INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C1','math',4,2,'u5',2,'꺾은선그래프의 뜻 — 시간에 따라 변화하는 양을 점으로 표시하고 그 점들을 선분으로 이어 그린 그래프로, 막대그래프보다 변화하는 모습을 알아보기 쉽다',ARRAY['4수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C2','math',4,2,'u5',2,'가로·세로와 눈금 읽기 — 가로·세로가 무엇을 나타내는지와 세로 눈금 한 칸의 크기를 먼저 확인하고 점의 값과 두 때의 차를 읽는다',ARRAY['4수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C3','math',4,2,'u5',2,'사이 값 짐작과 물결선 — 이웃한 두 점을 이은 선분으로 조사하지 않은 때의 값을 짐작하고, 물결선으로 필요 없는 부분을 줄이면 변화가 뚜렷하게 보인다',ARRAY['4수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C4','math',4,2,'u5',3,'나타내는 다섯 걸음 — 제목, 가로·세로에 나타낼 것, 눈금의 단위, 세로 눈금 한 칸의 크기를 정한 뒤 점을 찍고 가로 눈금의 순서대로 선분으로 잇는다',ARRAY['4수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C5','math',4,2,'u5',3,'눈금 한 칸 정하기 — 가장 큰 값까지 나타낼 수 있고 값이 눈금 위에 오도록 자료에 알맞게 세로 눈금 한 칸을 정하며, 한 칸이 클수록 변화가 덜 뚜렷하다',ARRAY['4수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C6','math',4,2,'u5',4,'물결선의 자리 — 물결선은 0과 가장 작은 값 사이에 넣고, 자료의 수 범위 안에 넣으면 기울어진 정도가 사실과 달라진다',ARRAY['4수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C7','math',4,2,'u5',4,'값이 큰 자료 나타내기 — 값이 크거나 서로 가까운 자료는 물결선과 작은 눈금 칸으로 나타내고, 아주 큰 자료는 공학 도구로 쉽고 빠르게 나타낸다',ARRAY['4수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C8','math',4,2,'u5',5,'값과 변화 읽기 — 꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것, 평평하면 변하지 않은 것으로 읽고 두 때의 차를 구한다',ARRAY['4수04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C9','math',4,2,'u5',5,'가장 많이 변한 때와 앞날 짐작 — 선분이 가파를수록 많이 변한 것이고, 가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾으며, 흐름으로 앞날을 짐작한다',ARRAY['4수04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C10','math',4,2,'u5',6,'자료를 모아 나타내기 — 시간에 따라 달라지는 주제를 정하고 믿을 수 있는 누리집에서 최근 자료를 출처와 함께 모아 표로 정리한 뒤 꺾은선그래프로 나타내 읽는다',ARRAY['4수04-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C11','math',4,2,'u5',7,'알맞은 그래프 고르기 — 그림그래프·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞고, 자료를 모은 목적과 특성을 함께 생각해 고르며 이어진 자료를 막대로 나타내도 틀린 것은 아니다',ARRAY['4수04-03']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C12','math',4,2,'u5',8,'두 자료를 한 그래프에 — 같은 가로 눈금 위에 두 값을 찍고 선의 색과 이름표로 구별하며, 두 값의 차와 변화를 견주고, 물결선을 쓴 그래프와 쓰지 않은 그래프 모두 맞다',ARRAY['4수04-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X01','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C4']::text[],'가로와 세로를 바꾸어 읽거나 바꾸어 정한다 — 가로에 양을, 세로에 때를 놓는다','가로는 때, 세로는 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X02','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C5','M4-2-u5-C8']::text[],'세로 눈금 한 칸의 크기를 확인하지 않고 눈금 칸 수를 그대로 값으로 읽는다','눈금 한 칸이 얼마인지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X03','math',4,'u5',ARRAY['M4-2-u5-C1']::text[],'꺾은선그래프와 막대그래프·그림그래프를 구별하지 못한다','점과 선분으로 이었는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X04','math',4,'u5',ARRAY['M4-2-u5-C3']::text[],'조사하지 않은 때의 값은 전혀 알 수 없다고 하거나 이웃한 한쪽 값을 그대로 쓴다','이웃한 두 점을 이은 선분 위에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X05','math',4,'u5',ARRAY['M4-2-u5-C3','M4-2-u5-C6','M4-2-u5-C7']::text[],'물결선을 쓰면 값이 바뀌거나 물결선 아래 값이 사라진다고 생각한다 — 물결선의 쓰임을 모른다','물결선은 필요 없는 부분만 줄임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X06','math',4,'u5',ARRAY['M4-2-u5-C1','M4-2-u5-C4']::text[],'점을 가로 눈금의 순서대로 잇지 않거나 곡선으로 잇거나 잇지 않아도 된다고 생각한다','순서대로, 선분으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X07','math',4,'u5',ARRAY['M4-2-u5-C5']::text[],'세로 눈금 한 칸의 크기를 자료에 맞지 않게 정한다 — 가장 큰 값까지 못 나타내거나 값이 눈금 사이에 온다','가장 큰 값까지, 눈금 위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X08','math',4,'u5',ARRAY['M4-2-u5-C3','M4-2-u5-C5','M4-2-u5-C7']::text[],'세로 눈금 한 칸이 크든 작든 변화가 똑같이 보인다고 생각한다','한 칸이 작을수록 뚜렷') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X09','math',4,'u5',ARRAY['M4-2-u5-C6']::text[],'물결선을 자료의 수 범위 안이나 가장 큰 값 근처에 넣는다','0과 가장 작은 값 사이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X10','math',4,'u5',ARRAY['M4-2-u5-C8','M4-2-u5-C9']::text[],'오른쪽 위로 올라가면 줄어든 것, 아래로 내려가면 늘어난 것으로 거꾸로 읽는다','오른쪽 위 = 늘어남') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X11','math',4,'u5',ARRAY['M4-2-u5-C9']::text[],'가장 많이 변한 때를 늘어난 곳에서만 찾는다 — 줄어든 것도 변한 것임을 놓친다','줄어든 것도 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X12','math',4,'u5',ARRAY['M4-2-u5-C8','M4-2-u5-C9']::text[],'점이 가장 높은(값이 가장 큰) 때를 가장 많이 늘어나거나 변한 때로 생각한다 — 높이와 기울기를 섞는다','높이가 아니라 기울기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X13','math',4,'u5',ARRAY['M4-2-u5-C8']::text[],'선분이 평평한 곳(변하지 않은 때)을 읽지 못한다','평평하면 변화 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X14','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C7','M4-2-u5-C8']::text[],'두 때의 차를 구할 때 다른 때의 값을 쓰거나 차 대신 합을 구하거나 받아내림을 틀린다','묻는 두 때의 값으로 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X15','math',4,'u5',ARRAY['M4-2-u5-C10']::text[],'시간과 관계없는 자료(지역별·학교별 등)를 꺾은선그래프의 조사 주제로 고른다','시간에 따라 달라지는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X16','math',4,'u5',ARRAY['M4-2-u5-C10']::text[],'자료를 아무 곳에서나·오래된 것으로 모으거나 출처를 적지 않아도 된다고 생각한다','믿을 수 있는 곳, 최근, 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X17','math',4,'u5',ARRAY['M4-2-u5-C11']::text[],'자료를 모은 목적과 특성을 생각하지 않고 그래프를 고른다 — 항목끼리 견주는 자료에 꺾은선그래프를 고르거나 한 그래프가 언제나 좋다고 한다','견주기인지 변화인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X18','math',4,'u5',ARRAY['M4-2-u5-C11']::text[],'이어진 자료를 막대그래프로 나타내면 틀린 것이라고 생각한다','틀린 것은 아님, 쓰임이 다름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X19','math',4,'u5',ARRAY['M4-2-u5-C12']::text[],'두 자료를 나타낸 그래프에서 선(이름표)을 바꾸어 읽거나 두 값의 차를 잘못 읽는다','이름표로 선을 먼저 가리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X20','math',4,'u5',ARRAY['M4-2-u5-C12']::text[],'물결선을 쓴 그래프와 쓰지 않은 그래프 가운데 하나만 맞다고 생각한다','둘 다 맞음, 뚜렷함만 다름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X21','math',4,'u5',ARRAY['M4-2-u5-C1','M4-2-u5-C2','M4-2-u5-C3','M4-2-u5-C4','M4-2-u5-C5','M4-2-u5-C6','M4-2-u5-C7','M4-2-u5-C8','M4-2-u5-C9','M4-2-u5-C10','M4-2-u5-C11','M4-2-u5-C12']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못↔바르게, 늘어난↔줄어든','물음의 핵심 낱말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X22','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C5','M4-2-u5-C9','M4-2-u5-C11']::text[],'그래프의 모양(선분의 기울기·점의 높이)만 보고 판단한다 — 세로 눈금 한 칸과 수를 읽지 않아 같은 자료를 다른 자료로 보거나, 가파르게 보이는 곳을 가장 많이 변한 때로 고른다(익힘 75 퐁당·지도서 393 건우)','모양 말고 눈금의 수를 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X23','math',4,'u5',ARRAY['M4-2-u5-C11']::text[],'같은 자료라도 수집 목적에 따라 알맞은 그래프가 달라질 수 있음을 모른다 — 채원(막대)·도윤(꺾은선) 가운데 한 사람만 맞다고 하거나, 월별·연도별 자료면 목적과 상관없이 언제나 꺾은선그래프라고 한다(지도서 375·401·403)','비교하려는지, 변화를 보려는지 목적부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X24','math',4,'u5',ARRAY['M4-2-u5-C7']::text[],'공학 도구로 나타낼 때 자료를 정확히 입력하지 않아도 된다고 하거나, 물결선·눈금 간격 설정이 달라도 그래프가 똑같이 나온다고 생각한다(지도서 372·388·389)','정확한 수 입력, 설정에 따라 모양이 달라짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X25','math',4,'u5',ARRAY['M4-2-u5-C9','M4-2-u5-C12']::text[],'앞날을 짐작할 때 그래프 전체의 흐름이 아니라 일부 구간(평평한 몇 해, 마지막 두 점)만 보고 짐작한다(지도서 393 예상 반응)','처음부터 끝까지 전체 흐름 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#1','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',1,'mc','auto','「준비하기」 — 조사한 자료의 수량을 막대 모양으로 나타낸 그래프를 무엇이라고 하나요?',ARRAY['M4-2-u5-X03']::text[],true,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"「준비하기」 — 조사한 자료의 수량을 막대 모양으로 나타낸 그래프를 무엇이라고 하나요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["4학년 1학기 「막대그래프」에서 배운 그래프예요.","배우고 싶어 하는 악기별 학생 수처럼 수량을 막대 모양으로 나타내요.","막대의 길이가 길수록 학생 수가 많아요."],"variant_rule":{"alt":[{"stem":"「스스로 준비 학습」 — 좋아하는 운동 종목별 학생 수를 조사한 표를 막대그래프로 나타내려고 해요. 가로에 운동 종목을 나타낸다면 세로에는 무엇을 나타내야 하나요?","options":[{"t":"학생 수","correct":true},{"t":"운동 종목","mis":"M4-2-u5-X01"},{"t":"합계","mis":"M4-2-u5-X21"},{"t":"막대의 색깔","mis":"M4-2-u5-X03"}],"explanation":["표의 항목은 배구, 야구, 축구, 핸드볼이에요.","가로에 운동 종목을 나타내면 세로에는 그 수량인 학생 수를 나타내요.","그래서 세로는 학생 수예요."],"asset":{"type":"picg","only":"table","head":"운동 종목","cols":["배구","야구","축구","핸드볼"],"counts":[5,7,11,4],"vh":"학생 수","unit":"명","title":"좋아하는 운동 종목별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#2','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',2,'mc','auto','「단원 도입」 — 환경 전시관에서 「미세 먼지 나쁨 일수 2017년 20일, 2021년 18일」을 보았어요. 연도별 미세 먼지 나쁨 일수의 변화를 알아보기 쉽게 나타내려면 이 단원에서 배우는 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],true,'{"seq":2,"concept":"M4-2-u5-C1","difficulty":2,"kind":"mc","stem":"「단원 도입」 — 환경 전시관에서 「미세 먼지 나쁨 일수 2017년 20일, 2021년 18일」을 보았어요. 연도별 미세 먼지 나쁨 일수의 변화를 알아보기 쉽게 나타내려면 이 단원에서 배우는 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["단원 핵심 질문은 「시간에 따른 변화를 알아보기 쉽도록 어떻게 나타낼까요?」예요.","연도별 미세 먼지 나쁨 일수는 시간에 따라 달라지는 자료예요.","시간에 따른 변화를 알아보기 쉬운 그래프는 꺾은선그래프예요."],"variant_rule":{"alt":[{"stem":"「단원 도입」 — 자외선 지수 매우 높음 일수가 4월에 4일, 8월에 17일이었어요. 8월은 4월보다 며칠 더 많았나요?","options":[{"t":"13일","correct":true},{"t":"21일","mis":"M4-2-u5-X14"},{"t":"4일","mis":"M4-2-u5-X14"},{"t":"17일","mis":"M4-2-u5-X14"}],"explanation":["두 때의 값만 써서 빼요.","17 − 4 = 13이에요.","8월은 4월보다 13일 더 많았어요."]},{"stem":"「단원 도입」 — 해수면 높이가 2018년에 27 cm, 2022년에 32 cm였어요. 2022년은 2018년보다 몇 cm 더 높아졌나요?","options":[{"t":"5 cm","correct":true},{"t":"59 cm","mis":"M4-2-u5-X14"},{"t":"27 cm","mis":"M4-2-u5-X14"},{"t":"32 cm","mis":"M4-2-u5-X14"}],"explanation":["두 해의 값만 써서 빼요.","32 − 27 = 5예요.","해수면은 5 cm 더 높아졌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#3','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C2',1,'mc','auto','「수학익힘」 — 「월별 나무의 키」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 「월별 나무의 키」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 나무의 키","correct":true},{"t":"가로: 나무의 키, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 나무의 키, 세로: 나무의 키","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월을, 세로에는 나무의 키를 cm 단위로 나타냈어요.","가로: 월, 세로: 나무의 키예요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 「날짜별 꽃병의 물 높이」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 날짜, 세로: 꽃병의 물 높이","correct":true},{"t":"가로: 꽃병의 물 높이, 세로: 날짜","mis":"M4-2-u5-X01"},{"t":"가로: 날짜, 세로: 날짜","mis":"M4-2-u5-X01"},{"t":"가로: 꽃병의 물 높이, 세로: 꽃병의 물 높이","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 날짜를, 세로에는 꽃병의 물 높이를 cm 단위로 나타냈어요.","가로: 날짜, 세로: 꽃병의 물 높이예요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이"}},{"stem":"「수학익힘」 — 「월별 선인장의 키」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 선인장의 키","correct":true},{"t":"가로: 선인장의 키, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 선인장의 키, 세로: 선인장의 키","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월을, 세로에는 선인장의 키를 cm 단위로 나타냈어요.","가로: 월, 세로: 선인장의 키예요."],"asset":{"type":"lgraph","xs":["5","6","7","8"],"series":[{"vals":[7,10,12,16]}],"step":1,"ymax":17,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#4','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C2',1,'sa','auto','「개념 쏙」 — 지유가 나무의 키를 나타낸 꺾은선그래프에서 세로 눈금 5칸이 50 cm를 나타내요. 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u5-C2","difficulty":1,"kind":"sa","stem":"「개념 쏙」 — 지유가 나무의 키를 나타낸 꺾은선그래프에서 세로 눈금 5칸이 50 cm를 나타내요. 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 5칸이 50 cm예요.","한 칸은 50 ÷ 5로 구해요.","세로 눈금 한 칸은 10 cm를 나타내요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 그래프에서 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 눈금 5칸이 5 cm예요.","한 칸은 5 ÷ 5 = 1이에요.","세로 눈금 한 칸은 1 cm를 나타내요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이"}},{"stem":"「수학익힘」 — 그래프에서 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 5칸이 50 cm예요.","한 칸은 50 ÷ 5 = 10이에요.","세로 눈금 한 칸은 10 cm를 나타내요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#5','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C3',2,'sa','auto','「생각 톡」 — 지유가 나무의 키를 두 달마다 쟀어요. 6월에는 재지 않았어요. 꺾은선그래프에서 5월과 7월의 두 점을 이은 선분을 보고 짐작하면 6월의 나무의 키는 약 몇 cm였을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C3","difficulty":2,"kind":"sa","stem":"「생각 톡」 — 지유가 나무의 키를 두 달마다 쟀어요. 6월에는 재지 않았어요. 꺾은선그래프에서 5월과 7월의 두 점을 이은 선분을 보고 짐작하면 6월의 나무의 키는 약 몇 cm였을까요? 숫자로 쓰세요.","answer":["110"],"explanation":["5월의 나무의 키는 100 cm, 7월의 나무의 키는 120 cm예요.","6월은 5월과 7월의 한가운데예요.","그래서 약 110 cm였을 것이라고 짐작해요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3","5","7","9","11"],"counts":[85,100,120,145,170],"vh":"나무의 키","unit":"cm","total":false,"title":"월별 나무의 키"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 그래프를 보고 짐작하면 8월의 나무의 키는 약 몇 cm였을까요? 숫자로 쓰세요.","answer":["120"],"explanation":["7월은 110 cm, 9월은 130 cm예요.","8월은 두 달의 한가운데예요.","8월의 나무의 키는 약 120 cm였을 거예요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}},{"stem":"「수학익힘」 — 그래프를 보고 짐작하면 오후 2시 30분의 가로등의 그림자 길이는 약 몇 cm였을까요? 숫자로 쓰세요.","answer":["70"],"explanation":["오후 2시는 50 cm, 오후 3시는 90 cm예요.","2시 30분은 두 시각의 한가운데예요.","두 점을 이은 선분 위에서 읽으면 약 70 cm예요."],"asset":{"type":"lgraph","xs":["1","2","3","4"],"series":[{"vals":[40,50,90,100]}],"step":10,"ymax":100,"ylab":"(cm)","xlab":"(시)","every":5,"title":"시각별 가로등의 그림자 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#6','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',2,'mc','auto','「생각 톡」 — 지유의 나무의 키를 가 그래프는 막대로, 나 그래프는 점과 선분으로 나타냈어요. 두 그래프의 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X03']::text[],true,'{"seq":6,"concept":"M4-2-u5-C1","difficulty":2,"kind":"mc","stem":"「생각 톡」 — 지유의 나무의 키를 가 그래프는 막대로, 나 그래프는 점과 선분으로 나타냈어요. 두 그래프의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 그래프 모두 월별 나무의 키를 나타냈어요.","correct":true},{"t":"두 그래프 모두 점들을 선분으로 이었어요.","mis":"M4-2-u5-X03"},{"t":"두 그래프 모두 막대로 나타냈어요.","mis":"M4-2-u5-X03"},{"t":"두 그래프가 나타낸 자료가 서로 달라요.","mis":"M4-2-u5-X03"}],"explanation":["같은 자료를 두 가지 그래프로 나타냈어요.","가 그래프는 막대로, 나 그래프는 점으로 표시하고 그 점들을 선분으로 이었어요.","같은 점은 둘 다 월별 나무의 키를 나타낸다는 거예요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 가로등의 그림자 길이를 막대그래프와 꺾은선그래프로 나타냈어요. 두 그래프의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"막대그래프는 막대로, 꺾은선그래프는 점과 선분으로 나타냈어요.","correct":true},{"t":"나타낸 자료가 서로 달라요.","mis":"M4-2-u5-X03"},{"t":"꺾은선그래프에는 세로 눈금이 없어요.","mis":"M4-2-u5-X03"},{"t":"막대그래프만 시각별 그림자 길이를 나타내요.","mis":"M4-2-u5-X03"}],"explanation":["두 그래프 모두 시각별 가로등의 그림자 길이를 나타내요.","막대그래프는 막대로, 꺾은선그래프는 점을 찍고 선분으로 이었어요.","나타낸 방법이 달라요."],"asset":{"type":"lgraph","xs":["1","2","3","4"],"series":[{"vals":[40,50,90,100]}],"step":10,"ymax":100,"ylab":"(cm)","xlab":"(시)","every":5,"title":"시각별 가로등의 그림자 길이","mode":"bar"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#7','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',2,'mc','auto','「생각 톡」 — 나무의 키가 시간에 따라 어떻게 변하는지 더 알아보기 쉬운 그래프와 그 이유로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03','M4-2-u5-X12']::text[],false,'{"seq":7,"concept":"M4-2-u5-C1","difficulty":2,"kind":"mc","stem":"「생각 톡」 — 나무의 키가 시간에 따라 어떻게 변하는지 더 알아보기 쉬운 그래프와 그 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"꺾은선그래프 — 나무의 키는 계속 변화하므로 점들을 선분으로 이어 나타내는 것이 알아보기 쉬워서","correct":true},{"t":"막대그래프 — 막대가 길수록 키가 커서","mis":"M4-2-u5-X17"},{"t":"두 그래프가 똑같이 알아보기 쉬워서 고를 수 없어요.","mis":"M4-2-u5-X03"},{"t":"꺾은선그래프 — 점이 막대보다 위에 찍혀서","mis":"M4-2-u5-X12"}],"explanation":["나무의 키는 시간에 따라 계속 변해요.","점들을 선분으로 이으면 선분이 기울어진 모양으로 변화가 한눈에 보여요.","그래서 꺾은선그래프가 더 알아보기 쉬워요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#8','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C3',2,'mc','auto','「개념 쏙」 — 시각별 온실 안의 온도를 두 꺾은선그래프로 나타냈어요. 다 그래프는 물결선 없이 0부터 세로 눈금 한 칸을 1 °C로, 라 그래프(아래)는 물결선(≈)을 넣고 세로 눈금 한 칸을 0.1 °C로 나타냈어요. 온도가 변화하는 모습이 더 뚜렷하게 나타나는 그래프와 그 이유는 어느 것인가요?',ARRAY['M4-2-u5-X08','M4-2-u5-X05']::text[],false,'{"seq":8,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 시각별 온실 안의 온도를 두 꺾은선그래프로 나타냈어요. 다 그래프는 물결선 없이 0부터 세로 눈금 한 칸을 1 °C로, 라 그래프(아래)는 물결선(≈)을 넣고 세로 눈금 한 칸을 0.1 °C로 나타냈어요. 온도가 변화하는 모습이 더 뚜렷하게 나타나는 그래프와 그 이유는 어느 것인가요?","options":[{"t":"라 그래프 — 세로 눈금 한 칸이 나타내는 크기가 작아서","correct":true},{"t":"다 그래프 — 0부터 나타내서","mis":"M4-2-u5-X08"},{"t":"라 그래프 — 온도가 더 높아서","mis":"M4-2-u5-X05"},{"t":"두 그래프가 똑같이 뚜렷해요.","mis":"M4-2-u5-X08"}],"explanation":["두 그래프는 같은 온도를 나타내요 — 물결선을 써도 값은 그대로예요.","라 그래프는 물결선으로 필요 없는 부분을 줄이고 한 칸을 0.1 °C로 작게 했어요.","그래서 라 그래프에서 변화가 더 뚜렷해요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[20.0,20.5,21.0,22.0,20.5]}],"step":0.1,"ymax":22.2,"ylab":"(°C)","xlab":"(시)","y0":20.0,"wave":true,"every":5,"title":"시각별 온실 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#9','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',1,'mc','auto','「개념 쏙」 — 시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?',ARRAY['M4-2-u5-X03','M4-2-u5-X05']::text[],true,'{"seq":9,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["나 그래프처럼 점을 찍고 선분으로 이은 그래프예요.","이런 그래프를 꺾은선그래프라고 해요.","시간에 따른 변화를 알아보기 쉬워요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 그래프처럼 시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["월별 선인장의 키를 점으로 표시했어요.","그 점들을 선분으로 이었어요.","이런 그래프를 꺾은선그래프라고 해요."],"asset":{"type":"lgraph","xs":["5","6","7","8"],"series":[{"vals":[7,10,12,16]}],"step":1,"ymax":17,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_basic#10','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C3',3,'error','auto','「수학익힘」 — 가로등의 그림자 길이를 나타낸 그래프를 보고 세 사람이 이야기했어요. 잘못 이야기한 사람은 누구인가요?',ARRAY['M4-2-u5-X04','M4-2-u5-X21']::text[],false,'{"seq":10,"concept":"M4-2-u5-C3","difficulty":3,"kind":"error","stem":"「수학익힘」 — 가로등의 그림자 길이를 나타낸 그래프를 보고 세 사람이 이야기했어요. 잘못 이야기한 사람은 누구인가요?","options":[{"t":"정후 — 「오후 2시 30분의 가로등의 그림자 길이는 100 cm였을 것 같아.」","correct":true,"mis_target":"M4-2-u5-X04"},{"t":"서윤 — 「두 그래프 모두 세로 눈금 한 칸은 10 cm를 나타내.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「가로등의 그림자 길이는 오후 4시에 오후 3시보다 10 cm 더 늘어났어.」","mis":"M4-2-u5-X21"}],"explanation":["오후 2시는 50 cm, 오후 3시는 90 cm예요.","오후 2시 30분은 두 점을 이은 선분 위에서 읽어 약 70 cm예요 — 100 cm는 오후 4시의 값이에요.","정후가 잘못 이야기했어요. 지아의 말처럼 100 − 90 = 10 cm 늘어났어요."],"asset":{"type":"lgraph","xs":["1","2","3","4"],"series":[{"vals":[40,50,90,100]}],"step":10,"ymax":100,"ylab":"(cm)","xlab":"(시)","every":5,"title":"시각별 가로등의 그림자 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#1','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C3',2,'ox','auto','「개념 쏙」 — 꺾은선그래프에서 물결선(≈)을 사용하면 필요 없는 부분을 줄여서 변화하는 모습이 잘 보여요.',ARRAY['M4-2-u5-X05']::text[],false,'{"seq":1,"concept":"M4-2-u5-C3","difficulty":2,"kind":"ox","stem":"「개념 쏙」 — 꺾은선그래프에서 물결선(≈)을 사용하면 필요 없는 부분을 줄여서 변화하는 모습이 잘 보여요.","answer":"O","reason_options":[{"t":"물결선으로 필요 없는 부분을 줄이고 눈금 한 칸을 작게 할 수 있어서","correct":true},{"t":"물결선을 쓰면 자료의 값이 바뀌어서","mis":"M4-2-u5-X05"}],"mis":"M4-2-u5-X05","explanation":["온실 안의 온도는 20 °C에서 22 °C 사이예요.","물결선으로 0과 20 사이를 줄이면 한 칸을 작게 잡을 수 있어요.","값은 그대로이고 변화만 뚜렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#2','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',2,'mc','auto','「확인 문제」 — 꽃병의 물 높이를 날짜별로 조사하여 나타낸 꺾은선그래프예요. 세로는 무엇을 나타내나요?',ARRAY['M4-2-u5-X01','M4-2-u5-X02','M4-2-u5-X03']::text[],false,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":2,"kind":"mc","stem":"「확인 문제」 — 꽃병의 물 높이를 날짜별로 조사하여 나타낸 꺾은선그래프예요. 세로는 무엇을 나타내나요?","options":[{"t":"꽃병의 물 높이","correct":true},{"t":"날짜","mis":"M4-2-u5-X01"},{"t":"1 cm","mis":"M4-2-u5-X02"},{"t":"꽃병의 수","mis":"M4-2-u5-X03"}],"explanation":["세로 눈금 옆에 적힌 것이 세로가 나타내는 것이에요.","가로는 날짜, 세로는 꽃병의 물 높이를 나타내요.","세로 눈금 한 칸은 1 cm예요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#3','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',3,'sa','auto','「수학익힘」 — 8월의 선인장의 키는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 8월의 선인장의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["세로 눈금 한 칸은 1 cm예요.","8월의 점을 따라 세로 눈금을 읽어요.","8월의 선인장의 키는 16 cm예요."],"asset":{"type":"lgraph","xs":["5","6","7","8"],"series":[{"vals":[7,10,12,16]}],"step":1,"ymax":17,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장의 키"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 9월의 나무의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["세로 눈금 한 칸은 10 cm예요.","9월의 점을 따라 세로 눈금을 읽어요.","9월의 나무의 키는 130 cm예요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}},{"stem":"「확인 문제」 — 4일의 꽃병의 물 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 한 칸은 1 cm예요.","4일의 점을 따라 세로 눈금을 읽어요.","4일의 꽃병의 물 높이는 10 cm예요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#4','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C3',3,'mc','auto','「개념 쏙」 라 그래프 — 오전 10시의 온도는 몇 °C인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X05']::text[],true,'{"seq":4,"concept":"M4-2-u5-C3","difficulty":3,"kind":"mc","stem":"「개념 쏙」 라 그래프 — 오전 10시의 온도는 몇 °C인가요?","options":[{"t":"22 °C","correct":true},{"t":"22.1 °C","mis":"M4-2-u5-X02"},{"t":"20 °C","mis":"M4-2-u5-X05"},{"t":"21.9 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 10시의 점을 따라 세로 눈금을 읽어요.","오전 10시의 온도는 22 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[20.0,20.5,21.0,22.0,20.5]}],"step":0.1,"ymax":22.2,"ylab":"(°C)","xlab":"(시)","y0":20.0,"wave":true,"every":5,"title":"시각별 온실 안의 온도"},"variant_rule":{"alt":[{"stem":"「개념 쏙」 라 그래프 — 오전 8시의 온도는 몇 °C인가요?","options":[{"t":"20.5 °C","correct":true},{"t":"20.6 °C","mis":"M4-2-u5-X02"},{"t":"5 °C","mis":"M4-2-u5-X05"},{"t":"20.4 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 8시의 점을 따라 세로 눈금을 읽어요.","오전 8시의 온도는 20.5 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[20.0,20.5,21.0,22.0,20.5]}],"step":0.1,"ymax":22.2,"ylab":"(°C)","xlab":"(시)","y0":20.0,"wave":true,"every":5,"title":"시각별 온실 안의 온도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#5','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C3',3,'mc','auto','「개념 쏙」 라 그래프 — 오전 9시 30분에는 온도를 재지 않았어요. 오전 9시 30분의 온실 안의 온도는 약 몇 °C였을까요?',ARRAY['M4-2-u5-X04']::text[],false,'{"seq":5,"concept":"M4-2-u5-C3","difficulty":3,"kind":"mc","stem":"「개념 쏙」 라 그래프 — 오전 9시 30분에는 온도를 재지 않았어요. 오전 9시 30분의 온실 안의 온도는 약 몇 °C였을까요?","options":[{"t":"약 21.5 °C","correct":true},{"t":"약 21 °C","mis":"M4-2-u5-X04"},{"t":"약 22 °C","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["오전 9시는 21 °C, 오전 10시는 22 °C예요.","9시 30분은 두 시각의 한가운데예요.","두 점을 이은 선분 위에서 읽으면 약 21.5 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[20.0,20.5,21.0,22.0,20.5]}],"step":0.1,"ymax":22.2,"ylab":"(°C)","xlab":"(시)","y0":20.0,"wave":true,"every":5,"title":"시각별 온실 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#6','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',3,'error','auto','「친구의 설명」 — 월별 나무의 키를 나타낸 꺾은선그래프를 보고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M4-2-u5-X01','M4-2-u5-X21']::text[],false,'{"seq":6,"concept":"M4-2-u5-C2","difficulty":3,"kind":"error","stem":"「친구의 설명」 — 월별 나무의 키를 나타낸 꺾은선그래프를 보고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"은우 — 「가로는 나무의 키, 세로는 월을 나타내고 세로 눈금 한 칸은 1 cm를 나타내.」","correct":true,"mis_target":"M4-2-u5-X01"},{"t":"하랑 — 「가로는 월, 세로는 나무의 키를 나타내.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「세로 눈금 5칸이 50 cm이니까 한 칸은 10 cm야.」","mis":"M4-2-u5-X21"}],"explanation":["가로 눈금 아래에는 3, 5, 7, 9, 11(월)이 적혀 있어요.","가로는 월, 세로는 나무의 키예요. 세로 눈금 5칸이 50 cm라서 한 칸은 10 cm예요.","은우는 가로와 세로를 바꾸고 눈금 한 칸도 확인하지 않았어요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#7','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',3,'match','auto','「수학익힘」 — 월별 나무의 키를 나타낸 꺾은선그래프를 보고, 왼쪽과 알맞은 것을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u5-C2","difficulty":3,"kind":"match","stem":"「수학익힘」 — 월별 나무의 키를 나타낸 꺾은선그래프를 보고, 왼쪽과 알맞은 것을 이어 보세요.","pairs":[{"l":"가로가 나타내는 것","r":"월"},{"l":"세로가 나타내는 것","r":"나무의 키"},{"l":"세로 눈금 한 칸의 크기","r":"10 cm"},{"l":"짐작한 8월의 나무의 키","r":"약 120 cm"}],"mis":"M4-2-u5-X01","explanation":["가로 눈금 아래에는 월이, 세로에는 나무의 키가 있어요.","세로 눈금 5칸이 50 cm라서 한 칸은 10 cm예요.","8월은 7월(110 cm)과 9월(130 cm)의 한가운데라 약 120 cm예요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#8','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',4,'sa','auto','「개념 쏙」 라 그래프 — 온실 안의 온도가 가장 높을 때와 가장 낮을 때의 차는 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u5-C2","difficulty":4,"kind":"sa","stem":"「개념 쏙」 라 그래프 — 온실 안의 온도가 가장 높을 때와 가장 낮을 때의 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","가장 높을 때는 오전 10시의 22 °C, 가장 낮을 때는 오전 7시의 20 °C예요.","22 − 20 = 2 — 2 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[20.0,20.5,21.0,22.0,20.5]}],"step":0.1,"ymax":22.2,"ylab":"(°C)","xlab":"(시)","y0":20.0,"wave":true,"every":5,"title":"시각별 온실 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#9','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C3',4,'mc','auto','「개념 쏙」 — 다 그래프(0부터, 한 칸 1 °C)에서는 오전 8시의 온도가 20 °C인지 20.5 °C인지 알아보기 어려워요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X05','M4-2-u5-X08','M4-2-u5-X02']::text[],false,'{"seq":9,"concept":"M4-2-u5-C3","difficulty":4,"kind":"mc","stem":"「개념 쏙」 — 다 그래프(0부터, 한 칸 1 °C)에서는 오전 8시의 온도가 20 °C인지 20.5 °C인지 알아보기 어려워요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"세로 눈금 한 칸이 1 °C라서 0.5 °C만큼의 차이가 아주 작게 보여서","correct":true},{"t":"물결선이 없어서 온도가 바뀌어서","mis":"M4-2-u5-X05"},{"t":"한 칸이 크든 작든 변화는 똑같이 보여서","mis":"M4-2-u5-X08"},{"t":"눈금 칸 수가 바로 온도라서","mis":"M4-2-u5-X02"}],"explanation":["다 그래프는 0부터 22 °C까지를 한 칸 1 °C로 나타냈어요.","0.5 °C는 반 칸이라 점이 거의 같은 높이로 보여요.","라 그래프처럼 물결선을 넣고 한 칸을 0.1 °C로 하면 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L02_challenge#10','math',4,2,'u5','L02','tb_g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C1',4,'essay','teacher','「수학에 퐁당」 — 월별 나무의 키를 나타낸 꺾은선그래프를 보고 가로와 세로가 나타내는 것, 세로 눈금 한 칸의 크기를 쓰고, 꺾은선그래프를 사용했을 때 편리한 점을 막대그래프와 견주어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C1","difficulty":4,"kind":"essay","stem":"「수학에 퐁당」 — 월별 나무의 키를 나타낸 꺾은선그래프를 보고 가로와 세로가 나타내는 것, 세로 눈금 한 칸의 크기를 쓰고, 꺾은선그래프를 사용했을 때 편리한 점을 막대그래프와 견주어 써 보세요.","answer_guide":{"answer":"예: 가로는 월, 세로는 나무의 키를 나타내고, 세로 눈금 한 칸은 10 cm를 나타낸다. 꺾은선그래프는 막대그래프와 달리 점들을 선분으로 이어서 시간에 따른 자료의 변화를 한눈에 알아보기 쉽고, 7월과 9월 사이처럼 조사하지 않은 8월의 키도 약 120 cm로 예상할 수 있다.","scoring_points":["가로 월·세로 나무의 키를 바르게 썼는가","세로 눈금 한 칸 10 cm를 썼는가","변화를 한눈에 / 사이 값 예상을 편리한 점으로 썼는가"]},"explanation":["가로는 월, 세로는 나무의 키예요.","세로 눈금 5칸이 50 cm라서 한 칸은 10 cm예요.","꺾은선그래프는 변화를 한눈에 보고 사이 값도 예상할 수 있어요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#1','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',1,'mc','auto','「생각 톡」 — 어느 지역의 미세 먼지 나쁨 일수를 연도별로 조사한 표를 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":1,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 어느 지역의 미세 먼지 나쁨 일수를 연도별로 조사한 표를 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?","options":[{"t":"가로: 연도, 세로: 일수","correct":true},{"t":"가로: 일수, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 일수, 세로: 일수","mis":"M4-2-u5-X01"}],"explanation":["표에는 연도와 그해의 일수가 있어요.","꺾은선그래프의 가로에는 때(연도)를, 세로에는 양(일수)을 나타내요.","가로: 연도, 세로: 일수예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"「문제 척」 — 선인장 줄기의 길이를 매월 1일에 조사한 표를 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?","options":[{"t":"가로: 월, 세로: 길이","correct":true},{"t":"가로: 길이, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 길이, 세로: 길이","mis":"M4-2-u5-X01"}],"explanation":["표에는 월과 그달의 줄기 길이가 있어요.","가로에는 때(월)를, 세로에는 양(길이)을 나타내요.","가로: 월, 세로: 길이예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[10,18,26,30,32],"vh":"길이","unit":"cm","total":false,"title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#2','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',1,'sa','auto','「생각 톡」 — 미세 먼지 나쁨 일수 표를 꺾은선그래프로 나타낼 때 세로 눈금은 얼마까지 나타내어야 할까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"「생각 톡」 — 미세 먼지 나쁨 일수 표를 꺾은선그래프로 나타낼 때 세로 눈금은 얼마까지 나타내어야 할까요? 숫자로 쓰세요.","answer":["25"],"explanation":["표의 값은 20, 21, 25, 5, 18이에요.","가장 큰 값까지 나타낼 수 있어야 해요.","가장 큰 값이 25이므로 25까지 나타내어야 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#3','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',1,'mc','auto','「생각 톡」 — 미세 먼지 나쁨 일수 표를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위는 무엇으로 나타내어야 할까요?',ARRAY['M4-2-u5-X01','M4-2-u5-X21','M4-2-u5-X02']::text[],false,'{"seq":3,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 미세 먼지 나쁨 일수 표를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위는 무엇으로 나타내어야 할까요?","options":[{"t":"가로: 년, 세로: 일","correct":true},{"t":"가로: 일, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 일수","mis":"M4-2-u5-X21"},{"t":"가로: 년, 세로: cm","mis":"M4-2-u5-X02"}],"explanation":["가로는 연도라서 단위는 년이에요.","세로는 일수라서 단위는 일이에요.","「연도·일수」는 이름, 「년·일」은 단위예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#4','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',1,'sa','auto','「생각 톡」 — 미세 먼지 나쁨 일수 표를 세로 눈금이 25칸인 그래프에 나타내려고 해요. 가장 큰 값 25까지 나타낼 수 있도록 세로 눈금 한 칸의 크기를 정하면 몇 일로 하면 좋을까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"「생각 톡」 — 미세 먼지 나쁨 일수 표를 세로 눈금이 25칸인 그래프에 나타내려고 해요. 가장 큰 값 25까지 나타낼 수 있도록 세로 눈금 한 칸의 크기를 정하면 몇 일로 하면 좋을까요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 눈금은 25까지 나타내야 해요.","세로 눈금이 25칸이니 한 칸을 1일로 하면 25칸이 25일이에요.","세로 눈금 한 칸은 1일로 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#5','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',2,'mc','auto','「개념 쏙」 — 꺾은선그래프로 나타내는 방법이에요. ① 알맞은 제목을 써요. ② 가로와 세로에 각각 무엇을 나타낼지 정해요. ③ 가로와 세로 눈금의 단위를 정해요. ④ 가장 큰 값까지 나타낼 수 있도록 세로 눈금 한 칸의 크기를 정해요. ⑤에 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X01']::text[],false,'{"seq":5,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 꺾은선그래프로 나타내는 방법이에요. ① 알맞은 제목을 써요. ② 가로와 세로에 각각 무엇을 나타낼지 정해요. ③ 가로와 세로 눈금의 단위를 정해요. ④ 가장 큰 값까지 나타낼 수 있도록 세로 눈금 한 칸의 크기를 정해요. ⑤에 알맞은 것은 어느 것인가요?","options":[{"t":"가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 이 점들을 선분으로 이어요.","correct":true},{"t":"가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 이 점들을 곡선으로 이어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 잇지 않아요.","mis":"M4-2-u5-X06"},{"t":"가로와 세로를 바꾸어 다시 그려요.","mis":"M4-2-u5-X01"}],"explanation":["①~④로 그래프의 틀을 만들어요.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍어요.","점들을 가로 눈금의 순서대로 선분으로 이어 완성해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#6','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',2,'sa','auto','「개념 쏙」 — 표를 보고 꺾은선그래프로 나타냈어요. 2020년의 점은 0에서 세로 눈금 몇 칸 위에 찍었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C4","difficulty":2,"kind":"sa","stem":"「개념 쏙」 — 표를 보고 꺾은선그래프로 나타냈어요. 2020년의 점은 0에서 세로 눈금 몇 칸 위에 찍었나요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 한 칸은 1일이에요.","2020년의 미세 먼지 나쁨 일수는 5일이에요.","그래서 0에서 5칸 위에 점을 찍어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[20,21,25,5,18]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"「개념 쏙」 — 표를 보고 꺾은선그래프로 나타냈어요. 2019년의 점은 0에서 세로 눈금 몇 칸 위에 찍었나요? 숫자로 쓰세요.","answer":["25"],"explanation":["세로 눈금 한 칸은 1일이에요.","2019년의 미세 먼지 나쁨 일수는 25일이에요.","그래서 0에서 25칸 위에 점을 찍어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[20,21,25,5,18]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#7','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',2,'mc','auto','「문제 척」 — 선인장 줄기의 길이 표를 꺾은선그래프로 나타낼 때 세로 눈금 한 칸의 크기로 알맞은 것과 그 까닭은 어느 것인가요?',ARRAY['M4-2-u5-X07','M4-2-u5-X08','M4-2-u5-X02']::text[],false,'{"seq":7,"concept":"M4-2-u5-C5","difficulty":2,"kind":"mc","stem":"「문제 척」 — 선인장 줄기의 길이 표를 꺾은선그래프로 나타낼 때 세로 눈금 한 칸의 크기로 알맞은 것과 그 까닭은 어느 것인가요?","options":[{"t":"2 cm — 자료의 값이 모두 짝수라서","correct":true},{"t":"3 cm — 가장 큰 값이 32라서","mis":"M4-2-u5-X07"},{"t":"10 cm — 한 칸이 클수록 변화가 뚜렷해서","mis":"M4-2-u5-X08"},{"t":"32 cm — 가장 큰 값으로 한 칸을 정해서","mis":"M4-2-u5-X02"}],"explanation":["표의 값은 10, 18, 26, 30, 32 cm로 모두 짝수예요.","한 칸을 2 cm로 하면 모든 값이 눈금 위에 와요.","3 cm로 하면 10, 26, 32가 눈금 사이에 와서 알맞지 않아요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[10,18,26,30,32],"vh":"길이","unit":"cm","total":false,"title":"월별 선인장 줄기의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#8','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',2,'sa','auto','「문제 척」 — 선인장 줄기의 길이를 세로 눈금 한 칸이 2 cm인 꺾은선그래프로 나타냈어요. 9월의 점은 0에서 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C4","difficulty":2,"kind":"sa","stem":"「문제 척」 — 선인장 줄기의 길이를 세로 눈금 한 칸이 2 cm인 꺾은선그래프로 나타냈어요. 9월의 점은 0에서 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["13"],"explanation":["세로 눈금 한 칸은 2 cm예요.","9월의 줄기 길이는 26 cm예요.","26 ÷ 2 = 13 — 13칸 위에 있어요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[10,18,26,30,32]}],"step":2,"ymax":34,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장 줄기의 길이"},"variant_rule":{"alt":[{"stem":"「문제 척」 — 선인장 줄기의 길이를 세로 눈금 한 칸이 2 cm인 꺾은선그래프로 나타냈어요. 11월의 점은 0에서 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["16"],"explanation":["세로 눈금 한 칸은 2 cm예요.","11월의 줄기 길이는 32 cm예요.","32 ÷ 2 = 16 — 16칸 위에 있어요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[10,18,26,30,32]}],"step":2,"ymax":34,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#9','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',2,'mc','auto','「수학익힘」 — 꺾은선그래프로 나타내는 방법이에요. 「가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고 이 점들을 □(으)로 이어 꺾은선그래프를 완성합니다.」 □ 안에 알맞은 말은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X03','M4-2-u5-X05']::text[],true,'{"seq":9,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 꺾은선그래프로 나타내는 방법이에요. 「가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고 이 점들을 □(으)로 이어 꺾은선그래프를 완성합니다.」 □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"선분","correct":true},{"t":"곡선","mis":"M4-2-u5-X06"},{"t":"막대","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["꺾은선그래프는 점들을 곧은 선으로 이어요.","두 점을 곧게 이은 선은 선분이에요.","□ 안에 알맞은 말은 선분이에요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["1","2","3","4","5"],"counts":[2,4,9,2,2],"vh":"일수","unit":"일","total":false,"title":"월별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 표를 꺾은선그래프로 나타낼 때 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"월별 미세 먼지 나쁨 일수","correct":true},{"t":"연도별 미세 먼지 나쁨 일수","mis":"M4-2-u5-X21"},{"t":"일수별 월","mis":"M4-2-u5-X01"},{"t":"미세 먼지","mis":"M4-2-u5-X21"}],"explanation":["표는 1월부터 5월까지 달마다 조사한 미세 먼지 나쁨 일수예요.","무엇을 무엇별로 조사했는지가 제목에 드러나야 해요.","제목은 「월별 미세 먼지 나쁨 일수」예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["1","2","3","4","5"],"counts":[2,4,9,2,2],"vh":"일수","unit":"일","total":false,"title":"월별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_basic#10','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',3,'mc','auto','「궁금해요」 — 친구가 월별 미세 먼지 나쁨 일수 표를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?',ARRAY['M4-2-u5-X07','M4-2-u5-X01','M4-2-u5-X09']::text[],false,'{"seq":10,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「궁금해요」 — 친구가 월별 미세 먼지 나쁨 일수 표를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점과 점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"세로 눈금 한 칸을 1일로 정했어요.","mis":"M4-2-u5-X07"},{"t":"가로에 월, 세로에 일수를 나타냈어요.","mis":"M4-2-u5-X01"},{"t":"2월과 3월 사이에 물결선이 없어요.","mis":"M4-2-u5-X09"}],"explanation":["꺾은선그래프는 점과 점을 선분으로 이어요.","곡선으로 이으면 자료의 수 사이의 값을 예상할 수 없고 잘못된 정보를 줘요.","가로 월·세로 일수, 한 칸 1일은 바르게 정했어요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[2,4,9,2,2]}],"step":1,"ymax":10,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 미세 먼지 나쁨 일수","curve":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#1','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',2,'ox','auto','「궁금해요」 — 꺾은선그래프에서 점과 점을 선분으로 잇지 않아도 돼요.',ARRAY['M4-2-u5-X06']::text[],false,'{"seq":1,"concept":"M4-2-u5-C4","difficulty":2,"kind":"ox","stem":"「궁금해요」 — 꺾은선그래프에서 점과 점을 선분으로 잇지 않아도 돼요.","answer":"X","reason_options":[{"t":"점과 점을 순서대로 선분으로 이어야 사이의 값을 예상할 수 있어서","correct":true},{"t":"점만 찍어도 값은 다 보여서","mis":"M4-2-u5-X06"}],"mis":"M4-2-u5-X06","explanation":["꺾은선그래프는 점들을 선분으로 이어 그린 그래프예요.","선분으로 이어야 변화와 사이 값을 알 수 있어요.","그래서 꼭 순서대로 선분으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#2','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',2,'mc','auto','「확인 문제」 — 시각별 운동장의 온도 표를 꺾은선그래프로 나타내려고 해요. 세로 눈금은 얼마까지 나타내어야 할까요?',ARRAY['M4-2-u5-X07','M4-2-u5-X01']::text[],false,'{"seq":2,"concept":"M4-2-u5-C5","difficulty":2,"kind":"mc","stem":"「확인 문제」 — 시각별 운동장의 온도 표를 꺾은선그래프로 나타내려고 해요. 세로 눈금은 얼마까지 나타내어야 할까요?","options":[{"t":"27 °C까지","correct":true},{"t":"25 °C까지","mis":"M4-2-u5-X07"},{"t":"20 °C까지","mis":"M4-2-u5-X07"},{"t":"오후 1시까지","mis":"M4-2-u5-X01"}],"explanation":["표의 값은 20, 22, 24, 25, 27 °C예요.","가장 큰 값까지 나타낼 수 있어야 해요.","가장 큰 값이 27 °C이므로 27 °C까지 나타내요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["오전 9","오전 10","오전 11","낮 12","오후 1"],"counts":[20,22,24,25,27],"vh":"온도","unit":"°C","total":false,"title":"시각별 운동장의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#3','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',3,'mc','auto','「궁금해요」 — 친구가 선인장 줄기의 길이 표를 보고 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07','M4-2-u5-X01']::text[],true,'{"seq":3,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「궁금해요」 — 친구가 선인장 줄기의 길이 표를 보고 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점을 가로 눈금의 순서대로 잇지 않았어요.","correct":true},{"t":"점을 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금 한 칸을 2 cm로 정했어요.","mis":"M4-2-u5-X07"},{"t":"가로와 세로를 바꾸어 나타냈어요.","mis":"M4-2-u5-X01"}],"explanation":["점은 7월, 8월, 9월, 10월, 11월 순서대로 이어야 해요.","이 그래프는 7월에서 9월로 건너뛰어 이었어요.","순서대로 잇지 않으면 변화를 잘못 알게 돼요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[10,18,26,30,32]}],"step":2,"ymax":34,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장 줄기의 길이","order":[0,2,1,3,4]},"variant_rule":{"alt":[{"stem":"「궁금해요」 — 친구가 날짜별 꽃병의 물 높이를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금 한 칸을 1 cm로 정했어요.","mis":"M4-2-u5-X07"},{"t":"가로에 날짜를 나타냈어요.","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 점을 찍은 다음 선분으로 이어요.","이 그래프는 점만 찍었어요.","선분으로 이어야 변화와 사이 값을 알 수 있어요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이","dots":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#4','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',3,'sa','auto','「확인 문제」 — 시각별 운동장의 온도를 나타낸 꺾은선그래프예요. 오후 1시의 온도는 오전 9시보다 몇 °C 더 높은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u5-C4","difficulty":3,"kind":"sa","stem":"「확인 문제」 — 시각별 운동장의 온도를 나타낸 꺾은선그래프예요. 오후 1시의 온도는 오전 9시보다 몇 °C 더 높은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세로 눈금 한 칸은 1 °C예요.","오전 9시는 20 °C, 오후 1시는 27 °C예요.","27 − 20 = 7 — 7 °C 더 높아요."],"asset":{"type":"lgraph","xs":["9","10","11","12","1"],"series":[{"vals":[20,22,24,25,27]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","y0":20,"wave":true,"every":5,"title":"시각별 운동장의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#5','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',3,'sa','auto','「문제 척」 — 선인장 줄기의 길이를 세로 눈금 한 칸이 2 cm인 그래프로 나타내려고 해요. 가장 큰 값 32 cm까지 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"「문제 척」 — 선인장 줄기의 길이를 세로 눈금 한 칸이 2 cm인 그래프로 나타내려고 해요. 가장 큰 값 32 cm까지 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.","answer":["16"],"explanation":["가장 큰 값은 11월의 32 cm예요.","한 칸이 2 cm이므로 32 ÷ 2 = 16이에요.","세로 눈금이 적어도 16칸 있어야 해요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[10,18,26,30,32],"vh":"길이","unit":"cm","total":false,"title":"월별 선인장 줄기의 길이"},"variant_rule":{"alt":[{"stem":"「생각 톡」 — 미세 먼지 나쁨 일수를 세로 눈금 한 칸이 1일인 그래프로 나타내려고 해요. 가장 큰 값까지 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.","answer":["25"],"explanation":["가장 큰 값은 2019년의 25일이에요.","한 칸이 1일이므로 25칸이 필요해요.","세로 눈금이 적어도 25칸 있어야 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#6','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',3,'error','auto','「친구의 설명」 — 미세 먼지 나쁨 일수 표(20일, 21일, 25일, 5일, 18일)를 꺾은선그래프로 나타낼 때 세로 눈금 한 칸의 크기를 잘못 정한 친구는 누구인가요?',ARRAY['M4-2-u5-X07','M4-2-u5-X21']::text[],false,'{"seq":6,"concept":"M4-2-u5-C5","difficulty":3,"kind":"error","stem":"「친구의 설명」 — 미세 먼지 나쁨 일수 표(20일, 21일, 25일, 5일, 18일)를 꺾은선그래프로 나타낼 때 세로 눈금 한 칸의 크기를 잘못 정한 친구는 누구인가요?","options":[{"t":"도윤 — 「한 칸을 2일로 하면 모든 값을 눈금 위에 나타낼 수 있어.」","correct":true,"mis_target":"M4-2-u5-X07"},{"t":"채원 — 「한 칸을 1일로 하고 25까지 나타낼래.」","mis":"M4-2-u5-X21"},{"t":"지유 — 「가장 큰 값 25까지 나타낼 수 있게 한 칸의 크기를 정해야 해.」","mis":"M4-2-u5-X21"}],"explanation":["한 칸을 2일로 하면 눈금은 0, 2, 4, …처럼 짝수만 있어요.","21, 25, 5는 홀수라 눈금 사이에 와요.","도윤이가 잘못 정했어요 — 이 표는 한 칸을 1일로 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#7','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',3,'mc','auto','「꼭 알아 둬요」 — 꺾은선그래프로 나타내는 다섯 걸음 가운데 순서를 바꾸어 마지막에 해도 되는 것은 어느 것인가요?',ARRAY['M4-2-u5-X07','M4-2-u5-X01','M4-2-u5-X06']::text[],false,'{"seq":7,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「꼭 알아 둬요」 — 꺾은선그래프로 나타내는 다섯 걸음 가운데 순서를 바꾸어 마지막에 해도 되는 것은 어느 것인가요?","options":[{"t":"알맞은 제목 쓰기","correct":true},{"t":"세로 눈금 한 칸의 크기 정하기","mis":"M4-2-u5-X07"},{"t":"가로와 세로에 무엇을 나타낼지 정하기","mis":"M4-2-u5-X01"},{"t":"점을 선분으로 잇기 전에 선분부터 긋기","mis":"M4-2-u5-X06"}],"explanation":["교과서에 「제목은 마지막에 써도 돼요.」라고 적혀 있어요.","눈금의 단위와 한 칸의 크기는 점을 찍기 전에 정해야 해요.","점은 찍은 다음에 선분으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#8','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',4,'sa','auto','「궁금해요」 — 미세 먼지 나쁨 일수(2017년 20일, 2018년 21일, 2019년 25일, 2020년 5일, 2021년 18일)를 세로 눈금 한 칸이 5일인 그래프로 나타내면, 점이 눈금 위에 오지 않는 연도는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u5-C5","difficulty":4,"kind":"sa","stem":"「궁금해요」 — 미세 먼지 나쁨 일수(2017년 20일, 2018년 21일, 2019년 25일, 2020년 5일, 2021년 18일)를 세로 눈금 한 칸이 5일인 그래프로 나타내면, 점이 눈금 위에 오지 않는 연도는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 칸이 5일이면 눈금은 0, 5, 10, 15, 20, 25예요.","20, 25, 5는 눈금 위에 오지만 21과 18은 눈금 사이에 와요.","눈금 위에 오지 않는 연도는 2018년과 2021년 — 2개예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#9','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',4,'mc','auto','「문제 척」 — 같은 선인장 줄기의 길이 자료를 세로 눈금 한 칸이 2 cm인 그래프와 10 cm인 그래프로 나타냈어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X08','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C5","difficulty":4,"kind":"mc","stem":"「문제 척」 — 같은 선인장 줄기의 길이 자료를 세로 눈금 한 칸이 2 cm인 그래프와 10 cm인 그래프로 나타냈어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 칸이 2 cm인 그래프에서 줄기 길이의 변화가 더 뚜렷하게 보여요.","correct":true},{"t":"한 칸이 10 cm인 그래프에서 변화가 더 뚜렷하게 보여요.","mis":"M4-2-u5-X08"},{"t":"두 그래프의 변화는 똑같이 보여요.","mis":"M4-2-u5-X08"},{"t":"두 그래프가 나타내는 줄기의 길이가 서로 달라요.","mis":"M4-2-u5-X05"}],"explanation":["두 그래프가 나타내는 값은 같아요.","한 칸이 작을수록 같은 변화도 더 많은 칸으로 나타나요.","그래서 한 칸이 2 cm인 그래프에서 변화가 더 뚜렷해요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[10,18,26,30,32]}],"step":2,"ymax":34,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장 줄기의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L03_challenge#10','math',4,2,'u5','L03','tb_g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',4,'essay','teacher','「문제 척」 — 선인장 줄기의 길이 표(7월 10 cm, 8월 18 cm, 9월 26 cm, 10월 30 cm, 11월 32 cm)를 꺾은선그래프로 나타내는 방법을 다섯 걸음으로 써 보세요. 세로 눈금 한 칸의 크기를 그렇게 정한 까닭도 함께 써요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C4","difficulty":4,"kind":"essay","stem":"「문제 척」 — 선인장 줄기의 길이 표(7월 10 cm, 8월 18 cm, 9월 26 cm, 10월 30 cm, 11월 32 cm)를 꺾은선그래프로 나타내는 방법을 다섯 걸음으로 써 보세요. 세로 눈금 한 칸의 크기를 그렇게 정한 까닭도 함께 써요.","answer_guide":{"answer":"예: ① 제목을 「월별 선인장 줄기의 길이」로 쓴다. ② 가로에는 월, 세로에는 길이를 나타낸다. ③ 가로 눈금의 단위는 월, 세로 눈금의 단위는 cm로 한다. ④ 자료의 값이 모두 짝수이므로 세로 눈금 한 칸을 2 cm로 하고 32 cm까지 나타낸다. ⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고 점들을 순서대로 선분으로 잇는다.","scoring_points":["제목·가로세로·단위를 차례로 썼는가","한 칸 2 cm와 그 까닭(모두 짝수)을 썼는가","점을 찍고 순서대로 선분으로 잇는다고 썼는가"]},"explanation":["제목, 가로·세로, 단위를 정해요.","모두 짝수이니 한 칸을 2 cm로 하면 값이 눈금 위에 와요.","점을 찍고 순서대로 선분으로 이어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[10,18,26,30,32],"vh":"길이","unit":"cm","total":false,"title":"월별 선인장 줄기의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#1','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',1,'mc','auto','「문제 척」 — 어느 지역의 인구수를 연도별로 조사한 표를 물결선을 사용한 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":1,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"「문제 척」 — 어느 지역의 인구수를 연도별로 조사한 표를 물결선을 사용한 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?","options":[{"t":"가로: 연도, 세로: 인구수","correct":true},{"t":"가로: 인구수, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 인구수, 세로: 인구수","mis":"M4-2-u5-X01"}],"explanation":["표에는 연도와 그해의 인구수가 있어요.","가로에는 때(연도)를, 세로에는 양(인구수)을 나타내요.","가로: 연도, 세로: 인구수예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[31,34,36,37,38],"vh":"인구수","unit":"만 명","total":false,"title":"연도별 인구수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 월별 해바라기의 키를 물결선을 사용하여 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?","options":[{"t":"가로: 월, 세로: 키","correct":true},{"t":"가로: 키, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 키, 세로: 키","mis":"M4-2-u5-X01"}],"explanation":["표에는 월과 그달의 해바라기 키가 있어요.","가로에는 때(월)를, 세로에는 양(키)을 나타내요.","가로: 월, 세로: 키예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6","7","8","9","10"],"counts":[180,183,186,190,193],"vh":"키","unit":"cm","total":false,"title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#2','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',1,'mc','auto','「문제 척」 — 인구수 표를 꺾은선그래프로 나타낼 때 물결선(≈)을 넣는다면 0부터 몇만 명 사이에 넣는 것이 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":2,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"「문제 척」 — 인구수 표를 꺾은선그래프로 나타낼 때 물결선(≈)을 넣는다면 0부터 몇만 명 사이에 넣는 것이 좋을까요?","options":[{"t":"0부터 31만 명 사이","correct":true},{"t":"34만 명과 36만 명 사이","mis":"M4-2-u5-X09"},{"t":"38만 명보다 위","mis":"M4-2-u5-X09"},{"t":"0부터 38만 명 사이","mis":"M4-2-u5-X09"}],"explanation":["표에서 가장 작은 값은 31만 명이에요.","물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄일 때 써요.","그래서 0부터 31만 명 사이에 넣어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[31,34,36,37,38],"vh":"인구수","unit":"만 명","total":false,"title":"연도별 인구수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 해바라기의 키 표를 꺾은선그래프로 나타낼 때 물결선을 넣는다면 0부터 몇 cm 사이에 넣는 것이 좋을까요?","options":[{"t":"0부터 180 cm 사이","correct":true},{"t":"186 cm와 190 cm 사이","mis":"M4-2-u5-X09"},{"t":"193 cm보다 위","mis":"M4-2-u5-X09"},{"t":"0부터 193 cm 사이","mis":"M4-2-u5-X09"}],"explanation":["표에서 가장 작은 값은 6월의 180 cm예요.","물결선은 0과 가장 작은 값 사이에 넣어요.","그래서 0부터 180 cm 사이에 넣어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6","7","8","9","10"],"counts":[180,183,186,190,193],"vh":"키","unit":"cm","total":false,"title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#3','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',1,'mc','auto','「문제 척」 — 인구수 표(31만, 34만, 36만, 37만, 38만 명)를 물결선을 사용한 꺾은선그래프로 나타낼 때 세로 눈금 한 칸은 몇만 명으로 나타내면 좋을까요?',ARRAY['M4-2-u5-X08','M4-2-u5-X07','M4-2-u5-X02']::text[],true,'{"seq":3,"concept":"M4-2-u5-C7","difficulty":1,"kind":"mc","stem":"「문제 척」 — 인구수 표(31만, 34만, 36만, 37만, 38만 명)를 물결선을 사용한 꺾은선그래프로 나타낼 때 세로 눈금 한 칸은 몇만 명으로 나타내면 좋을까요?","options":[{"t":"1만 명","correct":true},{"t":"10만 명","mis":"M4-2-u5-X08"},{"t":"3만 명","mis":"M4-2-u5-X07"},{"t":"31만 명","mis":"M4-2-u5-X02"}],"explanation":["자료의 값은 1만 명 단위로 달라요.","한 칸을 1만 명으로 하면 모든 값이 눈금 위에 오고 변화가 뚜렷해요.","3만 명으로 하면 34만, 37만, 38만 명이 눈금 사이에 와요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[31,34,36,37,38],"vh":"인구수","unit":"만 명","total":false,"title":"연도별 인구수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 해바라기의 키 표(180, 183, 186, 190, 193 cm)를 물결선을 사용한 꺾은선그래프로 나타낼 때 세로 눈금 한 칸은 몇 cm로 나타내면 좋을까요?","options":[{"t":"1 cm","correct":true},{"t":"10 cm","mis":"M4-2-u5-X08"},{"t":"3 cm","mis":"M4-2-u5-X07"},{"t":"180 cm","mis":"M4-2-u5-X02"}],"explanation":["183, 186, 190, 193은 1 cm 단위로 달라요.","한 칸을 1 cm로 하면 모든 값이 눈금 위에 와요.","3 cm로 하면 190, 193이 눈금 사이에 와요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6","7","8","9","10"],"counts":[180,183,186,190,193],"vh":"키","unit":"cm","total":false,"title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#4','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',1,'mc','auto','「디지털로 활동해요」 — 이지통계를 사용하여 연도별 다문화 가구 수를 꺾은선그래프로 나타냈어요. 이지통계를 사용했을 때 편리한 점은 어느 것인가요?',ARRAY['M4-2-u5-X24','M4-2-u5-X07','M4-2-u5-X20']::text[],false,'{"seq":4,"concept":"M4-2-u5-C7","difficulty":1,"kind":"mc","stem":"「디지털로 활동해요」 — 이지통계를 사용하여 연도별 다문화 가구 수를 꺾은선그래프로 나타냈어요. 이지통계를 사용했을 때 편리한 점은 어느 것인가요?","options":[{"t":"자료의 값이 큰 자료도 쉽고 빠르게 나타낼 수 있어요.","correct":true},{"t":"자료를 입력하지 않아도 그래프가 그려져요.","mis":"M4-2-u5-X24"},{"t":"값이 작은 자료만 나타낼 수 있어요.","mis":"M4-2-u5-X07"},{"t":"물결선을 쓴 그래프만 맞는 그래프가 돼요.","mis":"M4-2-u5-X20"}],"explanation":["다문화 가구 수는 33만부터 39만이 넘는 아주 큰 수예요.","이지통계에 정확한 수를 입력하고 꺾은선그래프를 고르면 쉽고 빠르게 그려 줘요.","그래서 값이 큰 자료도 쉽게 나타낼 수 있어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[334856,353803,367775,385219,399396],"vh":"가구 수","unit":"가구","total":false,"title":"연도별 다문화 가구 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#5','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',2,'sa','auto','「문제 척」 — 인구수를 물결선을 사용한 꺾은선그래프로 나타냈어요. 2020년의 점은 물결선 바로 위 30만 명 눈금에서 몇 칸 위에 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"「문제 척」 — 인구수를 물결선을 사용한 꺾은선그래프로 나타냈어요. 2020년의 점은 물결선 바로 위 30만 명 눈금에서 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["세로 눈금 한 칸은 1만 명이에요.","2020년의 인구수는 36만 명이에요.","36 − 30 = 6 — 30만 명 눈금에서 6칸 위에 있어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[31,34,36,37,38]}],"step":1,"ymax":40,"ylab":"(만 명)","xlab":"(년)","y0":30,"wave":true,"every":5,"title":"연도별 인구수"},"variant_rule":{"alt":[{"stem":"「문제 척」 — 인구수를 물결선을 사용한 꺾은선그래프로 나타냈어요. 2018년의 점은 물결선 바로 위 30만 명 눈금에서 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 눈금 한 칸은 1만 명이에요.","2018년의 인구수는 31만 명이에요.","31 − 30 = 1 — 1칸 위에 있어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[31,34,36,37,38]}],"step":1,"ymax":40,"ylab":"(만 명)","xlab":"(년)","y0":30,"wave":true,"every":5,"title":"연도별 인구수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#6','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',2,'mc','auto','「수학익힘」 — 월별 해바라기의 키를 물결선을 사용하여 나타냈어요. 물결선(≈)은 어디에 있나요?',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 월별 해바라기의 키를 물결선을 사용하여 나타냈어요. 물결선(≈)은 어디에 있나요?","options":[{"t":"세로 눈금 0과 180 사이","correct":true},{"t":"세로 눈금 186과 190 사이","mis":"M4-2-u5-X09"},{"t":"가로 눈금 8월과 9월 사이","mis":"M4-2-u5-X09"},{"t":"세로 눈금 193 위","mis":"M4-2-u5-X09"}],"explanation":["그래프의 맨 아래에 0이 있고 그 위에 물결선이 있어요.","물결선 바로 위 눈금은 180이에요.","물결선은 0과 180 사이의 필요 없는 부분을 줄인 거예요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[180,183,186,190,193]}],"step":1,"ymax":194,"ylab":"(cm)","xlab":"(월)","y0":180,"wave":true,"every":5,"title":"월별 해바라기의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#7','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',2,'sa','auto','「수학익힘」 — 물결선을 사용하여 나타낸 그래프예요. 9월의 해바라기의 키는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u5-C7","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 물결선을 사용하여 나타낸 그래프예요. 9월의 해바라기의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["190"],"explanation":["물결선 위 첫 눈금은 180 cm이고 한 칸은 1 cm예요.","9월의 점은 180 cm 눈금에서 10칸 위에 있어요.","9월의 해바라기의 키는 190 cm예요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[180,183,186,190,193]}],"step":1,"ymax":194,"ylab":"(cm)","xlab":"(월)","y0":180,"wave":true,"every":5,"title":"월별 해바라기의 키"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 물결선을 사용하여 나타낸 그래프예요. 8월의 해바라기의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["186"],"explanation":["물결선 위 첫 눈금은 180 cm이고 한 칸은 1 cm예요.","8월의 점은 180 cm 눈금에서 6칸 위에 있어요.","8월의 해바라기의 키는 186 cm예요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[180,183,186,190,193]}],"step":1,"ymax":194,"ylab":"(cm)","xlab":"(월)","y0":180,"wave":true,"every":5,"title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#8','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',2,'mc','auto','「성장 지원 평가」 — 인구수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때, 물결선 위 첫 눈금으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X09','M4-2-u5-X08']::text[],false,'{"seq":8,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「성장 지원 평가」 — 인구수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때, 물결선 위 첫 눈금으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"30만 명","correct":true},{"t":"35만 명","mis":"M4-2-u5-X09"},{"t":"20만 명","mis":"M4-2-u5-X08"},{"t":"38만 명","mis":"M4-2-u5-X09"}],"explanation":["가장 작은 값은 31만 명이에요 — 물결선 위 첫 눈금은 31만 명보다 작아야 해요.","35만이나 38만으로 시작하면 31만, 34만 명을 나타낼 수 없어요.","20만 명으로 시작하면 아랫부분이 많이 비어 변화가 덜 뚜렷해요 — 30만 명이 알맞아요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[31,34,36,37,38],"vh":"인구수","unit":"만 명","total":false,"title":"연도별 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#9','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',2,'mc','auto','「디지털로 활동해요」 — 연도별 다문화 가구 수(334856, 353803, 367775, 385219, 399396가구)를 직접 그려서 나타내기 어려운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X15','M4-2-u5-X24','M4-2-u5-X03']::text[],false,'{"seq":9,"concept":"M4-2-u5-C7","difficulty":2,"kind":"mc","stem":"「디지털로 활동해요」 — 연도별 다문화 가구 수(334856, 353803, 367775, 385219, 399396가구)를 직접 그려서 나타내기 어려운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료의 값이 아주 커서 눈금을 정하고 점을 찍기 어려워서","correct":true},{"t":"시간에 따라 달라지는 자료가 아니라서","mis":"M4-2-u5-X15"},{"t":"자료의 값을 어림해서 그려도 되기 때문에","mis":"M4-2-u5-X24"},{"t":"연도가 다섯 개뿐이라서","mis":"M4-2-u5-X03"}],"explanation":["가구 수는 여섯 자리 수로 아주 커요.","손으로 눈금 한 칸을 정하고 정확한 자리에 점을 찍기 어려워요.","이럴 때 공학 도구를 쓰면 쉽고 빠르게 나타낼 수 있어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[334856,353803,367775,385219,399396],"vh":"가구 수","unit":"가구","total":false,"title":"연도별 다문화 가구 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_basic#10','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',3,'mc','auto','「꼭 알아 둬요」 — 인구수 그래프에서 물결선을 34만 명과 36만 명 사이(자료의 수 범위 안)에 넣으면 어떻게 될까요?',ARRAY['M4-2-u5-X05','M4-2-u5-X09']::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":3,"kind":"mc","stem":"「꼭 알아 둬요」 — 인구수 그래프에서 물결선을 34만 명과 36만 명 사이(자료의 수 범위 안)에 넣으면 어떻게 될까요?","options":[{"t":"꺾은선의 기울어진 정도가 사실과 다르게 보여요.","correct":true},{"t":"값이 더 정확해져요.","mis":"M4-2-u5-X05"},{"t":"아무 문제가 없어요.","mis":"M4-2-u5-X09"},{"t":"35만 명이 0이 돼요.","mis":"M4-2-u5-X05"}],"explanation":["물결선은 자료의 수로 나타낼 필요가 없는 부분만 줄여요.","자료의 수 범위 안에 물결선을 넣으면 그 사이가 줄어들어 기울기가 사실과 달라져요.","그래서 물결선은 0과 가장 작은 값 사이에만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#1','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',2,'ox','auto','「꼭 알아 둬요」 — 물결선을 사용하여 필요 없는 부분을 생략해도 나타내고자 했던 자료는 변함이 없어요.',ARRAY['M4-2-u5-X05']::text[],false,'{"seq":1,"concept":"M4-2-u5-C6","difficulty":2,"kind":"ox","stem":"「꼭 알아 둬요」 — 물결선을 사용하여 필요 없는 부분을 생략해도 나타내고자 했던 자료는 변함이 없어요.","answer":"O","reason_options":[{"t":"물결선은 필요 없는 부분만 줄이고 값은 그대로 두어서","correct":true},{"t":"물결선 아래의 값은 모두 사라져서","mis":"M4-2-u5-X05"}],"mis":"M4-2-u5-X05","explanation":["물결선은 0과 가장 작은 값 사이처럼 필요 없는 부분을 생략해요.","자료의 값은 그대로예요.","그래프 전체가 줄어들어 보기 편해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#2','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',2,'mc','auto','「이런 활동도 있어요」 — 월별 영화관에 방문한 관람객 수 표를 꺾은선그래프로 나타내려고 해요. 물결선을 넣는다면 어디에 넣는 것이 좋을까요?',ARRAY['M4-2-u5-X09','M4-2-u5-X20']::text[],false,'{"seq":2,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「이런 활동도 있어요」 — 월별 영화관에 방문한 관람객 수 표를 꺾은선그래프로 나타내려고 해요. 물결선을 넣는다면 어디에 넣는 것이 좋을까요?","options":[{"t":"0부터 1650명 사이","correct":true},{"t":"1700명과 1750명 사이","mis":"M4-2-u5-X09"},{"t":"1800명보다 위","mis":"M4-2-u5-X09"},{"t":"넣으면 안 돼요","mis":"M4-2-u5-X20"}],"explanation":["표에서 가장 작은 값은 7월의 1650명이에요.","0부터 1650명 사이는 나타낼 필요가 없어요.","그래서 0부터 1650명 사이에 물결선을 넣어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4","5","6","7","8"],"counts":[1800,1700,1750,1650,1700],"vh":"관람객 수","unit":"명","total":false,"title":"월별 영화관에 방문한 관람객 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#3','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',3,'mc','auto','「수학에 퐁당」 — 이지통계로 나타내려는 연도별 농촌으로 돌아가는 가구 수 표예요. 가구 수가 가장 많은 해는 언제인가요?',ARRAY['M4-2-u5-X21']::text[],false,'{"seq":3,"concept":"M4-2-u5-C7","difficulty":3,"kind":"mc","stem":"「수학에 퐁당」 — 이지통계로 나타내려는 연도별 농촌으로 돌아가는 가구 수 표예요. 가구 수가 가장 많은 해는 언제인가요?","options":[{"t":"2021년","correct":true},{"t":"2020년","mis":"M4-2-u5-X21"},{"t":"2022년","mis":"M4-2-u5-X21"},{"t":"2018년","mis":"M4-2-u5-X21"}],"explanation":["여섯 자리 수는 높은 자리부터 견주어요.","363397이 가장 커요.","가구 수가 가장 많은 해는 2021년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[328343,317660,345205,363397,318769],"vh":"가구 수","unit":"가구","total":false,"title":"연도별 농촌으로 돌아가는 가구 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#4','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',3,'sa','auto','「디지털로 활동해요」 — 이지통계로 나타낸 연도별 다문화 가구 수 그래프의 세로 눈금이 0, 57000, 114000, 171000, 228000, 285000, 342000, 399000으로 57000씩 커져요. 399000은 0에서 세로 눈금 몇 칸 위인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"「디지털로 활동해요」 — 이지통계로 나타낸 연도별 다문화 가구 수 그래프의 세로 눈금이 0, 57000, 114000, 171000, 228000, 285000, 342000, 399000으로 57000씩 커져요. 399000은 0에서 세로 눈금 몇 칸 위인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세로 눈금 한 칸은 57000가구예요.","0부터 399000까지 눈금을 세면 57000, 114000, …, 399000이에요.","399000 ÷ 57000 = 7 — 7칸 위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#5','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',3,'mc','auto','「디지털로 활동해요」 — 친구와 같은 다문화 가구 수 자료를 이지통계로 나타냈는데 두 그래프의 모양이 달랐어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X24','M4-2-u5-X20','M4-2-u5-X05']::text[],false,'{"seq":5,"concept":"M4-2-u5-C7","difficulty":3,"kind":"mc","stem":"「디지털로 활동해요」 — 친구와 같은 다문화 가구 수 자료를 이지통계로 나타냈는데 두 그래프의 모양이 달랐어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물결선을 사용했는지와 세로 눈금 한 칸의 크기를 서로 다르게 정해서","correct":true},{"t":"설정이 달라도 그래프는 언제나 똑같이 나오니 한 사람이 자료를 잘못 입력했어요.","mis":"M4-2-u5-X24"},{"t":"둘 중 한 그래프는 틀린 그래프예요.","mis":"M4-2-u5-X20"},{"t":"물결선을 쓰면 가구 수가 바뀌어서","mis":"M4-2-u5-X05"}],"explanation":["같은 자료라도 물결선을 쓰거나 쓰지 않을 수 있어요.","세로 눈금 한 칸의 크기를 다르게 정하면 모양이 달라 보여요.","둘 다 맞을 수 있어요 — 단위를 너무 크지 않게 하면 변화가 더 잘 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#6','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',3,'error','auto','「수학익힘」 — 월별 해바라기의 키 표를 물결선을 사용한 꺾은선그래프로 나타내려고 해요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X09','M4-2-u5-X21']::text[],false,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":3,"kind":"error","stem":"「수학익힘」 — 월별 해바라기의 키 표를 물결선을 사용한 꺾은선그래프로 나타내려고 해요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「물결선을 186 cm와 190 cm 사이에 넣을래.」","correct":true,"mis_target":"M4-2-u5-X09"},{"t":"민서 — 「물결선은 0부터 180 cm 사이에 넣어.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「세로 눈금 한 칸은 1 cm로 할래.」","mis":"M4-2-u5-X21"}],"explanation":["물결선은 0과 가장 작은 값 사이에 넣어요.","186 cm와 190 cm 사이는 자료의 수 범위 안이에요.","준서처럼 넣으면 기울기가 사실과 달라져요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6","7","8","9","10"],"counts":[180,183,186,190,193],"vh":"키","unit":"cm","total":false,"title":"월별 해바라기의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#7','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',3,'sa','auto','「수학익힘」 — 물결선을 사용하여 나타낸 그래프예요. 10월의 해바라기의 키는 6월보다 몇 cm 더 큰가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 물결선을 사용하여 나타낸 그래프예요. 10월의 해바라기의 키는 6월보다 몇 cm 더 큰가요? 숫자로 쓰세요.","answer":["13"],"explanation":["6월은 180 cm, 10월은 193 cm예요.","두 달의 값만 써서 빼요.","193 − 180 = 13 — 13 cm 더 커요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[180,183,186,190,193]}],"step":1,"ymax":194,"ylab":"(cm)","xlab":"(월)","y0":180,"wave":true,"every":5,"title":"월별 해바라기의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#8','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',4,'mc','auto','「수학에 퐁당」 — 연도별 농촌으로 돌아가는 가구 수 표를 보고 답하세요. 전년도와 비교하여 가구 수가 가장 많이 줄어든 해는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X10','M4-2-u5-X12']::text[],false,'{"seq":8,"concept":"M4-2-u5-C7","difficulty":4,"kind":"mc","stem":"「수학에 퐁당」 — 연도별 농촌으로 돌아가는 가구 수 표를 보고 답하세요. 전년도와 비교하여 가구 수가 가장 많이 줄어든 해는 언제인가요?","options":[{"t":"2022년","correct":true},{"t":"2019년","mis":"M4-2-u5-X11"},{"t":"2020년","mis":"M4-2-u5-X10"},{"t":"2021년","mis":"M4-2-u5-X12"}],"explanation":["줄어든 해는 2019년(317660 − 328343)과 2022년(318769 − 363397)이에요.","2019년은 약 1만 가구, 2022년은 4만 가구가 넘게 줄었어요.","가장 많이 줄어든 해는 2022년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[328343,317660,345205,363397,318769],"vh":"가구 수","unit":"가구","total":false,"title":"연도별 농촌으로 돌아가는 가구 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#9','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',4,'essay','teacher','「성장 지원 평가」 — 어느 지역의 연도별 인구수 표(31만, 34만, 36만, 37만, 38만 명)를 물결선이 있는 꺾은선그래프로 나타내는 방법을 설명해 보세요. 물결선을 넣을 자리, 물결선 위 첫 눈금, 세로 눈금 한 칸의 크기를 꼭 써요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u5-C6","difficulty":4,"kind":"essay","stem":"「성장 지원 평가」 — 어느 지역의 연도별 인구수 표(31만, 34만, 36만, 37만, 38만 명)를 물결선이 있는 꺾은선그래프로 나타내는 방법을 설명해 보세요. 물결선을 넣을 자리, 물결선 위 첫 눈금, 세로 눈금 한 칸의 크기를 꼭 써요.","answer_guide":{"answer":"예: 가로에는 연도, 세로에는 인구수를 나타낸다. 가장 작은 값이 31만 명이므로 0부터 31만 명 사이에 물결선을 넣고, 물결선 위 첫 눈금을 30만 명으로 한다. 가장 큰 값이 38만 명이므로 세로 눈금 한 칸을 1만 명으로 하여 40만 명까지 나타내고, 연도별로 점을 찍어 선분으로 잇는다.","scoring_points":["물결선을 0과 31만 명 사이에 넣는다고 썼는가","물결선 위 첫 눈금(30만 명)과 한 칸(1만 명)을 썼는가","점을 찍고 선분으로 잇는다고 썼는가"]},"explanation":["가장 작은 값 31만 명 아래를 물결선으로 줄여요.","물결선 위를 30만 명부터, 한 칸을 1만 명으로 해요.","연도별로 점을 찍고 선분으로 이어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[31,34,36,37,38]}],"step":1,"ymax":40,"ylab":"(만 명)","xlab":"(년)","y0":30,"wave":true,"every":5,"title":"연도별 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L04_challenge#10','math',4,2,'u5','L04','tb_g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',4,'mc','auto','「궁금해요」 — 연도별 인구수 그래프에서 물결선을 쓴 그래프(30만 명부터, 한 칸 1만 명)와 물결선을 쓰지 않은 그래프(0부터, 한 칸 10만 명)를 바르게 견준 것은 어느 것인가요?',ARRAY['M4-2-u5-X20','M4-2-u5-X08','M4-2-u5-X05']::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":4,"kind":"mc","stem":"「궁금해요」 — 연도별 인구수 그래프에서 물결선을 쓴 그래프(30만 명부터, 한 칸 1만 명)와 물결선을 쓰지 않은 그래프(0부터, 한 칸 10만 명)를 바르게 견준 것은 어느 것인가요?","options":[{"t":"나타내는 인구수는 같고, 물결선을 쓴 그래프에서 변화가 더 뚜렷하게 보여요.","correct":true},{"t":"물결선을 쓴 그래프는 인구수가 줄어들어 보이니 틀린 그래프예요.","mis":"M4-2-u5-X20"},{"t":"물결선을 쓰지 않은 그래프에서 변화가 더 뚜렷해요.","mis":"M4-2-u5-X08"},{"t":"두 그래프가 나타내는 인구수가 서로 달라요.","mis":"M4-2-u5-X05"}],"explanation":["물결선은 값을 바꾸지 않아요.","0부터 한 칸 10만 명이면 31만~38만 명이 거의 평평하게 보여요.","물결선을 쓰고 한 칸을 1만 명으로 하면 변화가 뚜렷해요 — 둘 다 맞는 그래프예요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[31,34,36,37,38]}],"step":1,"ymax":40,"ylab":"(만 명)","xlab":"(년)","y0":30,"wave":true,"every":5,"title":"연도별 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#1','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'sa','auto','「개념 쏙」 — 7월의 일수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"「개념 쏙」 — 7월의 일수는 며칠인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["세로 눈금 한 칸은 1일이에요.","7월의 점을 따라 세로 눈금을 읽어요.","7월의 일수는 22일이에요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[4,17,18,22,17]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 8월의 일수는 며칠인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세로 눈금 한 칸은 1일이에요.","8월의 점을 따라 세로 눈금을 읽어요.","8월의 일수는 7일이에요."],"asset":{"type":"lgraph","xs":["5","6","7","8","9"],"series":[{"vals":[12,5,6,7,14]}],"step":1,"ymax":15,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 높음 일수"}},{"stem":"「수학익힘」 — 오후 7시의 방문자 수는 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["세로 눈금 한 칸은 1명이에요.","오후 7시의 점을 따라 세로 눈금을 읽어요.","오후 7시의 방문자 수는 20명이에요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[8,9,17,20,12]}],"step":1,"ymax":21,"ylab":"(명)","xlab":"(시)","every":5,"title":"시각별 방문자 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#2','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'mc','auto','「개념 쏙」 — 꺾은선그래프가 오른쪽 위로 올라가면 자료의 값은 어떻게 변한 것인가요?',ARRAY['M4-2-u5-X10','M4-2-u5-X13','M4-2-u5-X03']::text[],false,'{"seq":2,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 꺾은선그래프가 오른쪽 위로 올라가면 자료의 값은 어떻게 변한 것인가요?","options":[{"t":"늘어난 것","correct":true},{"t":"줄어든 것","mis":"M4-2-u5-X10"},{"t":"변하지 않은 것","mis":"M4-2-u5-X13"},{"t":"알 수 없어요","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 왼쪽에서 오른쪽으로 시간이 흘러요.","오른쪽 위로 올라가면 늘어난 것, 오른쪽 아래로 내려가면 줄어든 것이에요.","선분이 많이 기울어질수록 변화가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#3','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'mc','auto','「문제 척」 — 1인당 하루 물 사용량이 변하지 않은 때는 몇 년부터 몇 년까지인가요?',ARRAY['M4-2-u5-X13']::text[],false,'{"seq":3,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「문제 척」 — 1인당 하루 물 사용량이 변하지 않은 때는 몇 년부터 몇 년까지인가요?","options":[{"t":"2018년부터 2020년까지","correct":true},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2020년부터 2021년까지","mis":"M4-2-u5-X13"},{"t":"변하지 않은 때가 없어요.","mis":"M4-2-u5-X13"}],"explanation":["꺾은선그래프가 오른쪽 위로 올라가거나 아래로 내려가지 않은 때는 변화가 없는 때예요.","2018년, 2019년, 2020년의 사용량은 모두 295 L예요.","그래서 2018년부터 2020년까지 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[289,295,295,295,302]}],"step":1,"ymax":303,"ylab":"(L)","xlab":"(년)","y0":285,"wave":true,"every":5,"title":"연도별 1인당 하루 물 사용량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#4','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'mc','auto','「재미있는 수학」 땅따먹기 — 「연도별 우리나라의 우유 생산량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":4,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「재미있는 수학」 땅따먹기 — 「연도별 우리나라의 우유 생산량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 연도, 세로: 생산량","correct":true},{"t":"가로: 생산량, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 생산량, 세로: 생산량","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 연도를, 세로에는 생산량을 만 톤 단위로 나타냈어요.","가로: 연도, 세로: 생산량이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[204,205,209,203,198]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","y0":195,"wave":true,"every":5,"title":"연도별 우리나라의 우유 생산량"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 「시각별 마당에 쌓인 눈의 높이」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 높이","correct":true},{"t":"가로: 높이, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 높이, 세로: 높이","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각을, 세로에는 높이를 mm 단위로 나타냈어요.","가로: 시각, 세로: 높이예요."],"asset":{"type":"lgraph","xs":["11","12","1","2","3"],"series":[{"vals":[2,7,9,14,17]}],"step":1,"ymax":18,"ylab":"(mm)","xlab":"(시)","every":5,"title":"시각별 마당에 쌓인 눈의 높이"}},{"stem":"「수학익힘」 — 「연도별 1인당 쌀 소비량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 연도, 세로: 소비량","correct":true},{"t":"가로: 소비량, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 소비량, 세로: 소비량","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 연도를, 세로에는 소비량을 kg 단위로 나타냈어요.","가로: 연도, 세로: 소비량이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[61,59,58,57,57]}],"step":1,"ymax":62,"ylab":"(kg)","xlab":"(년)","y0":55,"wave":true,"every":5,"title":"연도별 1인당 쌀 소비량"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#5','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',2,'mc','auto','「개념 쏙」 — 전월과 비교하여 자외선 지수 매우 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],true,'{"seq":5,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 전월과 비교하여 자외선 지수 매우 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?","options":[{"t":"5월","correct":true},{"t":"7월","mis":"M4-2-u5-X12"},{"t":"8월","mis":"M4-2-u5-X10"},{"t":"6월","mis":"M4-2-u5-X21"}],"explanation":["꺾은선그래프가 오른쪽 위로 올라간 곳 가운데 선분이 가장 많이 기울어진 곳을 찾아요.","4월과 5월 사이가 4일에서 17일로 13일 늘어 가장 가팔라요.","가장 많이 늘어난 때는 5월이에요 — 일수가 가장 많은 7월과 헷갈리지 않아요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[4,17,18,22,17]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 전월과 비교하여 자외선 지수 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?","options":[{"t":"9월","correct":true},{"t":"5월","mis":"M4-2-u5-X12"},{"t":"6월","mis":"M4-2-u5-X10"},{"t":"7월","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 위로 올라간 곳은 6~7월, 7~8월, 8~9월이에요.","8월과 9월 사이가 7일에서 14일로 7일 늘어 가장 가팔라요.","가장 많이 늘어난 때는 9월이에요."],"asset":{"type":"lgraph","xs":["5","6","7","8","9"],"series":[{"vals":[12,5,6,7,14]}],"step":1,"ymax":15,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#6','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',2,'mc','auto','「개념 쏙」 — 자외선 지수 매우 높음 일수가 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10','M4-2-u5-X13']::text[],false,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 자외선 지수 매우 높음 일수가 어떻게 변하고 있나요?","options":[{"t":"4월부터 7월까지는 늘어났고 7월부터는 줄어들었어요.","correct":true},{"t":"4월부터 7월까지는 줄어들었고 7월부터는 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"4월부터 8월까지 계속 늘어났어요.","mis":"M4-2-u5-X13"},{"t":"4월부터 8월까지 변하지 않았어요.","mis":"M4-2-u5-X13"}],"explanation":["4월부터 7월까지 꺾은선그래프가 오른쪽 위로 올라가요.","7월부터 8월까지는 오른쪽 아래로 내려가요.","그래서 7월까지 늘어났다가 7월부터 줄어들었어요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[4,17,18,22,17]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 매우 높음 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#7','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',2,'mc','auto','「문제 척」 — 1인당 하루 물 사용량은 앞으로 어떻게 변화할까요? 알맞은 짐작과 그 이유는 어느 것인가요?',ARRAY['M4-2-u5-X25','M4-2-u5-X10','M4-2-u5-X04']::text[],false,'{"seq":7,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「문제 척」 — 1인당 하루 물 사용량은 앞으로 어떻게 변화할까요? 알맞은 짐작과 그 이유는 어느 것인가요?","options":[{"t":"더 많아질 것 — 꺾은선그래프가 전체적으로 오른쪽 위로 올라가고 있어서","correct":true},{"t":"변하지 않을 것 — 2018년부터 2020년까지 변화가 없어서","mis":"M4-2-u5-X25"},{"t":"줄어들 것 — 사용량이 300 L를 넘어서","mis":"M4-2-u5-X10"},{"t":"알 수 없어요 — 2022년은 조사하지 않아서","mis":"M4-2-u5-X04"}],"explanation":["2017년 289 L에서 2021년 302 L까지 전체 흐름을 봐요.","중간에 평평한 곳이 있지만 전체적으로 오른쪽 위로 올라가요.","그래서 앞으로 더 많아질 것이라고 짐작해요 — 물을 아껴 써야 해요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[289,295,295,295,302]}],"step":1,"ymax":303,"ylab":"(L)","xlab":"(년)","y0":285,"wave":true,"every":5,"title":"연도별 1인당 하루 물 사용량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#8','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',2,'sa','auto','「수학익힘」 — 도윤이가 집 앞마당에 쌓인 눈의 높이를 시각별로 재어 나타냈어요. 마당에 쌓인 눈의 높이가 오후 1시에는 오전 11시보다 몇 mm 더 높은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 도윤이가 집 앞마당에 쌓인 눈의 높이를 시각별로 재어 나타냈어요. 마당에 쌓인 눈의 높이가 오후 1시에는 오전 11시보다 몇 mm 더 높은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세로 눈금 한 칸은 1 mm예요.","오전 11시는 2 mm, 오후 1시는 9 mm예요.","9 − 2 = 7 — 7 mm 더 높아요."],"asset":{"type":"lgraph","xs":["11","12","1","2","3"],"series":[{"vals":[2,7,9,14,17]}],"step":1,"ymax":18,"ylab":"(mm)","xlab":"(시)","every":5,"title":"시각별 마당에 쌓인 눈의 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#9','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',2,'mc','auto','「수학익힘」 — 어느 식당의 방문자 수를 시각별로 나타낸 그래프예요. 전 시각과 비교하여 방문자 수가 가장 많이 늘어난 때는 몇 시인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],false,'{"seq":9,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 어느 식당의 방문자 수를 시각별로 나타낸 그래프예요. 전 시각과 비교하여 방문자 수가 가장 많이 늘어난 때는 몇 시인가요?","options":[{"t":"오후 6시","correct":true},{"t":"오후 7시","mis":"M4-2-u5-X12"},{"t":"오후 8시","mis":"M4-2-u5-X10"},{"t":"오후 5시","mis":"M4-2-u5-X21"}],"explanation":["전 시각보다 늘어난 수를 차례로 견주어요: 1명, 8명, 3명.","오후 5시에서 6시로 9명에서 17명이 되어 8명 늘었어요.","가장 많이 늘어난 때는 오후 6시예요 — 가장 많은 오후 7시가 아니에요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[8,9,17,20,12]}],"step":1,"ymax":21,"ylab":"(명)","xlab":"(시)","every":5,"title":"시각별 방문자 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_basic#10','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',3,'error','auto','「헷갈려요」 — 월별 최고 온도를 나타낸 꺾은선그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],false,'{"seq":10,"concept":"M4-2-u5-C9","difficulty":3,"kind":"error","stem":"「헷갈려요」 — 월별 최고 온도를 나타낸 꺾은선그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「전월과 비교하여 최고 온도가 가장 많이 변한 때는 가장 많이 늘어난 7월이야.」","correct":true,"mis_target":"M4-2-u5-X11"},{"t":"지유 — 「8월의 최고 온도는 36 °C야.」","mis":"M4-2-u5-X21"},{"t":"건우 — 「9월에는 전월보다 최고 온도가 6 °C 낮아졌어.」","mis":"M4-2-u5-X21"}],"explanation":["변화한 양은 늘어난 양과 줄어든 양을 모두 포함해요.","7월은 4 °C 늘었고, 9월은 6 °C, 10월은 5 °C 줄었어요.","가장 많이 변한 때는 9월이에요 — 서준이는 늘어난 곳만 보았어요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[30,34,36,30,25]}],"step":1,"ymax":37,"ylab":"(°C)","xlab":"(월)","y0":20,"wave":true,"every":5,"title":"월별 최고 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#1','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',2,'ox','auto','「헷갈려요」 — 꺾은선그래프에서 변화량이 가장 클 때는 자료의 값이 가장 많이 늘어난 때예요.',ARRAY['M4-2-u5-X11']::text[],false,'{"seq":1,"concept":"M4-2-u5-C9","difficulty":2,"kind":"ox","stem":"「헷갈려요」 — 꺾은선그래프에서 변화량이 가장 클 때는 자료의 값이 가장 많이 늘어난 때예요.","answer":"X","reason_options":[{"t":"변화량은 늘어난 양과 줄어든 양을 모두 포함해서","correct":true},{"t":"줄어든 것은 변화가 아니라서","mis":"M4-2-u5-X11"}],"mis":"M4-2-u5-X11","explanation":["늘어난 것도 줄어든 것도 모두 변한 거예요.","늘어난 정도와 줄어든 정도를 모두 확인해요.","오른쪽 위로든 아래로든 가장 많이 기울어진 선분을 찾아요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[30,34,36,30,25]}],"step":1,"ymax":37,"ylab":"(°C)","xlab":"(월)","y0":20,"wave":true,"every":5,"title":"월별 최고 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#2','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',2,'sa','auto','「수학익힘」 — 2018년의 소비량은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 2018년의 소비량은 몇 kg인가요? 숫자로 쓰세요.","answer":["61"],"explanation":["세로 눈금 한 칸은 1 kg이에요.","2018년의 점을 따라 세로 눈금을 읽어요.","2018년의 소비량은 61 kg이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[61,59,58,57,57]}],"step":1,"ymax":62,"ylab":"(kg)","xlab":"(년)","y0":55,"wave":true,"every":5,"title":"연도별 1인당 쌀 소비량"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 2020년의 소비량은 몇 kg인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["세로 눈금 한 칸은 1 kg이에요.","2020년의 점을 따라 세로 눈금을 읽어요.","2020년의 소비량은 58 kg이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[61,59,58,57,57]}],"step":1,"ymax":62,"ylab":"(kg)","xlab":"(년)","y0":55,"wave":true,"every":5,"title":"연도별 1인당 쌀 소비량"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#3','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',3,'mc','auto','「이런 활동도 있어요」 — 건우가 지유의 악기 연습 시간 그래프를 보고 「전날과 비교하여 지유의 악기 연습 시간이 가장 많이 변화한 때는 4일이야.」라고 말했어요. 바르게 고치면 몇 일인가요?',ARRAY['M4-2-u5-X22','M4-2-u5-X12','M4-2-u5-X13']::text[],false,'{"seq":3,"concept":"M4-2-u5-C9","difficulty":3,"kind":"mc","stem":"「이런 활동도 있어요」 — 건우가 지유의 악기 연습 시간 그래프를 보고 「전날과 비교하여 지유의 악기 연습 시간이 가장 많이 변화한 때는 4일이야.」라고 말했어요. 바르게 고치면 몇 일인가요?","options":[{"t":"5일","correct":true},{"t":"4일","mis":"M4-2-u5-X22"},{"t":"2일","mis":"M4-2-u5-X12"},{"t":"3일","mis":"M4-2-u5-X13"}],"explanation":["세로 눈금 한 칸은 2분이에요 — 모양만 보지 말고 수를 읽어요.","전날과 비교한 변화는 2일 10분, 3일 0분, 4일 20분, 5일 30분이에요.","가장 많이 변화한 때는 30분 늘어난 5일이에요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[50,60,60,40,70]}],"step":2,"ymax":72,"ylab":"(분)","xlab":"(일)","y0":40,"wave":true,"every":5,"title":"지유의 날짜별 악기 연습 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#4','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',3,'mc','auto','「수학익힘」 — 2023년도의 1인당 쌀 소비량은 어떻게 될지 알맞게 예상한 것은 어느 것인가요?',ARRAY['M4-2-u5-X10','M4-2-u5-X25','M4-2-u5-X04']::text[],false,'{"seq":4,"concept":"M4-2-u5-C9","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 2023년도의 1인당 쌀 소비량은 어떻게 될지 알맞게 예상한 것은 어느 것인가요?","options":[{"t":"줄어들 것 같아요 — 꺾은선그래프가 오른쪽 아래로 내려가고 있어서","correct":true},{"t":"늘어날 것 같아요 — 그래프가 오른쪽 아래로 내려가서","mis":"M4-2-u5-X10"},{"t":"변하지 않을 것 같아요 — 2021년과 2022년이 같아서","mis":"M4-2-u5-X25"},{"t":"알 수 없어요 — 2023년은 조사하지 않아서","mis":"M4-2-u5-X04"}],"explanation":["2018년 61 kg에서 2022년 57 kg까지 전체 흐름을 봐요.","꺾은선그래프가 전체적으로 오른쪽 아래로 내려가요.","그래서 2023년도에도 줄어들 것 같다고 예상해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[61,59,58,57,57]}],"step":1,"ymax":62,"ylab":"(kg)","xlab":"(년)","y0":55,"wave":true,"every":5,"title":"연도별 1인당 쌀 소비량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#5','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',3,'sa','auto','「확인 문제」 — 서준이의 날짜별 운동 시간이에요. 전날과 비교하여 운동을 가장 많이 한 날짜(전날보다 가장 많이 늘어난 날)는 며칠인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"「확인 문제」 — 서준이의 날짜별 운동 시간이에요. 전날과 비교하여 운동을 가장 많이 한 날짜(전날보다 가장 많이 늘어난 날)는 며칠인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 한 칸은 2분이에요.","전날보다 2일 8분, 3일 8분 늘고, 4일 12분 줄고, 5일 20분 늘었어요.","가장 많이 늘어난 날은 5일이에요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[30,38,46,34,54]}],"step":2,"ymax":56,"ylab":"(분)","xlab":"(일)","y0":30,"wave":true,"every":5,"title":"서준이의 날짜별 운동 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#6','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',3,'mc','auto','「확인 문제」 — 서준이가 운동을 적게 한 날짜부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X02']::text[],false,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"「확인 문제」 — 서준이가 운동을 적게 한 날짜부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"1일, 4일, 2일, 3일, 5일","correct":true},{"t":"1일, 2일, 3일, 4일, 5일","mis":"M4-2-u5-X21"},{"t":"5일, 3일, 2일, 4일, 1일","mis":"M4-2-u5-X21"},{"t":"4일, 1일, 2일, 3일, 5일","mis":"M4-2-u5-X02"}],"explanation":["운동 시간은 1일 30분, 2일 38분, 3일 46분, 4일 34분, 5일 54분이에요.","적은 것부터 30, 34, 38, 46, 54분이에요.","1일, 4일, 2일, 3일, 5일 순서예요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[30,38,46,34,54]}],"step":2,"ymax":56,"ylab":"(분)","xlab":"(일)","y0":30,"wave":true,"every":5,"title":"서준이의 날짜별 운동 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#7','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',3,'mc','auto','「수학에 퐁당」 — 차가운 물을 담은 컵의 무게를 5분마다 재어 나타낸 그래프예요. 알 수 있는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X10','M4-2-u5-X13']::text[],false,'{"seq":7,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"「수학에 퐁당」 — 차가운 물을 담은 컵의 무게를 5분마다 재어 나타낸 그래프예요. 알 수 있는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"컵의 무게가 무거워지다가 오전 10시 20분부터 변하지 않아요.","correct":true},{"t":"컵의 무게가 가벼워지다가 오전 10시 20분부터 변하지 않아요.","mis":"M4-2-u5-X10"},{"t":"컵의 무게가 오전 10시 25분까지 계속 무거워져요.","mis":"M4-2-u5-X13"},{"t":"오전 10시 5분에 컵이 가장 무거워요.","mis":"M4-2-u5-X10"}],"explanation":["공기 중의 수증기가 컵 표면에 달라붙어 무게가 변해요.","꺾은선그래프가 오른쪽 위로 올라가다가 오전 10시 20분부터는 평평해요.","무거워지다가 오전 10시 20분부터 변하지 않아요."],"asset":{"type":"lgraph","xs":["5","10","15","20","25"],"series":[{"vals":[221.5,221.9,222.2,222.5,222.5]}],"step":0.1,"ymax":222.6,"ylab":"(g)","xlab":"(분)","y0":221.5,"wave":true,"every":5,"title":"시각별 컵의 무게"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#8','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',4,'sa','auto','「헷갈려요」 — 월별 최고 온도를 나타낸 꺾은선그래프에서 전월과 비교하여 최고 온도가 가장 많이 변한 때에는 몇 °C 변했나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C9","difficulty":4,"kind":"sa","stem":"「헷갈려요」 — 월별 최고 온도를 나타낸 꺾은선그래프에서 전월과 비교하여 최고 온도가 가장 많이 변한 때에는 몇 °C 변했나요? 숫자로 쓰세요.","answer":["6"],"explanation":["전월과 비교한 변화: 7월 4 °C 오름, 8월 2 °C 오름, 9월 6 °C 내림, 10월 5 °C 내림.","늘어난 양과 줄어든 양을 모두 견주어요.","가장 많이 변한 때는 9월, 6 °C 변했어요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[30,34,36,30,25]}],"step":1,"ymax":37,"ylab":"(°C)","xlab":"(월)","y0":20,"wave":true,"every":5,"title":"월별 최고 온도"},"variant_rule":{"alt":[{"stem":"「이런 활동도 있어요」 — 지유의 악기 연습 시간 그래프에서 전날과 비교하여 연습 시간이 가장 많이 변화한 때에는 몇 분 변했나요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금 한 칸은 2분이에요.","전날과 비교한 변화: 10분, 0분, 20분, 30분이에요.","가장 많이 변화한 때는 5일, 30분이에요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[50,60,60,40,70]}],"step":2,"ymax":72,"ylab":"(분)","xlab":"(일)","y0":40,"wave":true,"every":5,"title":"지유의 날짜별 악기 연습 시간"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#9','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',4,'mc','auto','「재미있는 수학」 땅따먹기 — 우유 생산량이 전년도보다 줄어든 해를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X10','M4-2-u5-X12']::text[],false,'{"seq":9,"concept":"M4-2-u5-C8","difficulty":4,"kind":"mc","stem":"「재미있는 수학」 땅따먹기 — 우유 생산량이 전년도보다 줄어든 해를 모두 고른 것은 어느 것인가요?","options":[{"t":"2021년, 2022년","correct":true},{"t":"2022년","mis":"M4-2-u5-X21"},{"t":"2019년, 2020년","mis":"M4-2-u5-X10"},{"t":"2020년, 2021년, 2022년","mis":"M4-2-u5-X12"}],"explanation":["꺾은선그래프가 오른쪽 아래로 내려간 곳을 찾아요.","2020년 209만 톤에서 2021년 203만 톤, 2022년 198만 톤으로 내려가요.","줄어든 해는 2021년과 2022년이에요 — 가장 많은 2020년은 늘어난 해예요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[204,205,209,203,198]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","y0":195,"wave":true,"every":5,"title":"연도별 우리나라의 우유 생산량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L05_challenge#10','math',4,2,'u5','L05','tb_g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',4,'essay','teacher','「문제 척」 — 연도별 1인당 하루 물 사용량 그래프를 보고 앞으로 물 사용량이 어떻게 변화할지 그 이유와 함께 쓰고, 앞으로 우리는 물을 어떻게 사용해야 할지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C9","difficulty":4,"kind":"essay","stem":"「문제 척」 — 연도별 1인당 하루 물 사용량 그래프를 보고 앞으로 물 사용량이 어떻게 변화할지 그 이유와 함께 쓰고, 앞으로 우리는 물을 어떻게 사용해야 할지 써 보세요.","answer_guide":{"answer":"예: 물 사용량은 앞으로 더 많아질 것이다. 2018년부터 2020년까지는 변하지 않았지만 꺾은선그래프가 전체적으로 오른쪽 위로 올라가고 있기 때문이다. 물 사용량이 더 늘지 않도록 양치할 때 컵을 쓰는 것처럼 물을 아껴 써야 한다.","scoring_points":["더 많아질 것이라고 짐작했는가","전체적으로 오른쪽 위로 올라간다는 근거를 썼는가","물을 아껴 쓰는 방법을 썼는가"]},"explanation":["2017년 289 L에서 2021년 302 L로 전체적으로 올라가요.","평평한 몇 해만 보지 말고 전체 흐름을 봐요.","물을 아껴 쓰는 방법을 생각해요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[289,295,295,295,302]}],"step":1,"ymax":303,"ylab":"(L)","xlab":"(년)","y0":285,"wave":true,"every":5,"title":"연도별 1인당 하루 물 사용량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#1','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','「개념 쏙」 — 지유네 반은 지구 온난화로 인한 기후변화를 조사하려고 해요. 꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],false,'{"seq":1,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 지유네 반은 지구 온난화로 인한 기후변화를 조사하려고 해요. 꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"어느 지역의 연도별 폭염 일수","correct":true},{"t":"여러 지역의 폭염 일수","mis":"M4-2-u5-X15"},{"t":"우리 반 학생들이 좋아하는 계절","mis":"M4-2-u5-X15"},{"t":"강별 수질 오염 발생 횟수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","연도별 폭염 일수는 해마다 달라지는 자료예요.","여러 지역·좋아하는 계절·강별 자료는 시간에 따른 자료가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#2','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','「개념 쏙」 — 인터넷을 이용하여 자료를 수집할 때 주의해야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X16']::text[],false,'{"seq":2,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 인터넷을 이용하여 자료를 수집할 때 주의해야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"공식적인 누리집에서 최근 자료를 수집해요.","correct":true},{"t":"아무 누리집에서나 자료를 모아요.","mis":"M4-2-u5-X16"},{"t":"오래된 자료일수록 좋아요.","mis":"M4-2-u5-X16"},{"t":"자료의 출처는 적지 않아도 돼요.","mis":"M4-2-u5-X16"}],"explanation":["자료가 믿을 수 있는 곳에서 나왔는지 확인해요.","폭염 일수는 기상자료개방포털 누리집에서 최근 자료를 찾아요.","표 아래에 출처를 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#3','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','「수학익힘」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. 「조사하여 알고 싶은 □을/를 정합니다.」 □ 안에 알맞은 말은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":3,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. 「조사하여 알고 싶은 □을/를 정합니다.」 □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"주제","correct":true},{"t":"항목","mis":"M4-2-u5-X21"},{"t":"방법","mis":"M4-2-u5-X21"},{"t":"꺾은선그래프","mis":"M4-2-u5-X21"}],"explanation":["먼저 조사하여 알고 싶은 주제를 정해요.","그다음 주제에 따른 항목, 자료를 수집할 방법을 정해요.","마지막으로 수집한 자료를 꺾은선그래프로 나타내고 해석해요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. 「주제에 따른 □을/를 정합니다.」 □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"항목","correct":true},{"t":"주제","mis":"M4-2-u5-X21"},{"t":"방법","mis":"M4-2-u5-X21"},{"t":"꺾은선그래프","mis":"M4-2-u5-X21"}],"explanation":["주제를 정한 다음 주제에 따른 항목을 정해요.","연도별 폭염 일수라면 항목은 연도예요.","□ 안에 알맞은 말은 항목이에요."]},{"stem":"「수학익힘」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. 「자료를 수집할 □을/를 정하고 자료를 수집합니다.」 □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"방법","correct":true},{"t":"주제","mis":"M4-2-u5-X21"},{"t":"항목","mis":"M4-2-u5-X21"},{"t":"꺾은선그래프","mis":"M4-2-u5-X21"}],"explanation":["주제와 항목을 정한 다음 자료를 수집할 방법을 정해요.","인터넷을 이용하는 것도 한 방법이에요.","□ 안에 알맞은 말은 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#4','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','「개념 쏙」 — 수집한 연도별 폭염 일수 표를 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?',ARRAY['M4-2-u5-X01']::text[],false,'{"seq":4,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 수집한 연도별 폭염 일수 표를 꺾은선그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내어야 할까요?","options":[{"t":"가로: 연도, 세로: 일수","correct":true},{"t":"가로: 일수, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 일수, 세로: 일수","mis":"M4-2-u5-X01"}],"explanation":["표에는 2019년부터 2023년까지의 폭염 일수가 있어요.","가로에는 연도를, 세로에는 일수를 나타내요.","가로: 연도, 세로: 일수예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2019","2020","2021","2022","2023"],"counts":[15,4,18,10,19],"vh":"일수","unit":"일","total":false,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#5','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'sa','auto','「개념 쏙」 — 폭염 일수 표를 꺾은선그래프로 나타낼 때 세로 눈금은 얼마까지 나타내어야 할까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u5-C10","difficulty":2,"kind":"sa","stem":"「개념 쏙」 — 폭염 일수 표를 꺾은선그래프로 나타낼 때 세로 눈금은 얼마까지 나타내어야 할까요? 숫자로 쓰세요.","answer":["19"],"explanation":["표의 값은 15, 4, 18, 10, 19예요.","가장 큰 값까지 나타낼 수 있어야 해요.","가장 큰 값인 19까지 나타내어야 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2019","2020","2021","2022","2023"],"counts":[15,4,18,10,19],"vh":"일수","unit":"일","total":false,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#6','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'sa','auto','「개념 쏙」 — 2021년의 일수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C10","difficulty":2,"kind":"sa","stem":"「개념 쏙」 — 2021년의 일수는 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["세로 눈금 한 칸은 1일이에요.","2021년의 점을 따라 세로 눈금을 읽어요.","2021년의 일수는 18일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"},"variant_rule":{"alt":[{"stem":"「개념 쏙」 — 2023년의 일수는 며칠인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["세로 눈금 한 칸은 1일이에요.","2023년의 점을 따라 세로 눈금을 읽어요.","2023년의 일수는 19일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#7','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'mc','auto','「문제 척」 — 폭염 일수가 전년도와 비교하여 가장 많이 늘어난 때는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],false,'{"seq":7,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"「문제 척」 — 폭염 일수가 전년도와 비교하여 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2021년","correct":true},{"t":"2023년","mis":"M4-2-u5-X12"},{"t":"2020년","mis":"M4-2-u5-X10"},{"t":"2022년","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 위로 올라간 곳은 2020~2021년(14일), 2022~2023년(9일)이에요.","2020년 4일에서 2021년 18일로 가장 가파르게 올라가요.","가장 많이 늘어난 때는 2021년이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#8','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'mc','auto','「문제 척」 — 폭염 일수가 전년도와 비교하여 가장 많이 줄어든 때는 언제인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X10']::text[],false,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"「문제 척」 — 폭염 일수가 전년도와 비교하여 가장 많이 줄어든 때는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2022년","mis":"M4-2-u5-X21"},{"t":"2021년","mis":"M4-2-u5-X10"},{"t":"2019년","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 아래로 내려간 곳은 2019~2020년(11일), 2021~2022년(8일)이에요.","2019년 15일에서 2020년 4일로 가장 가파르게 내려가요.","가장 많이 줄어든 때는 2020년이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#9','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'mc','auto','「수학익힘」 — 연도별 태풍 발생 횟수 그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X13','M4-2-u5-X10']::text[],false,'{"seq":9,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 연도별 태풍 발생 횟수 그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"2018년과 2019년의 태풍 발생 횟수가 같아요.","correct":true},{"t":"2018년부터 2022년까지 계속 줄어들었어요.","mis":"M4-2-u5-X13"},{"t":"2021년에 태풍이 가장 많이 발생했어요.","mis":"M4-2-u5-X10"},{"t":"2022년에는 2021년보다 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["2018년과 2019년 사이의 선분은 평평해요 — 둘 다 29회예요.","2021년에 22회로 가장 적고, 2022년에는 25회로 늘었어요.","같은 값이면 선분이 평평해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[29,29,23,22,25]}],"step":1,"ymax":30,"ylab":"(회)","xlab":"(년)","y0":20,"wave":true,"every":5,"title":"연도별 태풍 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_basic#10','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',3,'mc','auto','「개념 쏙」 — 내가 나타낸 연도별 폭염 일수 꺾은선그래프가 자료 수집의 목적과 수집한 자료의 특성에 맞는지 확인한 말로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X15','M4-2-u5-X16','M4-2-u5-X23']::text[],false,'{"seq":10,"concept":"M4-2-u5-C10","difficulty":3,"kind":"mc","stem":"「개념 쏙」 — 내가 나타낸 연도별 폭염 일수 꺾은선그래프가 자료 수집의 목적과 수집한 자료의 특성에 맞는지 확인한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"기후변화를 조사하려는 목적과 연도별 변화를 나타내려는 자료의 특성에 맞게 잘 나타냈어요.","correct":true},{"t":"폭염 일수는 시간과 관계없는 자료라서 꺾은선그래프로 나타내면 안 돼요.","mis":"M4-2-u5-X15"},{"t":"출처를 적지 않았지만 그래프만 맞으면 괜찮아요.","mis":"M4-2-u5-X16"},{"t":"연도별 자료는 목적과 상관없이 언제나 꺾은선그래프만 맞아요.","mis":"M4-2-u5-X23"}],"explanation":["목적은 기후변화로 폭염 일수가 어떻게 변했는지 알아보는 거예요.","연도별 폭염 일수는 시간에 따라 변하는 자료예요.","그래서 꺾은선그래프가 목적과 특성에 맞아요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#1','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',2,'ox','auto','「성장 지원 평가」 — 여러 지역의 폭염 일수를 조사한 자료는 꺾은선그래프로 나타내기에 알맞아요.',ARRAY['M4-2-u5-X15']::text[],false,'{"seq":1,"concept":"M4-2-u5-C10","difficulty":2,"kind":"ox","stem":"「성장 지원 평가」 — 여러 지역의 폭염 일수를 조사한 자료는 꺾은선그래프로 나타내기에 알맞아요.","answer":"X","reason_options":[{"t":"시간에 따른 변화가 있는 자료가 아니라 지역별 자료라서","correct":true},{"t":"폭염 일수라면 무엇이든 꺾은선그래프로 나타내야 해서","mis":"M4-2-u5-X15"}],"mis":"M4-2-u5-X15","explanation":["지역별 자료는 그림그래프나 막대그래프로 나타내기에 알맞아요.","꺾은선그래프로 나타내기 알맞은 자료는 시간에 따른 변화가 있는 자료예요.","한 지역의 연도별 폭염 일수라면 꺾은선그래프가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#2','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',2,'mc','auto','「개념 쏙」 — 어느 지역의 연도별 폭염 일수 자료는 어디에서 찾으면 좋을까요?',ARRAY['M4-2-u5-X16']::text[],false,'{"seq":2,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 어느 지역의 연도별 폭염 일수 자료는 어디에서 찾으면 좋을까요?","options":[{"t":"기상자료개방포털 누리집","correct":true},{"t":"친구가 짐작해서 쓴 글","mis":"M4-2-u5-X16"},{"t":"10년 전에 본 신문 한 장","mis":"M4-2-u5-X16"},{"t":"출처가 없는 그림","mis":"M4-2-u5-X16"}],"explanation":["폭염 일수는 기상과 관련된 공식 자료예요.","기상자료개방포털 첫 화면 → 기후통계분석 → 기상현상일수 순서로 찾아요.","믿을 수 있는 곳의 최근 자료를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#3','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'sa','auto','「문제 척」 — 폭염 일수 그래프에서 2021년은 2020년보다 폭염 일수가 며칠 더 많은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"「문제 척」 — 폭염 일수 그래프에서 2021년은 2020년보다 폭염 일수가 며칠 더 많은가요? 숫자로 쓰세요.","answer":["14"],"explanation":["2020년은 4일, 2021년은 18일이에요.","두 해의 값만 써서 빼요.","18 − 4 = 14 — 14일 더 많아요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#4','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'sa','auto','「수학익힘」 — 태풍 발생 횟수가 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 태풍 발생 횟수가 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["가장 많았던 때는 2018년·2019년의 29회예요.","가장 적었던 때는 2021년의 22회예요.","29 − 22 = 7 — 7회예요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[29,29,23,22,25]}],"step":1,"ymax":30,"ylab":"(회)","xlab":"(년)","y0":20,"wave":true,"every":5,"title":"연도별 태풍 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#5','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'mc','auto','「수학익힘」 — 태풍 발생 횟수가 전년도와 비교하여 가장 많이 줄어든 해는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X13']::text[],false,'{"seq":5,"concept":"M4-2-u5-C10","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 태풍 발생 횟수가 전년도와 비교하여 가장 많이 줄어든 해는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2021년","mis":"M4-2-u5-X12"},{"t":"2022년","mis":"M4-2-u5-X10"},{"t":"2019년","mis":"M4-2-u5-X13"}],"explanation":["2019년은 변화가 없고, 2020년은 6회, 2021년은 1회 줄었어요.","2022년은 3회 늘었어요.","가장 많이 줄어든 해는 2020년이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[29,29,23,22,25]}],"step":1,"ymax":30,"ylab":"(회)","xlab":"(년)","y0":20,"wave":true,"every":5,"title":"연도별 태풍 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#6','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'mc','auto','「확인 문제」 — 우리 반 교실의 온도를 시각별로 조사한 표를 꺾은선그래프로 나타내려고 해요. 알맞게 정한 것은 어느 것인가요?',ARRAY['M4-2-u5-X09','M4-2-u5-X07','M4-2-u5-X20']::text[],false,'{"seq":6,"concept":"M4-2-u5-C10","difficulty":3,"kind":"mc","stem":"「확인 문제」 — 우리 반 교실의 온도를 시각별로 조사한 표를 꺾은선그래프로 나타내려고 해요. 알맞게 정한 것은 어느 것인가요?","options":[{"t":"물결선을 0부터 19 °C 사이에 넣고 세로 눈금은 23 °C까지 나타내요.","correct":true},{"t":"물결선을 20 °C와 22 °C 사이에 넣어요.","mis":"M4-2-u5-X09"},{"t":"세로 눈금은 19 °C까지만 나타내요.","mis":"M4-2-u5-X07"},{"t":"물결선은 쓰면 안 되니 0부터 나타내야만 해요.","mis":"M4-2-u5-X20"}],"explanation":["표의 값은 19, 20, 20, 22, 23 °C예요.","가장 작은 값 19 °C 아래를 물결선으로 줄이고, 가장 큰 값 23 °C까지 나타내요.","물결선을 쓰지 않고 0부터 나타내도 틀리지는 않아요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["오전 9","오전 10","오전 11","낮 12","오후 1"],"counts":[19,20,20,22,23],"vh":"온도","unit":"°C","total":false,"title":"시각별 교실의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#7','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'error','auto','「친구의 설명」 — 폭염 일수 자료를 수집하는 과정을 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X16','M4-2-u5-X21']::text[],false,'{"seq":7,"concept":"M4-2-u5-C10","difficulty":3,"kind":"error","stem":"「친구의 설명」 — 폭염 일수 자료를 수집하는 과정을 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「자료가 많을수록 좋으니 출처를 몰라도 아무 누리집 자료나 모을래.」","correct":true,"mis_target":"M4-2-u5-X16"},{"t":"시우 — 「최근 5년간의 자료를 모을래.」","mis":"M4-2-u5-X21"},{"t":"은우 — 「모은 자료를 연도별 폭염 일수 표로 정리할래.」","mis":"M4-2-u5-X21"}],"explanation":["자료는 믿을 수 있는 곳에서 모아야 해요.","최근 자료를 모으고 출처를 적어요.","민서는 출처를 확인하지 않아 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#8','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',4,'mc','auto','「문제 척」 — 폭염 일수 그래프를 보고 폭염 일수가 가장 많았던 때와 가장 적었던 때를 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X21','M4-2-u5-X02']::text[],false,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":4,"kind":"mc","stem":"「문제 척」 — 폭염 일수 그래프를 보고 폭염 일수가 가장 많았던 때와 가장 적었던 때를 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가장 많았던 때 2023년, 가장 적었던 때 2020년","correct":true},{"t":"가장 많았던 때 2021년, 가장 적었던 때 2020년","mis":"M4-2-u5-X12"},{"t":"가장 많았던 때 2020년, 가장 적었던 때 2023년","mis":"M4-2-u5-X21"},{"t":"가장 많았던 때 2019년, 가장 적었던 때 2022년","mis":"M4-2-u5-X02"}],"explanation":["가장 높이 있는 점은 2023년의 19일이에요.","가장 낮게 있는 점은 2020년의 4일이에요.","가장 많이 늘어난 2021년(18일)과 가장 많은 2023년은 달라요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#9','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',4,'sa','auto','「문제 척」 — 폭염 일수 그래프에서 전년도와 비교하여 폭염 일수가 가장 많이 변한 때에는 며칠 변했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u5-C10","difficulty":4,"kind":"sa","stem":"「문제 척」 — 폭염 일수 그래프에서 전년도와 비교하여 폭염 일수가 가장 많이 변한 때에는 며칠 변했나요? 숫자로 쓰세요.","answer":["14"],"explanation":["전년도와 비교한 변화: 2020년 11일 줄고, 2021년 14일 늘고, 2022년 8일 줄고, 2023년 9일 늘었어요.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 2021년, 14일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L06_challenge#10','math',4,2,'u5','L06','tb_g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',4,'essay','teacher','「개념 쏙」 — 지유네 반은 한파 일수를 조사하기로 했어요. 조사하고 싶은 주제를 정하는 것부터 꺾은선그래프로 나타내고 해석하는 것까지 어떤 순서로 하면 좋을지 쓰고, 자료를 수집할 때 주의할 점도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C10","difficulty":4,"kind":"essay","stem":"「개념 쏙」 — 지유네 반은 한파 일수를 조사하기로 했어요. 조사하고 싶은 주제를 정하는 것부터 꺾은선그래프로 나타내고 해석하는 것까지 어떤 순서로 하면 좋을지 쓰고, 자료를 수집할 때 주의할 점도 써 보세요.","answer_guide":{"answer":"예: ① 주제를 「어느 지역의 연도별 한파 일수」로 정한다. ② 항목을 연도와 한파 일수로 정한다. ③ 기상자료개방포털 누리집에서 최근 5년간의 자료를 수집해 표로 정리하고 출처를 적는다. ④ 표를 꺾은선그래프로 나타내고 가장 많이 늘어난 때 등을 해석한다. 공식적인 누리집에서 최근 자료를 모아야 한다.","scoring_points":["주제 → 항목 → 수집 방법 → 꺾은선그래프·해석 순서로 썼는가","시간에 따른(연도별) 주제를 골랐는가","믿을 수 있는 곳·최근 자료·출처를 주의할 점으로 썼는가"]},"explanation":["주제와 항목을 정하고 수집할 방법을 정해요.","공식 누리집에서 최근 자료를 모아 표로 정리하고 출처를 적어요.","꺾은선그래프로 나타내고 해석해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#1','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'match','auto','「개념 쏙」 — 우리가 배운 그래프와 그 그래프의 편리한 점을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":1,"concept":"M4-2-u5-C11","difficulty":1,"kind":"match","stem":"「개념 쏙」 — 우리가 배운 그래프와 그 그래프의 편리한 점을 알맞게 이어 보세요.","pairs":[{"l":"그림그래프","r":"그림으로 자료를 한눈에 비교하기 쉬워요."},{"l":"막대그래프","r":"막대의 길이로 자료의 크기를 한눈에 알아보기 쉬워요."},{"l":"꺾은선그래프","r":"시간에 따른 자료의 변화를 알아보기 쉬워요."}],"mis":"M4-2-u5-X17","explanation":["그림그래프와 막대그래프는 자료의 수량을 한눈에 비교하는 그래프예요.","꺾은선그래프는 점들을 선분으로 이어 변화를 보여 줘요.","자료 수집의 목적에 맞게 세 그래프의 편리한 점을 생각해 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#2','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'mc','auto','「개념 쏙」 — 시간에 따른 자료의 변화를 쉽게 알아보기에 적절한 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":2,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 시간에 따른 자료의 변화를 쉽게 알아보기에 적절한 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 점들을 선분으로 이어요.","선분이 기울어진 모양으로 변화가 한눈에 보여요.","시간에 따른 변화에는 꺾은선그래프가 적절해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#3','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'mc','auto','「토의 · 토론」 — 채원이는 어느 지역의 연도별 해수면 높이를 막대그래프로 나타냈어요. 채원이가 막대그래프로 나타낸 이유는 무엇인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X23','M4-2-u5-X05']::text[],false,'{"seq":3,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「토의 · 토론」 — 채원이는 어느 지역의 연도별 해수면 높이를 막대그래프로 나타냈어요. 채원이가 막대그래프로 나타낸 이유는 무엇인가요?","options":[{"t":"연도별 해수면 높이를 한눈에 비교하기 위해서","correct":true},{"t":"연도별 해수면 높이의 변화를 쉽게 알아보기 위해서","mis":"M4-2-u5-X21"},{"t":"해수면 높이는 막대그래프로만 나타낼 수 있어서","mis":"M4-2-u5-X23"},{"t":"막대그래프는 물결선을 쓸 수 없어서","mis":"M4-2-u5-X05"}],"explanation":["채원이는 「나는 연도별 해수면 높이를 한눈에 비교하기 위해 막대그래프로 나타내었어.」라고 했어요.","막대그래프는 자료의 수량을 한눈에 비교하기 편리해요.","채원이의 목적에 맞는 그래프예요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[27,30,34,32,32]}],"step":1,"ymax":35,"ylab":"(cm)","xlab":"(년)","every":10,"title":"연도별 해수면 높이","mode":"bar"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#4','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'mc','auto','「토의 · 토론」 — 도윤이는 같은 해수면 높이 자료를 꺾은선그래프로 나타냈어요. 도윤이가 꺾은선그래프로 나타낸 이유는 무엇인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X23','M4-2-u5-X17']::text[],false,'{"seq":4,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「토의 · 토론」 — 도윤이는 같은 해수면 높이 자료를 꺾은선그래프로 나타냈어요. 도윤이가 꺾은선그래프로 나타낸 이유는 무엇인가요?","options":[{"t":"연도별 해수면 높이의 변화를 쉽게 알아보기 위해서","correct":true},{"t":"연도별 해수면 높이를 한눈에 비교하기 위해서","mis":"M4-2-u5-X21"},{"t":"연도별 자료는 꺾은선그래프로만 나타낼 수 있어서","mis":"M4-2-u5-X23"},{"t":"꺾은선그래프가 더 예뻐서","mis":"M4-2-u5-X17"}],"explanation":["도윤이는 「나는 연도별 해수면 높이의 변화를 쉽게 알아보기 위해 꺾은선그래프로 나타내었어.」라고 했어요.","꺾은선그래프는 시간에 따른 변화를 한눈에 알아보기 편리해요.","도윤이의 목적에 맞는 그래프예요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[27,30,34,32,32]}],"step":1,"ymax":35,"ylab":"(cm)","xlab":"(년)","every":10,"title":"연도별 해수면 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#5','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','「개념 쏙」 — 여러 강의 수질 오염 발생 횟수 표를 보고 발생 횟수를 한눈에 비교하기에 가장 적절한 그래프를 고른 것은 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":5,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 여러 강의 수질 오염 발생 횟수 표를 보고 발생 횟수를 한눈에 비교하기에 가장 적절한 그래프를 고른 것은 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선을 넣은 꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"어느 그래프도 나타낼 수 없어요","mis":"M4-2-u5-X03"}],"explanation":["목적은 강별 발생 횟수를 한눈에 비교하는 거예요.","막대그래프는 발생 횟수를 한눈에 비교하기 편리하고 크고 작음을 쉽게 알 수 있어요.","그림그래프도 알맞아요 — 꺾은선그래프는 알맞지 않아요."],"asset":{"type":"picg","only":"table","head":"강","cols":["가","나","다","라","마"],"counts":[14,16,2,10,21],"vh":"횟수","unit":"회","total":false,"title":"강별 수질 오염 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#6','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','「개념 쏙」 — 강별 수질 오염 발생 횟수를 꺾은선그래프로 나타냈어요. 꺾은선그래프가 이 자료에 적절하지 않은 이유는 무엇인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X05']::text[],false,'{"seq":6,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「개념 쏙」 — 강별 수질 오염 발생 횟수를 꺾은선그래프로 나타냈어요. 꺾은선그래프가 이 자료에 적절하지 않은 이유는 무엇인가요?","options":[{"t":"시간에 따라 수집한 자료가 아니라서","correct":true},{"t":"자료의 값이 작아서","mis":"M4-2-u5-X17"},{"t":"물결선을 넣지 않아서","mis":"M4-2-u5-X05"},{"t":"강이 다섯 개뿐이라서","mis":"M4-2-u5-X17"}],"explanation":["가로가 시간이 아니라 강 가, 나, 다, 라, 마예요.","강과 강 사이의 선분은 아무 변화도 나타내지 않아요.","시간에 따른 자료가 아니므로 자료의 특성에 알맞지 않은 그래프예요."],"asset":{"type":"lgraph","xs":["가","나","다","라","마"],"series":[{"vals":[14,16,2,10,21]}],"step":1,"ymax":22,"ylab":"(회)","xlab":"(강)","every":5,"title":"강별 수질 오염 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#7','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','「수학익힘」 — 강아지의 몸무게를 매월 1일마다 조사한 표예요. 강아지의 몸무게의 변화를 나타내기에 가장 적절한 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X17']::text[],false,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 강아지의 몸무게를 매월 1일마다 조사한 표예요. 강아지의 몸무게의 변화를 나타내기에 가장 적절한 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프 — 막대가 길수록 무거워서","mis":"M4-2-u5-X17"},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"어느 그래프로 나타내도 똑같이 편리해요","mis":"M4-2-u5-X17"}],"explanation":["목적은 몸무게의 변화를 알아보는 거예요.","7월부터 11월까지 시간에 따라 달라지는 자료예요.","꺾은선그래프는 시간에 따라 변화하는 양을 한눈에 알아보기 편리해요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[4,5,5,6,7],"vh":"몸무게","unit":"kg","total":false,"title":"월별 강아지의 몸무게"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#8','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','「수학익힘」 — 여러 지역의 도서관 수를 한눈에 비교하기 위해 표의 내용을 그래프로 나타내려고 해요. 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 여러 지역의 도서관 수를 한눈에 비교하기 위해 표의 내용을 그래프로 나타내려고 해요. 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"그림그래프 또는 막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선을 넣은 꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"그래프로 나타낼 수 없어요","mis":"M4-2-u5-X03"}],"explanation":["지역별 도서관 수는 시간에 따른 자료가 아니에요.","목적은 지역끼리 수량을 한눈에 비교하는 거예요.","그림그래프와 막대그래프는 자료의 수량을 한눈에 비교하기 편리해요."],"asset":{"type":"picg","only":"table","head":"지역","cols":["광주","대전","부산","서울"],"counts":[24,25,47,188],"vh":"도서관 수","unit":"관","total":false,"title":"지역별 도서관 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#9','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','「수학익힘」 — 어느 지역의 해수면 높이를 연도별로 조사한 표예요. 해수면 높이의 변화를 알아보기 쉽게 나타내려면 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":9,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 어느 지역의 해수면 높이를 연도별로 조사한 표예요. 해수면 높이의 변화를 알아보기 쉽게 나타내려면 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표가 가장 좋아요","mis":"M4-2-u5-X03"}],"explanation":["목적은 해수면 높이의 변화를 알아보는 거예요.","시간에 따라 변화가 나타나는 자료는 꺾은선그래프로 나타내는 것이 적절해요.","각 항목의 수량을 비교하는 자료는 그림그래프·막대그래프가 적절해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[245,248,250,252,249],"vh":"높이","unit":"cm","total":false,"title":"연도별 해수면 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_basic#10','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',3,'mc','auto','「수학익힘」 — 지유네 반에서 기르는 식물의 키를 매월 1일마다 조사하여 나타낸 꺾은선그래프예요. 식물의 키의 변화를 한눈에 알아보기에 적절한 그래프인지와 그 이유로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X20','M4-2-u5-X12']::text[],false,'{"seq":10,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 지유네 반에서 기르는 식물의 키를 매월 1일마다 조사하여 나타낸 꺾은선그래프예요. 식물의 키의 변화를 한눈에 알아보기에 적절한 그래프인지와 그 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"적절해요 — 시간에 따라 변화하는 양을 알아보기 편리한 그래프는 꺾은선그래프라서","correct":true},{"t":"적절하지 않아요 — 막대그래프로 나타내야만 해서","mis":"M4-2-u5-X17"},{"t":"적절하지 않아요 — 물결선이 없어서","mis":"M4-2-u5-X20"},{"t":"적절해요 — 식물의 키가 점점 커서","mis":"M4-2-u5-X12"}],"explanation":["목적은 식물의 키의 변화를 한눈에 알아보는 거예요.","식물의 키는 시간에 따라 변하는 자료예요.","꺾은선그래프는 시간에 따라 변화하는 양을 알아보기 편리해요."],"asset":{"type":"lgraph","xs":["5","6","7","8"],"series":[{"vals":[8,12,18,26]}],"step":2,"ymax":28,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 식물의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#1','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',2,'ox','auto','「헷갈려요」 — 6월부터 10월까지 월별 최고 온도를 막대그래프로 나타내면 틀린 그래프예요.',ARRAY['M4-2-u5-X18']::text[],false,'{"seq":1,"concept":"M4-2-u5-C11","difficulty":2,"kind":"ox","stem":"「헷갈려요」 — 6월부터 10월까지 월별 최고 온도를 막대그래프로 나타내면 틀린 그래프예요.","answer":"X","reason_options":[{"t":"틀린 것은 아니고, 변화의 경향이나 사이 값을 알아보기가 꺾은선그래프보다 어려울 뿐이라서","correct":true},{"t":"이어진 자료는 꼭 꺾은선그래프로만 나타내야 해서","mis":"M4-2-u5-X18"}],"mis":"M4-2-u5-X18","explanation":["연속된 자료를 막대그래프로 나타냈다고 틀렸다고 할 수 없어요.","다만 막대그래프는 변화의 경향을 알아보거나 두 때 사이의 값을 예측하기 어려워요.","목적에 맞는 그래프를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#2','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',2,'mc','auto','「확인 문제」 — 제목은 「월별 어느 지역의 미세 먼지 발생 일수」, 수집 목적은 「월별 미세 먼지 발생 일수를 한눈에 비교하기 위함」이에요. 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X23','M4-2-u5-X03']::text[],true,'{"seq":2,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「확인 문제」 — 제목은 「월별 어느 지역의 미세 먼지 발생 일수」, 수집 목적은 「월별 미세 먼지 발생 일수를 한눈에 비교하기 위함」이에요. 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"그림그래프 또는 막대그래프","correct":true},{"t":"꺾은선그래프 — 월별 자료는 언제나 꺾은선그래프라서","mis":"M4-2-u5-X23"},{"t":"물결선을 넣은 꺾은선그래프","mis":"M4-2-u5-X23"},{"t":"표로만 나타내야 해요","mis":"M4-2-u5-X03"}],"explanation":["월별 자료라도 수집 목적을 먼저 봐요.","목적은 일수를 한눈에 비교하는 거예요.","그래서 그림그래프나 막대그래프가 적절해요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 제목은 「우리나라 선수들이 획득한 메달 수」, 수집 목적은 「최근 8년 간의 국제 경기에서 우리나라 선수들이 획득한 메달 수의 변화를 알아보기 위함」이에요. 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프 — 메달 수를 한눈에 비교하려고","mis":"M4-2-u5-X23"},{"t":"표로만 나타내야 해요","mis":"M4-2-u5-X03"}],"explanation":["수집 목적을 먼저 봐요.","목적은 시간에 따른 메달 수의 변화를 알아보는 거예요.","그래서 꺾은선그래프가 적절해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#3','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'mc','auto','「토의 · 토론」 — 같은 연도별 해수면 높이 자료를 채원이는 막대그래프로, 도윤이는 꺾은선그래프로 나타냈어요. 두 사람의 의견에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X23','M4-2-u5-X17']::text[],false,'{"seq":3,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「토의 · 토론」 — 같은 연도별 해수면 높이 자료를 채원이는 막대그래프로, 도윤이는 꺾은선그래프로 나타냈어요. 두 사람의 의견에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 알맞아요 — 자료를 나타낸 목적이 달라 알맞은 그래프도 달라요.","correct":true},{"t":"도윤이만 맞아요 — 연도별 자료는 꼭 꺾은선그래프로 나타내야 해요.","mis":"M4-2-u5-X23"},{"t":"채원이만 맞아요 — 해수면 높이는 막대그래프로 비교해야 해요.","mis":"M4-2-u5-X23"},{"t":"둘 다 틀려요 — 그림그래프로 나타내야 해요.","mis":"M4-2-u5-X17"}],"explanation":["채원이는 한눈에 비교하려고, 도윤이는 변화를 알아보려고 그래프를 골랐어요.","하나의 자료가 하나의 그래프로만 표현되지 않아요.","자료 수집의 목적과 자료의 특성을 생각하면 둘 다 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#4','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'mc','auto','「수학에 퐁당」 — 어느 바다의 시각별 수온을 나타낸 두 꺾은선그래프는 같은 값을 보고 나타냈는데, 한 그래프는 거의 평평하고 다른 그래프는 가파르게 내려가요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X22','M4-2-u5-X20','M4-2-u5-X05']::text[],false,'{"seq":4,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「수학에 퐁당」 — 어느 바다의 시각별 수온을 나타낸 두 꺾은선그래프는 같은 값을 보고 나타냈는데, 한 그래프는 거의 평평하고 다른 그래프는 가파르게 내려가요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"세로 눈금 한 칸의 크기와 세로 눈금의 수에 따라 같은 자료도 다르게 보이니 그래프의 수를 정확하게 읽어야 해요.","correct":true},{"t":"가파른 그래프의 바다가 수온이 더 많이 내려갔어요.","mis":"M4-2-u5-X22"},{"t":"두 그래프 가운데 하나는 틀린 그래프예요.","mis":"M4-2-u5-X20"},{"t":"물결선이 있는 그래프의 수온이 더 낮아요.","mis":"M4-2-u5-X05"}],"explanation":["두 그래프는 같은 값을 보고 나타냈어요.","세로 눈금 한 칸의 크기, 세로 눈금의 수를 어떻게 정하는지에 따라 모양이 달라 보여요.","그래프의 모양에만 초점을 두지 말고 수를 정확하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#5','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'error','auto','「성장 지원 평가」 — 강별 수질 오염 발생 횟수를 나타내기에 알맞은 그래프를 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X21']::text[],false,'{"seq":5,"concept":"M4-2-u5-C11","difficulty":3,"kind":"error","stem":"「성장 지원 평가」 — 강별 수질 오염 발생 횟수를 나타내기에 알맞은 그래프를 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「발생 횟수는 꺾은선그래프로 나타내는 것이 적절할 것 같아.」","correct":true,"mis_target":"M4-2-u5-X17"},{"t":"지아 — 「그림그래프가 적절해. 발생 횟수를 한눈에 비교하기 편리해.」","mis":"M4-2-u5-X21"},{"t":"하랑 — 「막대그래프가 적절해. 가장 많이 발생한 곳과 가장 적게 발생한 곳을 한눈에 알 수 있어.」","mis":"M4-2-u5-X21"}],"explanation":["목적은 강별 발생 횟수를 한눈에 비교하는 거예요.","강별 자료는 시간에 따른 자료가 아니에요.","준서처럼 꺾은선그래프를 고르면 자료의 특성에 맞지 않아요."],"asset":{"type":"picg","only":"table","head":"강","cols":["가","나","다","라","마"],"counts":[14,16,2,10,21],"vh":"횟수","unit":"회","total":false,"title":"강별 수질 오염 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#6','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'mc','auto','「개념 쏙」 — 자료의 특성에 따라 목적에 맞는 적절한 그래프를 선택하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X17']::text[],false,'{"seq":6,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「개념 쏙」 — 자료의 특성에 따라 목적에 맞는 적절한 그래프를 선택하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료 수집의 목적과 그림그래프, 막대그래프, 꺾은선그래프의 편리한 점을 생각해요.","correct":true},{"t":"그래프 모양이 보기 좋은 것을 골라요.","mis":"M4-2-u5-X17"},{"t":"언제나 꺾은선그래프를 골라요.","mis":"M4-2-u5-X17"},{"t":"자료의 수가 많으면 막대그래프를 골라요.","mis":"M4-2-u5-X17"}],"explanation":["자료 수집의 목적을 생각해요.","수집한 자료의 특성을 생각해요.","세 그래프의 편리한 점을 생각해 목적에 맞는 그래프를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#7','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'mc','auto','「수학익힘」 — 강아지의 몸무게를 막대그래프로도 나타냈어요. 이 막대그래프에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17','M4-2-u5-X13']::text[],false,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 강아지의 몸무게를 막대그래프로도 나타냈어요. 이 막대그래프에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"틀린 그래프는 아니지만, 몸무게의 변화를 알아보기에는 꺾은선그래프가 더 편리해요.","correct":true},{"t":"이어진 자료를 막대로 나타냈으니 틀린 그래프예요.","mis":"M4-2-u5-X18"},{"t":"몸무게의 변화를 알아보기에는 막대그래프가 가장 좋아요.","mis":"M4-2-u5-X17"},{"t":"8월과 9월의 몸무게가 서로 달라요.","mis":"M4-2-u5-X13"}],"explanation":["같은 자료를 막대그래프로도 꺾은선그래프로도 나타낼 수 있어요.","막대그래프로 나타냈다고 틀린 것은 아니에요.","시간에 따른 변화를 알아보기에는 꺾은선그래프가 편리해요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[4,5,5,6,7]}],"step":1,"ymax":8,"ylab":"(kg)","xlab":"(월)","every":5,"title":"월별 강아지의 몸무게","mode":"bar"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#8','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',4,'mc','auto','「궁금해요」 — 강별 수질 오염 발생 횟수를 나타낸 꺾은선그래프에서 나 강과 다 강 사이의 선분을 보고 「발생 횟수가 줄어들었다」고 읽으면 안 되는 까닭은 무엇인가요?',ARRAY['M4-2-u5-X08','M4-2-u5-X10','M4-2-u5-X05']::text[],false,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":4,"kind":"mc","stem":"「궁금해요」 — 강별 수질 오염 발생 횟수를 나타낸 꺾은선그래프에서 나 강과 다 강 사이의 선분을 보고 「발생 횟수가 줄어들었다」고 읽으면 안 되는 까닭은 무엇인가요?","options":[{"t":"가로가 시간이 아니라 강이라서 점과 점 사이의 선분이 변화를 나타내지 않아서","correct":true},{"t":"세로 눈금 한 칸이 커서","mis":"M4-2-u5-X08"},{"t":"선분이 오른쪽 아래로 내려갔으니 줄어든 것이 맞아요","mis":"M4-2-u5-X10"},{"t":"물결선이 없어서","mis":"M4-2-u5-X05"}],"explanation":["꺾은선그래프의 선분은 시간에 따른 변화를 나타낼 때 뜻이 있어요.","나 강과 다 강은 서로 다른 강일 뿐 시간의 차례가 아니에요.","그래서 이 자료에는 꺾은선그래프가 알맞지 않아요."],"asset":{"type":"lgraph","xs":["가","나","다","라","마"],"series":[{"vals":[14,16,2,10,21]}],"step":1,"ymax":22,"ylab":"(회)","xlab":"(강)","every":5,"title":"강별 수질 오염 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#9','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',4,'sa','auto','「개념 쏙」 — 강별 수질 오염 발생 횟수를 막대그래프로 나타냈어요. 수질 오염이 가장 많이 발생한 강과 가장 적게 발생한 강의 발생 횟수의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u5-C11","difficulty":4,"kind":"sa","stem":"「개념 쏙」 — 강별 수질 오염 발생 횟수를 막대그래프로 나타냈어요. 수질 오염이 가장 많이 발생한 강과 가장 적게 발생한 강의 발생 횟수의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["막대그래프는 크고 작음을 한눈에 비교하기 편리해요.","가장 많은 강은 마 강 21회, 가장 적은 강은 다 강 2회예요.","21 − 2 = 19 — 19회예요."],"asset":{"type":"lgraph","xs":["가","나","다","라","마"],"series":[{"vals":[14,16,2,10,21]}],"step":1,"ymax":22,"ylab":"(회)","xlab":"(강)","every":5,"title":"강별 수질 오염 발생 횟수","mode":"bar"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L07_challenge#10','math',4,2,'u5','L07','tb_g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',4,'essay','teacher','「토의 · 토론」 — 어느 지역의 연도별 해수면 높이 표(2018년 27 cm, 2019년 30 cm, 2020년 34 cm, 2021년 32 cm, 2022년 32 cm)를 그래프로 나타내려고 해요. 목적이 다른 두 가지 경우를 들어 각각 어떤 그래프가 알맞은지와 그 이유를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C11","difficulty":4,"kind":"essay","stem":"「토의 · 토론」 — 어느 지역의 연도별 해수면 높이 표(2018년 27 cm, 2019년 30 cm, 2020년 34 cm, 2021년 32 cm, 2022년 32 cm)를 그래프로 나타내려고 해요. 목적이 다른 두 가지 경우를 들어 각각 어떤 그래프가 알맞은지와 그 이유를 써 보세요.","answer_guide":{"answer":"예: 연도별 해수면 높이를 한눈에 비교하는 것이 목적이면 자료의 수량을 한눈에 비교하기 편리한 막대그래프가 알맞다. 연도별 해수면 높이의 변화를 알아보는 것이 목적이면 시간에 따른 변화를 한눈에 알아보기 편리한 꺾은선그래프가 알맞다. 하나의 자료도 목적에 따라 다른 그래프로 나타낼 수 있다.","scoring_points":["비교 목적 → 막대(그림)그래프를 썼는가","변화 목적 → 꺾은선그래프를 썼는가","각 그래프의 편리한 점으로 이유를 썼는가"]},"explanation":["비교하려면 막대그래프가 편리해요.","변화를 보려면 꺾은선그래프가 편리해요.","목적에 따라 알맞은 그래프가 달라요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[27,30,34,32,32],"vh":"높이","unit":"cm","total":false,"title":"연도별 해수면 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#1','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'mc','auto','「창의가 반짝」 — 연도별 유소년층과 노년층 인구수(만 명) — 유소년층 2018년 650, 2019년 640, 2020년 630, 2021년 610, 2022년 590 · 노년층 2018년 750, 2019년 780, 2020년 830, 2021년 870, 2022년 900. 유소년층과 노년층 인구수의 변화를 한눈에 알아보려면 어떻게 하면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":1,"concept":"M4-2-u5-C12","difficulty":1,"kind":"mc","stem":"「창의가 반짝」 — 연도별 유소년층과 노년층 인구수(만 명) — 유소년층 2018년 650, 2019년 640, 2020년 630, 2021년 610, 2022년 590 · 노년층 2018년 750, 2019년 780, 2020년 830, 2021년 870, 2022년 900. 유소년층과 노년층 인구수의 변화를 한눈에 알아보려면 어떻게 하면 좋을까요?","options":[{"t":"꺾은선그래프로 나타내면 좋아요.","correct":true},{"t":"그림그래프로 나타내면 좋아요.","mis":"M4-2-u5-X17"},{"t":"막대그래프로 지역별로 나타내면 좋아요.","mis":"M4-2-u5-X17"},{"t":"표로만 보면 돼요.","mis":"M4-2-u5-X03"}],"explanation":["두 자료 모두 2018년부터 2022년까지 연도별로 조사했어요.","시간에 따른 변화를 한눈에 알아보려는 거예요.","꺾은선그래프로 나타내면 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#2','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'mc','auto','「창의가 반짝」 — 유소년층과 노년층 두 개의 자료를 하나의 꺾은선그래프로 나타냈어요. 두 자료를 구분하기 위해 어떻게 했나요?',ARRAY['M4-2-u5-X19','M4-2-u5-X01']::text[],false,'{"seq":2,"concept":"M4-2-u5-C12","difficulty":1,"kind":"mc","stem":"「창의가 반짝」 — 유소년층과 노년층 두 개의 자료를 하나의 꺾은선그래프로 나타냈어요. 두 자료를 구분하기 위해 어떻게 했나요?","options":[{"t":"선분의 색을 다르게 하고 이름표를 붙였어요.","correct":true},{"t":"두 자료를 한 선으로 이었어요.","mis":"M4-2-u5-X19"},{"t":"가로와 세로를 바꾸었어요.","mis":"M4-2-u5-X01"},{"t":"노년층만 나타냈어요.","mis":"M4-2-u5-X19"}],"explanation":["같은 연도의 두 자료를 같은 가로 눈금 위에 나타내요.","유소년층과 노년층을 구분하기 위해 선분의 색을 다르게 했어요.","이름표를 보고 어느 선인지 먼저 확인해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#3','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'mc','auto','「창의가 반짝」 — 꺾은선그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X19','M4-2-u5-X10']::text[],false,'{"seq":3,"concept":"M4-2-u5-C12","difficulty":1,"kind":"mc","stem":"「창의가 반짝」 — 꺾은선그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"유소년층 인구수는 점점 줄어들고, 노년층 인구수는 점점 늘어나고 있어요.","correct":true},{"t":"유소년층 인구수는 점점 늘어나고, 노년층 인구수는 점점 줄어들고 있어요.","mis":"M4-2-u5-X19"},{"t":"두 인구수가 모두 늘어나고 있어요.","mis":"M4-2-u5-X10"},{"t":"두 인구수가 모두 줄어들고 있어요.","mis":"M4-2-u5-X10"}],"explanation":["이름표로 두 선을 먼저 가려요.","유소년층 선은 오른쪽 아래로, 노년층 선은 오른쪽 위로 가요.","유소년층은 줄어들고 노년층은 늘어나고 있어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#4','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'mc','auto','「창의가 반짝」 — 유소년층과 노년층 인구수를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 0과 몇만 명 사이에 넣었나요?',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":4,"concept":"M4-2-u5-C12","difficulty":1,"kind":"mc","stem":"「창의가 반짝」 — 유소년층과 노년층 인구수를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 0과 몇만 명 사이에 넣었나요?","options":[{"t":"0과 590만 명 사이","correct":true},{"t":"650만 명과 750만 명 사이","mis":"M4-2-u5-X09"},{"t":"900만 명보다 위","mis":"M4-2-u5-X09"},{"t":"0과 900만 명 사이","mis":"M4-2-u5-X09"}],"explanation":["두 자료의 값은 590만 명부터 900만 명까지예요.","가장 작은 값은 2022년 유소년층의 590만 명이에요.","그래서 물결선을 0과 590만 명 사이에 넣었어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#5','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'sa','auto','「창의가 반짝」 — 2018년에 노년층 인구수는 유소년층 인구수보다 몇만 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"「창의가 반짝」 — 2018년에 노년층 인구수는 유소년층 인구수보다 몇만 명 더 많은가요? 숫자로 쓰세요.","answer":["100"],"explanation":["세로 눈금 한 칸은 10만 명이에요.","2018년 노년층은 750만 명, 유소년층은 650만 명이에요.","750 − 650 = 100 — 100만 명 더 많아요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"},"variant_rule":{"alt":[{"stem":"「창의가 반짝」 — 2020년에 노년층 인구수는 유소년층 인구수보다 몇만 명 더 많은가요? 숫자로 쓰세요.","answer":["200"],"explanation":["세로 눈금 한 칸은 10만 명이에요.","2020년 노년층은 830만 명, 유소년층은 630만 명이에요.","830 − 630 = 200 — 200만 명 더 많아요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#6','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'mc','auto','「창의가 반짝」 — 유소년층 인구수와 노년층 인구수의 차가 가장 적은 때와 가장 많은 때를 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X19','M4-2-u5-X14']::text[],false,'{"seq":6,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「창의가 반짝」 — 유소년층 인구수와 노년층 인구수의 차가 가장 적은 때와 가장 많은 때를 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가장 적은 때 2018년, 가장 많은 때 2022년","correct":true},{"t":"가장 적은 때 2022년, 가장 많은 때 2018년","mis":"M4-2-u5-X21"},{"t":"가장 적은 때 2018년, 가장 많은 때 2020년","mis":"M4-2-u5-X19"},{"t":"가장 적은 때 2019년, 가장 많은 때 2021년","mis":"M4-2-u5-X14"}],"explanation":["두 선 사이의 간격을 봐요.","차는 2018년 100만 명, 2019년 140만 명, 2020년 200만 명, 2021년 260만 명, 2022년 310만 명이에요.","가장 적은 때는 2018년, 가장 많은 때는 2022년이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#7','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'sa','auto','「창의가 반짝」 — 2022년에 노년층 인구수는 유소년층 인구수보다 몇만 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"「창의가 반짝」 — 2022년에 노년층 인구수는 유소년층 인구수보다 몇만 명 더 많은가요? 숫자로 쓰세요.","answer":["310"],"explanation":["2022년 노년층은 900만 명이에요.","2022년 유소년층은 590만 명이에요.","900 − 590 = 310 — 310만 명 더 많아요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#8','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'mc','auto','「창의가 반짝」 — 노년층 인구수가 전년도와 비교하여 가장 많이 늘어난 때는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X22','M4-2-u5-X21']::text[],false,'{"seq":8,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「창의가 반짝」 — 노년층 인구수가 전년도와 비교하여 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2022년","mis":"M4-2-u5-X12"},{"t":"2021년","mis":"M4-2-u5-X22"},{"t":"2019년","mis":"M4-2-u5-X21"}],"explanation":["노년층의 전년도 대비 늘어난 수: 2019년 30만, 2020년 50만, 2021년 40만, 2022년 30만 명.","노년층 선이 가장 가파르게 올라간 곳은 2019년과 2020년 사이예요.","가장 많이 늘어난 때는 2020년이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#9','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'mc','auto','「창의가 반짝」 — 친구들이 유소년층과 노년층 인구수를 물결선을 사용한 꺾은선그래프와 물결선을 사용하지 않은 꺾은선그래프로 나타냈어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X20','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「창의가 반짝」 — 친구들이 유소년층과 노년층 인구수를 물결선을 사용한 꺾은선그래프와 물결선을 사용하지 않은 꺾은선그래프로 나타냈어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요 — 물결선을 사용하면 변화의 정도가 더 잘 나타나요.","correct":true},{"t":"물결선을 사용한 그래프만 맞아요.","mis":"M4-2-u5-X20"},{"t":"물결선을 사용하지 않은 그래프만 맞아요.","mis":"M4-2-u5-X20"},{"t":"물결선을 쓰면 인구수가 바뀌어요.","mis":"M4-2-u5-X05"}],"explanation":["해결 방안 1은 물결선을 사용한 그래프, 해결 방안 2는 사용하지 않은 그래프예요.","두 방법 모두 같은 자료를 바르게 나타낼 수 있어요.","물결선을 쓰면 필요 없는 부분을 줄여 변화가 더 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_basic#10','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',3,'mc','auto','「창의가 반짝」 — 앞으로 우리나라의 인구 구성은 어떻게 변화할지 꺾은선그래프를 보고 알맞게 예상한 것은 어느 것인가요?',ARRAY['M4-2-u5-X19','M4-2-u5-X10','M4-2-u5-X25']::text[],false,'{"seq":10,"concept":"M4-2-u5-C12","difficulty":3,"kind":"mc","stem":"「창의가 반짝」 — 앞으로 우리나라의 인구 구성은 어떻게 변화할지 꺾은선그래프를 보고 알맞게 예상한 것은 어느 것인가요?","options":[{"t":"유소년층 인구수와 노년층 인구수의 차는 점점 커질 것 같아요.","correct":true},{"t":"두 인구수의 차는 점점 작아질 것 같아요.","mis":"M4-2-u5-X19"},{"t":"유소년층 인구수가 점점 늘어날 것 같아요.","mis":"M4-2-u5-X10"},{"t":"앞으로는 변하지 않을 것 같아요.","mis":"M4-2-u5-X25"}],"explanation":["유소년층은 계속 줄어들고 노년층은 계속 늘어나고 있어요.","두 선 사이의 간격이 해마다 넓어져요.","그래서 차는 점점 커질 것이라고 예상해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#1','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',2,'ox','auto','「스스로 역량을 기르는 과정」 — 두 개의 자료를 하나의 그래프로 나타낼 때는 같은 연도의 두 자료를 같은 가로 눈금 위에 나타내요.',ARRAY['M4-2-u5-X19']::text[],false,'{"seq":1,"concept":"M4-2-u5-C12","difficulty":2,"kind":"ox","stem":"「스스로 역량을 기르는 과정」 — 두 개의 자료를 하나의 그래프로 나타낼 때는 같은 연도의 두 자료를 같은 가로 눈금 위에 나타내요.","answer":"O","reason_options":[{"t":"같은 연도의 두 자료를 하나의 연도에 동시에 나타내야 견주기 쉬워서","correct":true},{"t":"두 자료는 서로 다른 가로 눈금에 따로 나타내야 해서","mis":"M4-2-u5-X19"}],"mis":"M4-2-u5-X19","explanation":["가로는 연도, 세로는 일수예요.","같은 연도의 폭염 일수와 한파 일수를 하나의 연도에 동시에 나타내요.","서로 다른 색의 점과 선분으로 구분해요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#2','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',2,'sa','auto','「수학익힘」 — 연도별 폭염 일수와 한파 일수를 하나의 그래프로 나타냈어요. 2022년의 한파 일수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 연도별 폭염 일수와 한파 일수를 하나의 그래프로 나타냈어요. 2022년의 한파 일수는 며칠인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["이름표로 한파 일수 선을 먼저 찾아요.","세로 눈금 한 칸은 1일이에요.","2022년의 한파 일수는 31일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 연도별 폭염 일수와 한파 일수를 하나의 그래프로 나타냈어요. 2021년의 폭염 일수는 며칠인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["이름표로 폭염 일수 선을 먼저 찾아요.","세로 눈금 한 칸은 1일이에요.","2021년의 폭염 일수는 22일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#3','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'mc','auto','「수학익힘」 — 2020년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?',ARRAY['M4-2-u5-X10','M4-2-u5-X19']::text[],true,'{"seq":3,"concept":"M4-2-u5-C12","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 2020년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?","options":[{"t":"폭염 일수와 한파 일수가 모두 줄어들었어요.","correct":true},{"t":"폭염 일수와 한파 일수가 모두 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"폭염 일수만 줄어들었어요.","mis":"M4-2-u5-X19"},{"t":"한파 일수만 줄어들었어요.","mis":"M4-2-u5-X19"}],"explanation":["폭염 일수는 16일에서 10일로, 한파 일수는 11일에서 9일로 바뀌었어요.","두 선 모두 2019년에서 2020년으로 오른쪽 아래로 내려가요.","모두 줄어들었어요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 2021년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?","options":[{"t":"폭염 일수와 한파 일수가 모두 늘어났어요.","correct":true},{"t":"폭염 일수와 한파 일수가 모두 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"폭염 일수만 늘어났어요.","mis":"M4-2-u5-X19"},{"t":"한파 일수만 늘어났어요.","mis":"M4-2-u5-X19"}],"explanation":["폭염 일수는 10일에서 22일로, 한파 일수는 9일에서 19일로 바뀌었어요.","두 선 모두 2020년에서 2021년으로 오른쪽 위로 올라가요.","모두 늘어났어요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#4','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'sa','auto','「수학익힘」 — 폭염 일수와 한파 일수의 차가 가장 큰 때에는 차가 며칠인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u5-C12","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 폭염 일수와 한파 일수의 차가 가장 큰 때에는 차가 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["연도별 차: 2019년 5일, 2020년 1일, 2021년 3일, 2022년 18일.","두 선 사이가 가장 많이 벌어진 때는 2022년이에요.","31 − 13 = 18 — 18일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#5','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'mc','auto','「수학익힘」 — 폭염 일수와 한파 일수의 차가 가장 작은 때는 언제인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X19']::text[],false,'{"seq":5,"concept":"M4-2-u5-C12","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 폭염 일수와 한파 일수의 차가 가장 작은 때는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2022년","mis":"M4-2-u5-X21"},{"t":"2019년","mis":"M4-2-u5-X19"},{"t":"2021년","mis":"M4-2-u5-X19"}],"explanation":["연도별 차: 2019년 5일, 2020년 1일, 2021년 3일, 2022년 18일.","두 선이 가장 가까이 붙은 때는 2020년이에요.","차가 가장 작은 때는 2020년이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#6','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'error','auto','「성장 지원 평가」 — 유소년층과 노년층 인구수 그래프를 보고 잘못 해석한 친구는 누구인가요?',ARRAY['M4-2-u5-X19','M4-2-u5-X21']::text[],false,'{"seq":6,"concept":"M4-2-u5-C12","difficulty":3,"kind":"error","stem":"「성장 지원 평가」 — 유소년층과 노년층 인구수 그래프를 보고 잘못 해석한 친구는 누구인가요?","options":[{"t":"채원 — 「유소년층 인구수는 점점 늘어나고 노년층 인구수는 점점 줄어들고 있어.」","correct":true,"mis_target":"M4-2-u5-X19"},{"t":"도윤 — 「2018년에 노년층 인구수는 유소년층 인구수보다 100만 명 더 많아.」","mis":"M4-2-u5-X21"},{"t":"지유 — 「노년층 인구수가 전년도와 비교하여 가장 많이 늘어난 때는 2020년이야.」","mis":"M4-2-u5-X21"}],"explanation":["그래프의 이름표(범례)를 보고 두 선을 먼저 가려요.","유소년층 선은 내려가고 노년층 선은 올라가요.","채원이는 두 선을 바꾸어 읽었어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#7','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'mc','auto','「스스로 역량을 기르는 과정」 — 폭염 일수와 한파 일수를 하나의 그래프로 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X14','M4-2-u5-X19']::text[],false,'{"seq":7,"concept":"M4-2-u5-C12","difficulty":3,"kind":"mc","stem":"「스스로 역량을 기르는 과정」 — 폭염 일수와 한파 일수를 하나의 그래프로 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"폭염 일수와 한파 일수를 서로 다른 색의 점과 선분으로 나타내요.","correct":true},{"t":"폭염 일수와 한파 일수를 더해서 한 선으로 나타내요.","mis":"M4-2-u5-X14"},{"t":"폭염 일수는 꺾은선으로, 한파 일수는 표로만 나타내요.","mis":"M4-2-u5-X19"},{"t":"두 자료를 서로 다른 연도에 나타내요.","mis":"M4-2-u5-X19"}],"explanation":["하나의 그래프에 두 자료를 동시에 나타내요.","같은 연도의 두 자료를 하나의 연도에 나타내요.","서로 다른 색의 점과 선분으로 구분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#8','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',4,'sa','auto','「창의가 반짝」 — 유소년층과 노년층 인구수의 차는 2018년부터 2022년까지 몇만 명 커졌나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u5-C12","difficulty":4,"kind":"sa","stem":"「창의가 반짝」 — 유소년층과 노년층 인구수의 차는 2018년부터 2022년까지 몇만 명 커졌나요? 숫자로 쓰세요.","answer":["210"],"explanation":["2018년의 차는 750 − 650 = 100만 명이에요.","2022년의 차는 900 − 590 = 310만 명이에요.","310 − 100 = 210 — 210만 명 커졌어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#9','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',4,'mc','auto','「창의가 반짝」 — 유소년층과 노년층 인구수 그래프에서 두 선 사이의 간격이 해마다 넓어지는 것은 무엇을 뜻하나요?',ARRAY['M4-2-u5-X19','M4-2-u5-X14','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C12","difficulty":4,"kind":"mc","stem":"「창의가 반짝」 — 유소년층과 노년층 인구수 그래프에서 두 선 사이의 간격이 해마다 넓어지는 것은 무엇을 뜻하나요?","options":[{"t":"유소년층 인구수와 노년층 인구수의 차가 점점 커지고 있어요.","correct":true},{"t":"두 인구수가 모두 늘어나고 있어요.","mis":"M4-2-u5-X19"},{"t":"두 인구수의 합이 해마다 같아요.","mis":"M4-2-u5-X14"},{"t":"물결선 때문에 넓어 보일 뿐이에요.","mis":"M4-2-u5-X05"}],"explanation":["두 선 사이의 간격은 두 인구수의 차예요.","차는 100만, 140만, 200만, 260만, 310만 명으로 커져요.","간격이 넓어지는 것은 차가 커진다는 뜻이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_L08_challenge#10','math',4,2,'u5','L08','tb_g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',4,'essay','teacher','「수학과 문제해결」 — 연도별 폭염 일수와 한파 일수(일) — 폭염 일수 2019년 16, 2020년 10, 2021년 22, 2022년 13 · 한파 일수 2019년 11, 2020년 9, 2021년 19, 2022년 31. 이 표를 하나의 꺾은선그래프로 나타내는 방법을 쓰고(세로 눈금 한 칸의 크기와 두 자료를 구분하는 방법 포함), 그래프에서 알 수 있는 내용을 두 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C12","difficulty":4,"kind":"essay","stem":"「수학과 문제해결」 — 연도별 폭염 일수와 한파 일수(일) — 폭염 일수 2019년 16, 2020년 10, 2021년 22, 2022년 13 · 한파 일수 2019년 11, 2020년 9, 2021년 19, 2022년 31. 이 표를 하나의 꺾은선그래프로 나타내는 방법을 쓰고(세로 눈금 한 칸의 크기와 두 자료를 구분하는 방법 포함), 그래프에서 알 수 있는 내용을 두 가지 써 보세요.","answer_guide":{"answer":"예: 가로는 연도, 세로는 일수로 하고 가장 큰 값이 31일이므로 세로 눈금 한 칸을 1일로 하여 31일까지 나타낸다. 같은 연도에 폭염 일수와 한파 일수를 서로 다른 색의 점과 선분으로 나타내고 이름표를 붙인다. 2021년은 전년도와 비교하여 폭염 일수와 한파 일수가 모두 늘어났고, 두 일수의 차가 가장 큰 때는 2022년이다.","scoring_points":["가로·세로와 세로 눈금 한 칸(1일 또는 2일)을 정했는가","서로 다른 색의 점과 선분·이름표로 구분한다고 썼는가","그래프에서 알 수 있는 내용을 두 가지 바르게 썼는가"]},"explanation":["가로는 연도, 세로는 일수예요.","두 자료는 다른 색의 점과 선분으로 구분해요.","두 선의 오르내림과 간격을 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#1','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C1',1,'mc','auto','「스스로 마무리하기」 — 「시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 □(이)라고 합니다.」 □ 안에 알맞은 말은 어느 것인가요?',ARRAY['M4-2-u5-X03','M4-2-u5-X05']::text[],false,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 「시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 □(이)라고 합니다.」 □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["점으로 표시하고 선분으로 이은 그래프예요.","이런 그래프를 꺾은선그래프라고 해요.","시간에 따른 변화를 알아보기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#2','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C2',1,'sa','auto','「스스로 마무리하기」 — 6월의 키는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 6월의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["세로 눈금 한 칸은 1 cm예요.","6월의 점을 따라 세로 눈금을 읽어요.","6월의 키는 17 cm예요."],"asset":{"type":"lgraph","xs":["4","5","6","7"],"series":[{"vals":[4,9,17,21]}],"step":1,"ymax":22,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 식물의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#3','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C2',1,'mc','auto','「스스로 마무리하기」 — 「월별 책 판매량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],false,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 「월별 책 판매량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 판매량","correct":true},{"t":"가로: 판매량, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 판매량, 세로: 판매량","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월을, 세로에는 판매량을 권 단위로 나타냈어요.","가로: 월, 세로: 판매량이에요."],"asset":{"type":"lgraph","xs":["5","6","7","8"],"series":[{"vals":[20,40,35,50]}],"step":5,"ymax":50,"ylab":"(권)","xlab":"(월)","every":5,"title":"월별 책 판매량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#4','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C5',1,'mc','auto','「스스로 마무리하기」 — 국제선 운항 횟수 표를 세로 눈금이 28칸인 꺾은선그래프로 나타내려고 해요. 가장 큰 값 53만 회까지 나타내려면 세로 눈금 한 칸을 몇만 회로 정하면 좋을까요?',ARRAY['M4-2-u5-X07','M4-2-u5-X08','M4-2-u5-X02']::text[],false,'{"seq":4,"concept":"M4-2-u5-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 국제선 운항 횟수 표를 세로 눈금이 28칸인 꺾은선그래프로 나타내려고 해요. 가장 큰 값 53만 회까지 나타내려면 세로 눈금 한 칸을 몇만 회로 정하면 좋을까요?","options":[{"t":"2만 회","correct":true},{"t":"1만 회","mis":"M4-2-u5-X07"},{"t":"10만 회","mis":"M4-2-u5-X08"},{"t":"53만 회","mis":"M4-2-u5-X02"}],"explanation":["가장 큰 값은 2019년의 53만 회예요.","한 칸을 1만 회로 하면 28칸으로 28만 회까지만 나타내요.","한 칸을 2만 회로 하면 56만 회까지 나타낼 수 있어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#5','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',1,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈어요. 운항 횟수가 가장 많은 때는 몇 년인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈어요. 운항 횟수가 가장 많은 때는 몇 년인가요? 숫자로 쓰세요.","answer":["2019"],"explanation":["꺾은선그래프에서는 가장 높이 있는 점, 표에서는 가장 큰 값이에요.","2019년의 53만 회가 가장 많아요.","가장 많은 때는 2019년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#6','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',1,'mc','auto','「스스로 마무리하기」 — 서준이의 체온이 가장 높은 때는 언제인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X21','M4-2-u5-X10']::text[],false,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 서준이의 체온이 가장 높은 때는 언제인가요?","options":[{"t":"오전 7시","correct":true},{"t":"오전 9시","mis":"M4-2-u5-X02"},{"t":"오전 10시","mis":"M4-2-u5-X21"},{"t":"오전 11시","mis":"M4-2-u5-X10"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 7시의 36.7 °C가 가장 높아요.","가장 높은 때는 오전 7시예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#7','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C11',1,'mc','auto','「스스로 마무리하기」 — 우리나라 유적지의 관람객 수를 연도별로 조사한 표예요. 관람객 수의 변화를 알아보기 쉽게 나타내려면 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 우리나라 유적지의 관람객 수를 연도별로 조사한 표예요. 관람객 수의 변화를 알아보기 쉽게 나타내려면 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["목적은 관람객 수의 변화를 알아보는 거예요.","연도별로 달라지는 자료예요.","시간에 따른 변화를 알아보기에는 꺾은선그래프가 편리해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[1224,1452,590,754,1190],"vh":"관람객 수","unit":"만 명","total":false,"title":"연도별 유적지의 관람객 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#8','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C10',1,'mc','auto','「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. ① 조사하고 싶은 주제를 정합니다. ② 주제에 따른 □을/를 정합니다. □ 안에 알맞은 말은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],false,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. ① 조사하고 싶은 주제를 정합니다. ② 주제에 따른 □을/를 정합니다. □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"항목","correct":true},{"t":"주제","mis":"M4-2-u5-X21"},{"t":"방법","mis":"M4-2-u5-X21"},{"t":"꺾은선그래프","mis":"M4-2-u5-X21"}],"explanation":["① 주제 → ② 항목 → ③ 방법·수집 → ④ 꺾은선그래프로 나타내고 해석해요.","차례를 떠올려 빈칸을 채워요.","□ 안에 알맞은 말은 항목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#9','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 오전 7시의 체온은 몇 °C인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 오전 7시의 체온은 몇 °C인가요?","options":[{"t":"36.7 °C","correct":true},{"t":"36.8 °C","mis":"M4-2-u5-X02"},{"t":"7 °C","mis":"M4-2-u5-X05"},{"t":"36.6 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 7시의 점을 따라 세로 눈금을 읽어요.","오전 7시의 체온은 36.7 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#10','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C6',2,'mc','auto','「스스로 마무리하기」 — 인구수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 인구수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?","options":[{"t":"0부터 31만 명 사이","correct":true},{"t":"34만 명과 36만 명 사이","mis":"M4-2-u5-X09"},{"t":"38만 명보다 위","mis":"M4-2-u5-X09"},{"t":"0부터 38만 명 사이","mis":"M4-2-u5-X09"}],"explanation":["가장 작은 값은 31만 명이에요.","물결선은 0과 가장 작은 값 사이에 넣어요.","0부터 31만 명 사이에 넣어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[31,34,36,37,38],"vh":"인구수","unit":"만 명","total":false,"title":"연도별 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#11','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',2,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수는 2020년에 2019년보다 몇만 회 줄어들었나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수는 2020년에 2019년보다 몇만 회 줄어들었나요? 숫자로 쓰세요.","answer":["36"],"explanation":["2019년은 53만 회, 2020년은 17만 회예요.","두 해의 값만 써서 빼요.","53 − 17 = 36 — 36만 회 줄어들었어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#12','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C9',2,'mc','auto','「스스로 마무리하기」 — 전월과 비교하여 자외선 지수 매우 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],false,'{"seq":12,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 전월과 비교하여 자외선 지수 매우 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?","options":[{"t":"5월","correct":true},{"t":"7월","mis":"M4-2-u5-X12"},{"t":"8월","mis":"M4-2-u5-X10"},{"t":"6월","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 위로 올라간 선분 가운데 가장 가파른 곳을 찾아요.","4월에서 5월로 13일 늘었어요.","가장 많이 늘어난 때는 5월이에요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[4,17,18,22,17]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 매우 높음 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#13','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 1인당 하루 물 사용량이 변하지 않은 때는 몇 년부터 몇 년까지인가요?',ARRAY['M4-2-u5-X13']::text[],false,'{"seq":13,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 1인당 하루 물 사용량이 변하지 않은 때는 몇 년부터 몇 년까지인가요?","options":[{"t":"2018년부터 2020년까지","correct":true},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2020년부터 2021년까지","mis":"M4-2-u5-X13"},{"t":"변하지 않은 때가 없어요.","mis":"M4-2-u5-X13"}],"explanation":["선분이 평평한 곳이 변하지 않은 때예요.","2018년, 2019년, 2020년이 모두 295 L예요.","2018년부터 2020년까지 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[289,295,295,295,302]}],"step":1,"ymax":303,"ylab":"(L)","xlab":"(년)","y0":285,"wave":true,"every":5,"title":"연도별 1인당 하루 물 사용량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#14','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C12',2,'mc','auto','「스스로 마무리하기」 — 유소년층과 노년층 인구수 그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X19','M4-2-u5-X10']::text[],false,'{"seq":14,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 유소년층과 노년층 인구수 그래프를 보고 알 수 있는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"유소년층 인구수는 줄어들고, 노년층 인구수는 늘어나고 있어요.","correct":true},{"t":"유소년층 인구수는 늘어나고, 노년층 인구수는 줄어들고 있어요.","mis":"M4-2-u5-X19"},{"t":"두 인구수가 모두 늘어나고 있어요.","mis":"M4-2-u5-X10"},{"t":"두 인구수의 차가 점점 작아져요.","mis":"M4-2-u5-X19"}],"explanation":["이름표로 두 선을 먼저 가려요.","유소년층 선은 내려가고 노년층 선은 올라가요.","두 인구수의 차는 점점 커져요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#15','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C3',2,'mc','auto','「스스로 마무리하기」 — 지유의 나무의 키는 5월에 100 cm, 7월에 120 cm였어요. 6월의 나무의 키는 약 몇 cm였을까요?',ARRAY['M4-2-u5-X04']::text[],false,'{"seq":15,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 지유의 나무의 키는 5월에 100 cm, 7월에 120 cm였어요. 6월의 나무의 키는 약 몇 cm였을까요?","options":[{"t":"약 110 cm","correct":true},{"t":"약 100 cm","mis":"M4-2-u5-X04"},{"t":"약 120 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["6월은 5월과 7월의 한가운데예요.","두 점을 이은 선분 위에서 짐작해요.","약 110 cm였을 거예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3","5","7","9","11"],"counts":[85,100,120,145,170],"vh":"나무의 키","unit":"cm","total":false,"title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#16','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C9',2,'mc','auto','「스스로 마무리하기」 — 1인당 하루 물 사용량은 앞으로 어떻게 변화할까요?',ARRAY['M4-2-u5-X25','M4-2-u5-X10','M4-2-u5-X04']::text[],false,'{"seq":16,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 1인당 하루 물 사용량은 앞으로 어떻게 변화할까요?","options":[{"t":"더 많아질 것 — 전체적으로 오른쪽 위로 올라가고 있어서","correct":true},{"t":"변하지 않을 것 — 2018~2020년이 같아서","mis":"M4-2-u5-X25"},{"t":"줄어들 것","mis":"M4-2-u5-X10"},{"t":"알 수 없어요","mis":"M4-2-u5-X04"}],"explanation":["처음부터 끝까지 전체 흐름을 봐요.","전체적으로 오른쪽 위로 올라가요.","더 많아질 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[289,295,295,295,302]}],"step":1,"ymax":303,"ylab":"(L)","xlab":"(년)","y0":285,"wave":true,"every":5,"title":"연도별 1인당 하루 물 사용량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#17','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C3',3,'error','auto','「스스로 마무리하기」 — 가로등의 그림자 길이 그래프를 보고 잘못 이야기한 사람은 누구인가요?',ARRAY['M4-2-u5-X04','M4-2-u5-X21']::text[],false,'{"seq":17,"concept":"M4-2-u5-C3","difficulty":3,"kind":"error","stem":"「스스로 마무리하기」 — 가로등의 그림자 길이 그래프를 보고 잘못 이야기한 사람은 누구인가요?","options":[{"t":"정후 — 「오후 2시 30분의 가로등의 그림자 길이는 100 cm였을 것 같아.」","correct":true,"mis_target":"M4-2-u5-X04"},{"t":"서윤 — 「두 그래프 모두 세로 눈금 한 칸은 10 cm를 나타내.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「가로등의 그림자 길이는 오후 4시에 오후 3시보다 10 cm 더 늘어났어.」","mis":"M4-2-u5-X21"}],"explanation":["오후 2시는 50 cm, 오후 3시는 90 cm예요.","2시 30분은 두 점 사이에서 약 70 cm예요.","정후가 잘못 이야기했어요."],"asset":{"type":"lgraph","xs":["1","2","3","4"],"series":[{"vals":[40,50,90,100]}],"step":10,"ymax":100,"ylab":"(cm)","xlab":"(시)","every":5,"title":"시각별 가로등의 그림자 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#18','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C4',3,'mc','auto','「스스로 마무리하기」 — 친구가 선인장 줄기의 길이를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07','M4-2-u5-X01']::text[],false,'{"seq":18,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 친구가 선인장 줄기의 길이를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점을 가로 눈금의 순서대로 잇지 않았어요.","correct":true},{"t":"점을 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금 한 칸을 2 cm로 정했어요.","mis":"M4-2-u5-X07"},{"t":"가로와 세로를 바꾸었어요.","mis":"M4-2-u5-X01"}],"explanation":["점은 가로 눈금의 순서대로 이어야 해요.","7월에서 9월로 건너뛰어 이었어요.","순서대로 잇지 않으면 잘못된 정보를 줘요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[10,18,26,30,32]}],"step":2,"ymax":34,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 선인장 줄기의 길이","order":[0,2,1,3,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#19','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C9',3,'sa','auto','「스스로 마무리하기」 — 월별 최고 온도 그래프에서 전월과 비교하여 가장 많이 변한 때에는 몇 °C 변했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 월별 최고 온도 그래프에서 전월과 비교하여 가장 많이 변한 때에는 몇 °C 변했나요? 숫자로 쓰세요.","answer":["6"],"explanation":["변화: 4 °C 오름, 2 °C 오름, 6 °C 내림, 5 °C 내림.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 9월, 6 °C예요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[30,34,36,30,25]}],"step":1,"ymax":37,"ylab":"(°C)","xlab":"(월)","y0":20,"wave":true,"every":5,"title":"월별 최고 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#20','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C11',3,'mc','auto','「스스로 마무리하기」 — 같은 해수면 높이 자료를 채원이는 막대그래프로, 도윤이는 꺾은선그래프로 나타냈어요. 알맞은 생각은 어느 것인가요?',ARRAY['M4-2-u5-X23','M4-2-u5-X17']::text[],false,'{"seq":20,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 같은 해수면 높이 자료를 채원이는 막대그래프로, 도윤이는 꺾은선그래프로 나타냈어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"둘 다 알맞아요 — 목적에 따라 알맞은 그래프가 달라요.","correct":true},{"t":"도윤이만 맞아요 — 연도별 자료는 꼭 꺾은선그래프예요.","mis":"M4-2-u5-X23"},{"t":"채원이만 맞아요.","mis":"M4-2-u5-X23"},{"t":"둘 다 틀려요.","mis":"M4-2-u5-X17"}],"explanation":["채원이는 비교하려고, 도윤이는 변화를 알아보려고 했어요.","하나의 자료도 여러 그래프로 나타낼 수 있어요.","목적에 맞으면 둘 다 알맞아요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[27,30,34,32,32]}],"step":1,"ymax":35,"ylab":"(cm)","xlab":"(년)","every":10,"title":"연도별 해수면 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#21','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C5',3,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수(가장 큰 값 53만 회)를 세로 눈금 한 칸이 2만 회인 그래프로 나타내려고 해요. 가장 큰 값까지 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수(가장 큰 값 53만 회)를 세로 눈금 한 칸이 2만 회인 그래프로 나타내려고 해요. 가장 큰 값까지 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.","answer":["27"],"explanation":["한 칸이 2만 회이므로 26칸이면 52만 회예요.","53만 회는 52만 회보다 커서 한 칸이 더 필요해요.","세로 눈금이 적어도 27칸 있어야 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#22','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C6',3,'ox','auto','「스스로 마무리하기」 — 꺾은선그래프에서 물결선은 자료의 수 범위 안에 넣어도 돼요.',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":22,"concept":"M4-2-u5-C6","difficulty":3,"kind":"ox","stem":"「스스로 마무리하기」 — 꺾은선그래프에서 물결선은 자료의 수 범위 안에 넣어도 돼요.","answer":"X","reason_options":[{"t":"자료의 수 범위 안에 넣으면 꺾은선의 기울기가 사실과 다르게 보여서","correct":true},{"t":"물결선은 어디에 넣어도 값이 그대로라서","mis":"M4-2-u5-X09"}],"mis":"M4-2-u5-X09","explanation":["물결선은 나타낼 필요가 없는 부분만 줄여요.","자료의 수 범위를 가로지르면 기울기가 사실과 달라져요.","0과 가장 작은 값 사이에만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#23','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',4,'essay','teacher','「스스로 마무리하기」 — 연도별 국제선 운항 횟수 표를 꺾은선그래프로 나타내고, 그래프를 보고 알 수 있는 내용을 세 가지 써 보세요. 가장 많은 때·가장 적은 때와 운항 횟수의 변화가 가장 큰 때를 꼭 넣어요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u5-C8","difficulty":4,"kind":"essay","stem":"「스스로 마무리하기」 — 연도별 국제선 운항 횟수 표를 꺾은선그래프로 나타내고, 그래프를 보고 알 수 있는 내용을 세 가지 써 보세요. 가장 많은 때·가장 적은 때와 운항 횟수의 변화가 가장 큰 때를 꼭 넣어요.","answer_guide":{"answer":"예: 국제선 운항 횟수가 가장 많은 때는 2019년이고, 가장 적은 때는 2021년이다. 전년도와 비교하여 운항 횟수의 변화가 가장 크면서 처음으로 줄어든 때는 2020년이다. 2017년부터 2019년까지는 조금씩 늘어났다.","scoring_points":["가장 많은 때 2019년·가장 적은 때 2021년을 썼는가","변화가 가장 큰 때 2020년을 썼는가","그래프에 근거한 사실만 썼는가"]},"explanation":["표를 꺾은선그래프로 나타내면 가장 높은 점과 가장 낮은 점이 보여요.","위로든 아래로든 가장 가파른 선분을 찾아요.","그래프에 나타난 사실을 근거로 써요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#24','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',4,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수는 2017년부터 2019년까지 몇만 회 늘어났나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수는 2017년부터 2019년까지 몇만 회 늘어났나요? 숫자로 쓰세요.","answer":["7"],"explanation":["2017년은 46만 회, 2019년은 53만 회예요.","처음과 끝 두 해의 값만 써서 빼요.","53 − 46 = 7 — 7만 회 늘어났어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_a#25','math',4,2,'u5','','tb_g4_2_math_u5_review_a','unit_review','M4-2-u5-C9',4,'mc','auto','「스스로 마무리하기」 — 전년도와 비교하여 국제선 운항 횟수의 변화가 가장 크면서 운항 횟수가 처음으로 줄어든 때는 언제인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X12','M4-2-u5-X10']::text[],false,'{"seq":25,"concept":"M4-2-u5-C9","difficulty":4,"kind":"mc","stem":"「스스로 마무리하기」 — 전년도와 비교하여 국제선 운항 횟수의 변화가 가장 크면서 운항 횟수가 처음으로 줄어든 때는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2021년","mis":"M4-2-u5-X21"},{"t":"2019년","mis":"M4-2-u5-X12"},{"t":"2018년","mis":"M4-2-u5-X10"}],"explanation":["2019년까지 늘다가 2020년에 처음 줄어들었어요.","2020년에는 36만 회가 줄어 변화가 가장 커요.","답은 2020년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#1','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C1',1,'mc','auto','「스스로 마무리하기」 — 꺾은선그래프에서 가로 눈금과 세로 눈금이 만나는 곳에 찍은 점들은 무엇으로 잇나요?',ARRAY['M4-2-u5-X06','M4-2-u5-X03','M4-2-u5-X05']::text[],false,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 꺾은선그래프에서 가로 눈금과 세로 눈금이 만나는 곳에 찍은 점들은 무엇으로 잇나요?","options":[{"t":"선분","correct":true},{"t":"곡선","mis":"M4-2-u5-X06"},{"t":"막대","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["꺾은선그래프는 점들을 곧은 선으로 이어요.","점과 점을 순서대로 선분으로 이어요.","곡선으로 이으면 잘못된 정보를 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#2','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C2',1,'sa','auto','「스스로 마무리하기」 — 5월의 키는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 5월의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금 한 칸은 1 cm예요.","5월의 점을 따라 세로 눈금을 읽어요.","5월의 키는 9 cm예요."],"asset":{"type":"lgraph","xs":["4","5","6","7"],"series":[{"vals":[4,9,17,21]}],"step":1,"ymax":22,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 식물의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#3','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C2',1,'mc','auto','「스스로 마무리하기」 — 「연도별 우리나라의 우유 생산량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],false,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 「연도별 우리나라의 우유 생산량」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 연도, 세로: 생산량","correct":true},{"t":"가로: 생산량, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 생산량, 세로: 생산량","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 연도를, 세로에는 생산량을 만 톤 단위로 나타냈어요.","가로: 연도, 세로: 생산량이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[204,205,209,203,198]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","y0":195,"wave":true,"every":5,"title":"연도별 우리나라의 우유 생산량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#4','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C5',1,'mc','auto','「스스로 마무리하기」 — 미세 먼지 나쁨 일수 표를 세로 눈금이 25칸인 그래프로 나타내려고 해요. 세로 눈금 한 칸을 몇 일로 정하면 좋을까요?',ARRAY['M4-2-u5-X07','M4-2-u5-X02']::text[],false,'{"seq":4,"concept":"M4-2-u5-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 미세 먼지 나쁨 일수 표를 세로 눈금이 25칸인 그래프로 나타내려고 해요. 세로 눈금 한 칸을 몇 일로 정하면 좋을까요?","options":[{"t":"1일","correct":true},{"t":"5일","mis":"M4-2-u5-X07"},{"t":"2일","mis":"M4-2-u5-X07"},{"t":"25일","mis":"M4-2-u5-X02"}],"explanation":["가장 큰 값은 25일이에요.","한 칸을 1일로 하면 25칸으로 25일까지 나타내요.","5일이나 2일로 하면 눈금 사이에 오는 값이 생겨요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#5','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',1,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈어요. 운항 횟수가 가장 적은 때는 몇 년인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈어요. 운항 횟수가 가장 적은 때는 몇 년인가요? 숫자로 쓰세요.","answer":["2021"],"explanation":["꺾은선그래프에서는 가장 낮게 있는 점, 표에서는 가장 작은 값이에요.","2021년의 13만 회가 가장 적어요.","가장 적은 때는 2021년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#6','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',1,'mc','auto','「스스로 마무리하기」 — 서준이의 체온이 가장 낮은 때는 언제인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X02']::text[],false,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 서준이의 체온이 가장 낮은 때는 언제인가요?","options":[{"t":"오전 10시","correct":true},{"t":"오전 7시","mis":"M4-2-u5-X21"},{"t":"오전 8시","mis":"M4-2-u5-X02"},{"t":"오전 11시","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 10시의 36.3 °C가 가장 낮아요.","가장 낮은 때는 오전 10시예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#7','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C11',1,'mc','auto','「스스로 마무리하기」 — 강별 수질 오염 발생 횟수를 한눈에 비교하려면 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 강별 수질 오염 발생 횟수를 한눈에 비교하려면 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"그림그래프 또는 막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선을 넣은 꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["강별 자료는 시간에 따른 자료가 아니에요.","목적은 한눈에 비교하는 거예요.","그림그래프나 막대그래프가 편리해요."],"asset":{"type":"picg","only":"table","head":"강","cols":["가","나","다","라","마"],"counts":[14,16,2,10,21],"vh":"횟수","unit":"회","total":false,"title":"강별 수질 오염 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#8','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C10',1,'mc','auto','「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. ③ 자료를 수집할 □을/를 정하고, 자료를 수집합니다. □ 안에 알맞은 말은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],false,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. ③ 자료를 수집할 □을/를 정하고, 자료를 수집합니다. □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"방법","correct":true},{"t":"주제","mis":"M4-2-u5-X21"},{"t":"항목","mis":"M4-2-u5-X21"},{"t":"꺾은선그래프","mis":"M4-2-u5-X21"}],"explanation":["① 주제 → ② 항목 → ③ 방법·수집 → ④ 꺾은선그래프로 나타내고 해석해요.","차례를 떠올려 빈칸을 채워요.","□ 안에 알맞은 말은 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#9','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 오전 8시의 체온은 몇 °C인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 오전 8시의 체온은 몇 °C인가요?","options":[{"t":"36.5 °C","correct":true},{"t":"36.6 °C","mis":"M4-2-u5-X02"},{"t":"5 °C","mis":"M4-2-u5-X05"},{"t":"36.4 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 8시의 점을 따라 세로 눈금을 읽어요.","오전 8시의 체온은 36.5 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#10','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C6',2,'mc','auto','「스스로 마무리하기」 — 해바라기의 키 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 해바라기의 키 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?","options":[{"t":"0부터 180 cm 사이","correct":true},{"t":"186 cm와 190 cm 사이","mis":"M4-2-u5-X09"},{"t":"193 cm보다 위","mis":"M4-2-u5-X09"},{"t":"0부터 193 cm 사이","mis":"M4-2-u5-X09"}],"explanation":["가장 작은 값은 180 cm예요.","물결선은 0과 가장 작은 값 사이에 넣어요.","0부터 180 cm 사이에 넣어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6","7","8","9","10"],"counts":[180,183,186,190,193],"vh":"키","unit":"cm","total":false,"title":"월별 해바라기의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#11','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',2,'sa','auto','「스스로 마무리하기」 — 마당에 쌓인 눈의 높이는 오후 3시에 낮 12시보다 몇 mm 더 높은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"「스스로 마무리하기」 — 마당에 쌓인 눈의 높이는 오후 3시에 낮 12시보다 몇 mm 더 높은가요? 숫자로 쓰세요.","answer":["10"],"explanation":["낮 12시는 7 mm, 오후 3시는 17 mm예요.","두 시각의 값만 써서 빼요.","17 − 7 = 10 — 10 mm 더 높아요."],"asset":{"type":"lgraph","xs":["11","12","1","2","3"],"series":[{"vals":[2,7,9,14,17]}],"step":1,"ymax":18,"ylab":"(mm)","xlab":"(시)","every":5,"title":"시각별 마당에 쌓인 눈의 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#12','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C9',2,'mc','auto','「스스로 마무리하기」 — 전 시각과 비교하여 방문자 수가 가장 많이 늘어난 때는 몇 시인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],false,'{"seq":12,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 전 시각과 비교하여 방문자 수가 가장 많이 늘어난 때는 몇 시인가요?","options":[{"t":"오후 6시","correct":true},{"t":"오후 7시","mis":"M4-2-u5-X12"},{"t":"오후 8시","mis":"M4-2-u5-X10"},{"t":"오후 5시","mis":"M4-2-u5-X21"}],"explanation":["늘어난 수: 오후 5시 1명, 6시 8명, 7시 3명.","오후 5시에서 6시로 가장 가파르게 올라가요.","가장 많이 늘어난 때는 오후 6시예요."],"asset":{"type":"lgraph","xs":["4","5","6","7","8"],"series":[{"vals":[8,9,17,20,12]}],"step":1,"ymax":21,"ylab":"(명)","xlab":"(시)","every":5,"title":"시각별 방문자 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#13','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 컵의 무게가 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],false,'{"seq":13,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 컵의 무게가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"오전 10시 20분부터 오전 10시 25분까지","correct":true},{"t":"오전 10시 5분부터 오전 10시 10분까지","mis":"M4-2-u5-X13"},{"t":"오전 10시 15분부터 오전 10시 20분까지","mis":"M4-2-u5-X13"},{"t":"변하지 않은 때가 없어요.","mis":"M4-2-u5-X13"}],"explanation":["선분이 평평한 곳이 변하지 않은 때예요.","오전 10시 20분과 25분 모두 222.5 g이에요.","오전 10시 20분부터 변하지 않았어요."],"asset":{"type":"lgraph","xs":["5","10","15","20","25"],"series":[{"vals":[221.5,221.9,222.2,222.5,222.5]}],"step":0.1,"ymax":222.6,"ylab":"(g)","xlab":"(분)","y0":221.5,"wave":true,"every":5,"title":"시각별 컵의 무게"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#14','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C12',2,'mc','auto','「스스로 마무리하기」 — 2020년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?',ARRAY['M4-2-u5-X10','M4-2-u5-X19']::text[],false,'{"seq":14,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 2020년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?","options":[{"t":"모두 줄어들었어요.","correct":true},{"t":"모두 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"폭염 일수만 줄어들었어요.","mis":"M4-2-u5-X19"},{"t":"한파 일수만 줄어들었어요.","mis":"M4-2-u5-X19"}],"explanation":["폭염 일수는 16일에서 10일로, 한파 일수는 11일에서 9일로 바뀌었어요.","두 선 모두 오른쪽 아래로 내려가요.","모두 줄어들었어요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#15','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C3',2,'mc','auto','「스스로 마무리하기」 — 그래프를 보고 짐작하면 8월의 나무의 키는 약 몇 cm였을까요?',ARRAY['M4-2-u5-X04']::text[],false,'{"seq":15,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 그래프를 보고 짐작하면 8월의 나무의 키는 약 몇 cm였을까요?","options":[{"t":"약 120 cm","correct":true},{"t":"약 110 cm","mis":"M4-2-u5-X04"},{"t":"약 130 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["7월은 110 cm, 9월은 130 cm예요.","8월은 두 달의 한가운데예요.","약 120 cm였을 거예요."],"asset":{"type":"lgraph","xs":["3","5","7","9","11"],"series":[{"vals":[50,80,110,130,170]}],"step":10,"ymax":180,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#16','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C9',2,'mc','auto','「스스로 마무리하기」 — 2023년도의 1인당 쌀 소비량은 어떻게 될까요?',ARRAY['M4-2-u5-X25','M4-2-u5-X10','M4-2-u5-X04']::text[],false,'{"seq":16,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 2023년도의 1인당 쌀 소비량은 어떻게 될까요?","options":[{"t":"줄어들 것 — 전체적으로 오른쪽 아래로 내려가고 있어서","correct":true},{"t":"변하지 않을 것 — 2021년과 2022년이 같아서","mis":"M4-2-u5-X25"},{"t":"늘어날 것","mis":"M4-2-u5-X10"},{"t":"알 수 없어요","mis":"M4-2-u5-X04"}],"explanation":["처음부터 끝까지 전체 흐름을 봐요.","전체적으로 오른쪽 아래로 내려가요.","줄어들 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[61,59,58,57,57]}],"step":1,"ymax":62,"ylab":"(kg)","xlab":"(년)","y0":55,"wave":true,"every":5,"title":"연도별 1인당 쌀 소비량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#17','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C9',3,'error','auto','「스스로 마무리하기」 — 월별 최고 온도 그래프를 보고 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],false,'{"seq":17,"concept":"M4-2-u5-C9","difficulty":3,"kind":"error","stem":"「스스로 마무리하기」 — 월별 최고 온도 그래프를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「전월과 비교하여 최고 온도가 가장 많이 변한 때는 가장 많이 늘어난 7월이야.」","correct":true,"mis_target":"M4-2-u5-X11"},{"t":"지유 — 「8월의 최고 온도는 36 °C야.」","mis":"M4-2-u5-X21"},{"t":"건우 — 「9월에는 전월보다 최고 온도가 6 °C 낮아졌어.」","mis":"M4-2-u5-X21"}],"explanation":["변화한 양은 늘어난 양과 줄어든 양을 모두 포함해요.","9월에 6 °C 줄어 가장 많이 변했어요.","서준이는 늘어난 곳만 보았어요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[30,34,36,30,25]}],"step":1,"ymax":37,"ylab":"(°C)","xlab":"(월)","y0":20,"wave":true,"every":5,"title":"월별 최고 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#18','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C4',3,'mc','auto','「스스로 마무리하기」 — 친구가 월별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07','M4-2-u5-X01']::text[],false,'{"seq":18,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 친구가 월별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점과 점을 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금 한 칸을 1일로 정했어요.","mis":"M4-2-u5-X07"},{"t":"가로에 월을 나타냈어요.","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 점과 점을 선분으로 이어요.","곡선으로 이으면 사이 값을 예상할 수 없어요.","선분으로 다시 이어야 해요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[2,4,9,2,2]}],"step":1,"ymax":10,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 미세 먼지 나쁨 일수","curve":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#19','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C9',3,'sa','auto','「스스로 마무리하기」 — 폭염 일수 그래프에서 전년도와 비교하여 가장 많이 변한 때에는 며칠 변했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 폭염 일수 그래프에서 전년도와 비교하여 가장 많이 변한 때에는 며칠 변했나요? 숫자로 쓰세요.","answer":["14"],"explanation":["변화: 11일 줄고, 14일 늘고, 8일 줄고, 9일 늘었어요.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 2021년, 14일이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#20','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C11',3,'mc','auto','「스스로 마무리하기」 — 강아지의 몸무게를 막대그래프로 나타냈어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17','M4-2-u5-X13']::text[],false,'{"seq":20,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 강아지의 몸무게를 막대그래프로 나타냈어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"틀린 그래프는 아니지만, 변화를 알아보기에는 꺾은선그래프가 더 편리해요.","correct":true},{"t":"이어진 자료를 막대로 나타냈으니 틀린 그래프예요.","mis":"M4-2-u5-X18"},{"t":"변화를 알아보기에는 막대그래프가 가장 좋아요.","mis":"M4-2-u5-X17"},{"t":"막대가 같은 높이인 달이 없어요.","mis":"M4-2-u5-X13"}],"explanation":["막대그래프로 나타냈다고 틀린 것은 아니에요.","변화의 경향을 알아보기에는 꺾은선그래프가 편리해요.","8월과 9월은 막대 높이가 같아요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[4,5,5,6,7]}],"step":1,"ymax":8,"ylab":"(kg)","xlab":"(월)","every":5,"title":"월별 강아지의 몸무게","mode":"bar"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#21','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C5',3,'sa','auto','「스스로 마무리하기」 — 선인장 줄기의 길이(가장 큰 값 32 cm)를 세로 눈금 한 칸이 2 cm인 그래프로 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 선인장 줄기의 길이(가장 큰 값 32 cm)를 세로 눈금 한 칸이 2 cm인 그래프로 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.","answer":["16"],"explanation":["가장 큰 값은 32 cm예요.","32 ÷ 2 = 16이에요.","적어도 16칸 있어야 해요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[10,18,26,30,32],"vh":"길이","unit":"cm","total":false,"title":"월별 선인장 줄기의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#22','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C11',3,'ox','auto','「스스로 마무리하기」 — 연속된 자료는 무조건 꺾은선그래프로 나타내야 해요.',ARRAY['M4-2-u5-X18']::text[],false,'{"seq":22,"concept":"M4-2-u5-C11","difficulty":3,"kind":"ox","stem":"「스스로 마무리하기」 — 연속된 자료는 무조건 꺾은선그래프로 나타내야 해요.","answer":"X","reason_options":[{"t":"막대그래프로 나타내도 틀린 것은 아니고 목적에 맞게 고르면 돼서","correct":true},{"t":"연속된 자료를 막대로 나타내면 틀린 그래프라서","mis":"M4-2-u5-X18"}],"mis":"M4-2-u5-X18","explanation":["연속된 자료도 막대그래프로 나타낼 수 있어요.","다만 변화의 경향을 알아보기에는 꺾은선그래프가 편리해요.","자료의 특성과 목적에 맞는 그래프를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#23','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C11',4,'essay','teacher','「스스로 마무리하기」 — 우리나라 유적지의 관람객 수 표를 보고 관람객 수의 변화를 알아보기 쉽게 나타내려면 어떤 그래프로 나타내면 좋을지 고르고, 그 이유를 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u5-C11","difficulty":4,"kind":"essay","stem":"「스스로 마무리하기」 — 우리나라 유적지의 관람객 수 표를 보고 관람객 수의 변화를 알아보기 쉽게 나타내려면 어떤 그래프로 나타내면 좋을지 고르고, 그 이유를 써 보세요.","answer_guide":{"answer":"예: 꺾은선그래프로 나타내면 좋다. 관람객 수는 연도별로 달라지는 자료이고, 시간에 따른 자료의 변화를 알아보기에는 꺾은선그래프가 편리하기 때문이다.","scoring_points":["꺾은선그래프를 골랐는가","시간(연도)에 따라 달라지는 자료라고 썼는가","변화를 알아보기 편리하다는 이유를 썼는가"]},"explanation":["관람객 수는 연도별 자료예요.","목적은 변화를 알아보는 거예요.","꺾은선그래프가 편리해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[1224,1452,590,754,1190],"vh":"관람객 수","unit":"만 명","total":false,"title":"연도별 유적지의 관람객 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#24','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',4,'sa','auto','「이런 활동도 있어요」 — 양파 싹의 길이는 25일에 19일보다 몇 cm 더 길어졌나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"「이런 활동도 있어요」 — 양파 싹의 길이는 25일에 19일보다 몇 cm 더 길어졌나요? 숫자로 쓰세요.","answer":["9"],"explanation":["19일은 15 cm, 25일은 24 cm예요.","두 날의 값만 써서 빼요.","24 − 15 = 9 — 9 cm 더 길어졌어요."],"asset":{"type":"lgraph","xs":["1","7","13","19","25"],"series":[{"vals":[0,3,7,15,24]}],"step":1,"ymax":25,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 양파 싹의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_b#25','math',4,2,'u5','','tb_g4_2_math_u5_review_b','unit_review','M4-2-u5-C7',4,'mc','auto','「수학에 퐁당」 — 연도별 농촌으로 돌아가는 가구 수 표에서 전년도와 비교하여 가장 많이 줄어든 해는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X10','M4-2-u5-X12']::text[],false,'{"seq":25,"concept":"M4-2-u5-C7","difficulty":4,"kind":"mc","stem":"「수학에 퐁당」 — 연도별 농촌으로 돌아가는 가구 수 표에서 전년도와 비교하여 가장 많이 줄어든 해는 언제인가요?","options":[{"t":"2022년","correct":true},{"t":"2019년","mis":"M4-2-u5-X11"},{"t":"2020년","mis":"M4-2-u5-X10"},{"t":"2021년","mis":"M4-2-u5-X12"}],"explanation":["줄어든 해는 2019년과 2022년이에요.","2022년이 4만 가구 넘게 줄어 더 많이 줄었어요.","답은 2022년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[328343,317660,345205,363397,318769],"vh":"가구 수","unit":"가구","total":false,"title":"연도별 농촌으로 돌아가는 가구 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#1','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C1',1,'mc','auto','「스스로 마무리하기」 — 꺾은선그래프에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X04','M4-2-u5-X06','M4-2-u5-X02']::text[],false,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 꺾은선그래프에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"조사하지 않은 중간의 값을 예상할 수 있어요.","correct":true},{"t":"조사한 때의 값만 알 수 있어요.","mis":"M4-2-u5-X04"},{"t":"점과 점을 잇지 않아도 돼요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금 한 칸은 언제나 1이에요.","mis":"M4-2-u5-X02"}],"explanation":["꺾은선그래프는 점들을 선분으로 이어요.","두 점을 이은 선분 위에서 사이 값을 예상할 수 있어요.","세로 눈금 한 칸은 그래프마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#2','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C2',1,'sa','auto','「이런 활동도 있어요」 — 19일의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"sa","stem":"「이런 활동도 있어요」 — 19일의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["세로 눈금 한 칸은 1 cm예요.","19일의 점을 따라 세로 눈금을 읽어요.","19일의 길이는 15 cm예요."],"asset":{"type":"lgraph","xs":["1","7","13","19","25"],"series":[{"vals":[0,3,7,15,24]}],"step":1,"ymax":25,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 양파 싹의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#3','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C2',1,'mc','auto','「스스로 마무리하기」 — 「서준이의 날짜별 운동 시간」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],false,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 「서준이의 날짜별 운동 시간」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 날짜, 세로: 운동 시간","correct":true},{"t":"가로: 운동 시간, 세로: 날짜","mis":"M4-2-u5-X01"},{"t":"가로: 날짜, 세로: 날짜","mis":"M4-2-u5-X01"},{"t":"가로: 운동 시간, 세로: 운동 시간","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 날짜를, 세로에는 운동 시간을 분 단위로 나타냈어요.","가로: 날짜, 세로: 운동 시간이에요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[30,38,46,34,54]}],"step":2,"ymax":56,"ylab":"(분)","xlab":"(일)","y0":30,"wave":true,"every":5,"title":"서준이의 날짜별 운동 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#4','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C5',1,'mc','auto','「스스로 마무리하기」 — 선인장 줄기의 길이 표를 꺾은선그래프로 나타낼 때 세로 눈금 한 칸을 몇 cm로 정하면 좋을까요?',ARRAY['M4-2-u5-X07','M4-2-u5-X08','M4-2-u5-X02']::text[],false,'{"seq":4,"concept":"M4-2-u5-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 선인장 줄기의 길이 표를 꺾은선그래프로 나타낼 때 세로 눈금 한 칸을 몇 cm로 정하면 좋을까요?","options":[{"t":"2 cm","correct":true},{"t":"3 cm","mis":"M4-2-u5-X07"},{"t":"10 cm","mis":"M4-2-u5-X08"},{"t":"32 cm","mis":"M4-2-u5-X02"}],"explanation":["표의 값은 10, 18, 26, 30, 32 cm로 모두 짝수예요.","한 칸을 2 cm로 하면 모든 값이 눈금 위에 와요.","세로 눈금 한 칸은 2 cm가 좋아요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[10,18,26,30,32],"vh":"길이","unit":"cm","total":false,"title":"월별 선인장 줄기의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#5','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',1,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈어요. 운항 횟수가 처음으로 줄어든 때는 몇 년인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈어요. 운항 횟수가 처음으로 줄어든 때는 몇 년인가요? 숫자로 쓰세요.","answer":["2020"],"explanation":["꺾은선그래프가 오른쪽 아래로 바뀌기 시작한 곳 — 표에서 처음으로 전년도보다 작아진 해를 찾아요.","2019년까지 늘다가 2020년에 처음 줄어들었어요.","처음으로 줄어든 때는 2020년이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#6','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',1,'mc','auto','「스스로 마무리하기」 — 서준이의 체온이 전 시각과 비교하여 올라간 때를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u5-X10','M4-2-u5-X12','M4-2-u5-X21']::text[],false,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 서준이의 체온이 전 시각과 비교하여 올라간 때를 모두 고른 것은 어느 것인가요?","options":[{"t":"오전 9시, 오전 11시","correct":true},{"t":"오전 8시, 오전 10시","mis":"M4-2-u5-X10"},{"t":"오전 7시","mis":"M4-2-u5-X12"},{"t":"오전 9시","mis":"M4-2-u5-X21"}],"explanation":["꺾은선그래프가 오른쪽 위로 올라간 곳을 찾아요.","8시에서 9시로, 10시에서 11시로 올라가요.","올라간 때는 오전 9시와 오전 11시예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#7','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C11',1,'mc','auto','「스스로 마무리하기」 — 지역별 도서관 수를 한눈에 비교하려면 어떤 그래프로 나타내면 좋을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 지역별 도서관 수를 한눈에 비교하려면 어떤 그래프로 나타내면 좋을까요?","options":[{"t":"그림그래프 또는 막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선을 넣은 꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["지역별 자료는 시간에 따른 자료가 아니에요.","목적은 지역끼리 한눈에 비교하는 거예요.","그림그래프나 막대그래프가 편리해요."],"asset":{"type":"picg","only":"table","head":"지역","cols":["광주","대전","부산","서울"],"counts":[24,25,47,188],"vh":"도서관 수","unit":"관","total":false,"title":"지역별 도서관 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#8','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C10',1,'mc','auto','「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. ④ 수집한 자료를 □(으)로 나타내고 해석합니다. □ 안에 알맞은 말은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],false,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 방법이에요. ④ 수집한 자료를 □(으)로 나타내고 해석합니다. □ 안에 알맞은 말은 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"주제","mis":"M4-2-u5-X21"},{"t":"항목","mis":"M4-2-u5-X21"},{"t":"방법","mis":"M4-2-u5-X21"}],"explanation":["① 주제 → ② 항목 → ③ 방법·수집 → ④ 꺾은선그래프로 나타내고 해석해요.","차례를 떠올려 빈칸을 채워요.","□ 안에 알맞은 말은 꺾은선그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#9','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 오전 9시의 체온은 몇 °C인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 오전 9시의 체온은 몇 °C인가요?","options":[{"t":"36.6 °C","correct":true},{"t":"36.7 °C","mis":"M4-2-u5-X02"},{"t":"6 °C","mis":"M4-2-u5-X05"},{"t":"36.5 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 9시의 점을 따라 세로 눈금을 읽어요.","오전 9시의 체온은 36.6 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#10','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C6',2,'mc','auto','「스스로 마무리하기」 — 영화관 관람객 수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 영화관 관람객 수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?","options":[{"t":"0부터 1650명 사이","correct":true},{"t":"1700명과 1750명 사이","mis":"M4-2-u5-X09"},{"t":"1800명보다 위","mis":"M4-2-u5-X09"},{"t":"0부터 1800명 사이","mis":"M4-2-u5-X09"}],"explanation":["가장 작은 값은 1650명이에요.","물결선은 0과 가장 작은 값 사이에 넣어요.","0부터 1650명 사이에 넣어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4","5","6","7","8"],"counts":[1800,1700,1750,1650,1700],"vh":"관람객 수","unit":"명","total":false,"title":"월별 영화관에 방문한 관람객 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#11','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',2,'sa','auto','「스스로 마무리하기」 — 해바라기의 키는 9월에 7월보다 몇 cm 더 큰가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"「스스로 마무리하기」 — 해바라기의 키는 9월에 7월보다 몇 cm 더 큰가요? 숫자로 쓰세요.","answer":["7"],"explanation":["7월은 183 cm, 9월은 190 cm예요.","두 달의 값만 써서 빼요.","190 − 183 = 7 — 7 cm 더 커요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[180,183,186,190,193]}],"step":1,"ymax":194,"ylab":"(cm)","xlab":"(월)","y0":180,"wave":true,"every":5,"title":"월별 해바라기의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#12','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C9',2,'mc','auto','「스스로 마무리하기」 — 전월과 비교하여 자외선 지수 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],false,'{"seq":12,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 전월과 비교하여 자외선 지수 높음 일수가 가장 많이 늘어난 때는 몇 월인가요?","options":[{"t":"9월","correct":true},{"t":"5월","mis":"M4-2-u5-X12"},{"t":"6월","mis":"M4-2-u5-X10"},{"t":"7월","mis":"M4-2-u5-X21"}],"explanation":["늘어난 수: 7월 1일, 8월 1일, 9월 7일.","8월에서 9월로 가장 가파르게 올라가요.","가장 많이 늘어난 때는 9월이에요."],"asset":{"type":"lgraph","xs":["5","6","7","8","9"],"series":[{"vals":[12,5,6,7,14]}],"step":1,"ymax":15,"ylab":"(일)","xlab":"(월)","every":5,"title":"월별 자외선 지수 높음 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#13','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 태풍 발생 횟수가 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],false,'{"seq":13,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 태풍 발생 횟수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2018년부터 2019년까지","correct":true},{"t":"2020년부터 2021년까지","mis":"M4-2-u5-X13"},{"t":"2021년부터 2022년까지","mis":"M4-2-u5-X13"},{"t":"변하지 않은 때가 없어요.","mis":"M4-2-u5-X13"}],"explanation":["선분이 평평한 곳이 변하지 않은 때예요.","2018년과 2019년이 모두 29회예요.","2018년부터 2019년까지 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[29,29,23,22,25]}],"step":1,"ymax":30,"ylab":"(회)","xlab":"(년)","y0":20,"wave":true,"every":5,"title":"연도별 태풍 발생 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#14','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C12',2,'mc','auto','「스스로 마무리하기」 — 2022년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?',ARRAY['M4-2-u5-X19','M4-2-u5-X10']::text[],false,'{"seq":14,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 2022년은 전년도와 비교하여 폭염 일수와 한파 일수가 어떻게 변했나요?","options":[{"t":"폭염 일수는 줄어들고 한파 일수는 늘어났어요.","correct":true},{"t":"폭염 일수는 늘어나고 한파 일수는 줄어들었어요.","mis":"M4-2-u5-X19"},{"t":"모두 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"모두 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["폭염 일수는 22일에서 13일로, 한파 일수는 19일에서 31일로 바뀌었어요.","폭염 선은 내려가고 한파 선은 올라가요.","폭염 일수는 줄어들고 한파 일수는 늘어났어요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022"],"series":[{"name":"폭염 일수","vals":[16,10,22,13]},{"name":"한파 일수","vals":[11,9,19,31]}],"step":1,"ymax":32,"ylab":"(일)","xlab":"(년)","every":10,"title":"연도별 폭염 일수와 한파 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#15','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C3',2,'mc','auto','「스스로 마무리하기」 — 그래프를 보고 짐작하면 오후 2시 30분의 가로등의 그림자 길이는 약 몇 cm였을까요?',ARRAY['M4-2-u5-X04']::text[],false,'{"seq":15,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 그래프를 보고 짐작하면 오후 2시 30분의 가로등의 그림자 길이는 약 몇 cm였을까요?","options":[{"t":"약 70 cm","correct":true},{"t":"약 50 cm","mis":"M4-2-u5-X04"},{"t":"약 100 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["오후 2시는 50 cm, 오후 3시는 90 cm예요.","2시 30분은 두 시각의 한가운데예요.","약 70 cm였을 거예요."],"asset":{"type":"lgraph","xs":["1","2","3","4"],"series":[{"vals":[40,50,90,100]}],"step":10,"ymax":100,"ylab":"(cm)","xlab":"(시)","every":5,"title":"시각별 가로등의 그림자 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#16','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C12',2,'mc','auto','「스스로 마무리하기」 — 유소년층과 노년층 인구수의 차는 앞으로 어떻게 될까요?',ARRAY['M4-2-u5-X19','M4-2-u5-X25','M4-2-u5-X04']::text[],false,'{"seq":16,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 유소년층과 노년층 인구수의 차는 앞으로 어떻게 될까요?","options":[{"t":"점점 커질 것 — 두 선 사이의 간격이 해마다 넓어져서","correct":true},{"t":"점점 작아질 것","mis":"M4-2-u5-X19"},{"t":"변하지 않을 것","mis":"M4-2-u5-X25"},{"t":"알 수 없어요","mis":"M4-2-u5-X04"}],"explanation":["유소년층은 줄고 노년층은 늘어요.","두 선 사이의 간격이 해마다 넓어져요.","차는 점점 커질 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#17','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C2',3,'error','auto','「스스로 마무리하기」 — 월별 책 판매량 그래프를 보고 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X01','M4-2-u5-X21']::text[],false,'{"seq":17,"concept":"M4-2-u5-C2","difficulty":3,"kind":"error","stem":"「스스로 마무리하기」 — 월별 책 판매량 그래프를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「가로는 판매량, 세로는 월을 나타내.」","correct":true,"mis_target":"M4-2-u5-X01"},{"t":"하랑 — 「세로 눈금 5칸이 25권이니까 한 칸은 5권이야.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「8월의 책 판매량은 50권이야.」","mis":"M4-2-u5-X21"}],"explanation":["가로 눈금 아래에는 5, 6, 7, 8(월)이 적혀 있어요.","가로는 월, 세로는 판매량이에요.","은우는 가로와 세로를 바꾸어 썼어요."],"asset":{"type":"lgraph","xs":["5","6","7","8"],"series":[{"vals":[20,40,35,50]}],"step":5,"ymax":50,"ylab":"(권)","xlab":"(월)","every":5,"title":"월별 책 판매량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#18','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C4',3,'mc','auto','「스스로 마무리하기」 — 친구가 날짜별 꽃병의 물 높이를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07','M4-2-u5-X01']::text[],false,'{"seq":18,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 친구가 날짜별 꽃병의 물 높이를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금 한 칸을 1 cm로 정했어요.","mis":"M4-2-u5-X07"},{"t":"가로에 날짜를 나타냈어요.","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 점을 찍은 다음 선분으로 이어요.","점만 찍으면 변화가 잘 보이지 않아요.","점들을 순서대로 선분으로 이어야 해요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이","dots":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#19','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C9',3,'sa','auto','「스스로 마무리하기」 — 지유의 악기 연습 시간 그래프에서 전날과 비교하여 가장 많이 변화한 때에는 몇 분 변했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 지유의 악기 연습 시간 그래프에서 전날과 비교하여 가장 많이 변화한 때에는 몇 분 변했나요? 숫자로 쓰세요.","answer":["30"],"explanation":["변화: 10분 늘고, 0분, 20분 줄고, 30분 늘었어요.","모양만 보지 말고 수를 읽어요.","가장 많이 변화한 때는 5일, 30분이에요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[50,60,60,40,70]}],"step":2,"ymax":72,"ylab":"(분)","xlab":"(일)","y0":40,"wave":true,"every":5,"title":"지유의 날짜별 악기 연습 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#20','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C11',3,'mc','auto','「스스로 마무리하기」 — 수집 목적이 「월별 미세 먼지 발생 일수를 한눈에 비교하기 위함」일 때 알맞은 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X23','M4-2-u5-X03']::text[],false,'{"seq":20,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 수집 목적이 「월별 미세 먼지 발생 일수를 한눈에 비교하기 위함」일 때 알맞은 그래프는 어느 것인가요?","options":[{"t":"그림그래프 또는 막대그래프","correct":true},{"t":"꺾은선그래프 — 월별 자료는 언제나 꺾은선그래프라서","mis":"M4-2-u5-X23"},{"t":"물결선을 넣은 꺾은선그래프","mis":"M4-2-u5-X23"},{"t":"표로만 나타내야 해요","mis":"M4-2-u5-X03"}],"explanation":["월별 자료라도 수집 목적을 먼저 봐요.","목적은 한눈에 비교하는 거예요.","그림그래프나 막대그래프가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#21','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C5',3,'sa','auto','「스스로 마무리하기」 — 미세 먼지 나쁨 일수(가장 큰 값 25일)를 세로 눈금 한 칸이 1일인 그래프로 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 미세 먼지 나쁨 일수(가장 큰 값 25일)를 세로 눈금 한 칸이 1일인 그래프로 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.","answer":["25"],"explanation":["가장 큰 값은 25일이에요.","한 칸이 1일이므로 25칸이 필요해요.","적어도 25칸 있어야 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[20,21,25,5,18],"vh":"일수","unit":"일","total":false,"title":"연도별 미세 먼지 나쁨 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#22','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C7',3,'ox','auto','「스스로 마무리하기」 — 자료의 수량이 아주 큰 경우 공학 도구를 사용하여 그래프로 나타내면 편리해요.',ARRAY['M4-2-u5-X24']::text[],false,'{"seq":22,"concept":"M4-2-u5-C7","difficulty":3,"kind":"ox","stem":"「스스로 마무리하기」 — 자료의 수량이 아주 큰 경우 공학 도구를 사용하여 그래프로 나타내면 편리해요.","answer":"O","reason_options":[{"t":"정확한 수를 입력하면 값이 큰 자료도 쉽고 빠르게 나타낼 수 있어서","correct":true},{"t":"공학 도구는 자료를 대충 입력해도 똑같이 그려 줘서","mis":"M4-2-u5-X24"}],"mis":"M4-2-u5-X24","explanation":["다문화 가구 수처럼 값이 큰 자료는 손으로 그리기 어려워요.","이지통계 같은 공학 도구에 정확한 수를 입력해요.","쉽고 빠르게 꺾은선그래프로 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#23','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C11',4,'essay','teacher','「이 단원 학습을 마치고」 — 만화 속 친구들은 「1인당 하루 생활계 폐기물 발생량이 매년 증가하고 있다」는 것을 알리려고 최근 5년간의 자료를 모았어요. 막대그래프와 꺾은선그래프 가운데 어느 그래프로 나타내는 것이 좋을지 고르고, 그 이유와 자료를 모을 때 주의할 점을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u5-C11","difficulty":4,"kind":"essay","stem":"「이 단원 학습을 마치고」 — 만화 속 친구들은 「1인당 하루 생활계 폐기물 발생량이 매년 증가하고 있다」는 것을 알리려고 최근 5년간의 자료를 모았어요. 막대그래프와 꺾은선그래프 가운데 어느 그래프로 나타내는 것이 좋을지 고르고, 그 이유와 자료를 모을 때 주의할 점을 써 보세요.","answer_guide":{"answer":"예: 꺾은선그래프가 좋다. 막대그래프도 틀린 것은 아니지만 꺾은선그래프가 시간에 따른 변화를 알아보기 쉽기 때문이다. 자료는 인터넷에서 믿을 수 있는 누리집의 최근 자료를 모으고 출처를 적어야 한다.","scoring_points":["꺾은선그래프를 골랐는가","막대도 틀린 것은 아니지만 변화가 더 잘 보인다고 썼는가","믿을 수 있는 곳·최근 자료·출처를 썼는가"]},"explanation":["매년 증가하는 변화를 알리려는 목적이에요.","꺾은선그래프가 시간에 따른 변화를 알아보기 쉬워요.","믿을 수 있는 곳의 최근 자료를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#24','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C12',4,'sa','auto','「스스로 마무리하기」 — 유소년층과 노년층 인구수의 차는 2018년부터 2022년까지 몇만 명 커졌나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u5-C12","difficulty":4,"kind":"sa","stem":"「스스로 마무리하기」 — 유소년층과 노년층 인구수의 차는 2018년부터 2022년까지 몇만 명 커졌나요? 숫자로 쓰세요.","answer":["210"],"explanation":["2018년의 차는 100만 명이에요.","2022년의 차는 310만 명이에요.","310 − 100 = 210 — 210만 명 커졌어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_c#25','math',4,2,'u5','','tb_g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',4,'mc','auto','「수학에 퐁당」 — 컵의 무게 그래프에서 컵의 무게가 가장 많이 늘어난 때는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X13','M4-2-u5-X22']::text[],false,'{"seq":25,"concept":"M4-2-u5-C8","difficulty":4,"kind":"mc","stem":"「수학에 퐁당」 — 컵의 무게 그래프에서 컵의 무게가 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"오전 10시 10분","correct":true},{"t":"오전 10시 20분","mis":"M4-2-u5-X12"},{"t":"오전 10시 25분","mis":"M4-2-u5-X13"},{"t":"오전 10시 15분","mis":"M4-2-u5-X22"}],"explanation":["늘어난 무게: 10분 0.4 g, 15분 0.3 g, 20분 0.3 g, 25분 0 g.","오전 10시 5분에서 10분으로 가장 가파르게 올라가요.","가장 많이 늘어난 때는 오전 10시 10분이에요."],"asset":{"type":"lgraph","xs":["5","10","15","20","25"],"series":[{"vals":[221.5,221.9,222.2,222.5,222.5]}],"step":0.1,"ymax":222.6,"ylab":"(g)","xlab":"(분)","y0":221.5,"wave":true,"every":5,"title":"시각별 컵의 무게"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#1','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C1',1,'mc','auto','「스스로 마무리하기」 — 그래프를 보고 알맞은 말을 고르세요. 이 그래프처럼 시간에 따라 변화하는 양을 점으로 표시하고 선분으로 이은 그래프는 무엇인가요?',ARRAY['M4-2-u5-X03']::text[],false,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 그래프를 보고 알맞은 말을 고르세요. 이 그래프처럼 시간에 따라 변화하는 양을 점으로 표시하고 선분으로 이은 그래프는 무엇인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["월별 식물의 키를 점으로 표시했어요.","점들을 선분으로 이었어요.","꺾은선그래프예요."],"asset":{"type":"lgraph","xs":["4","5","6","7"],"series":[{"vals":[4,9,17,21]}],"step":1,"ymax":22,"ylab":"(cm)","xlab":"(월)","every":5,"title":"월별 식물의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#2','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C2',1,'sa','auto','「확인 문제」 — 3일의 꽃병의 물 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"sa","stem":"「확인 문제」 — 3일의 꽃병의 물 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["세로 눈금 한 칸은 1 cm예요.","3일의 점을 따라 세로 눈금을 읽어요.","3일의 꽃병의 물 높이는 13 cm예요."],"asset":{"type":"lgraph","xs":["1","2","3","4","5"],"series":[{"vals":[17,15,13,10,8]}],"step":1,"ymax":18,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 꽃병의 물 높이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#3','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C2',1,'mc','auto','「스스로 마무리하기」 — 「시각별 컵의 무게」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],false,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 「시각별 컵의 무게」 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 무게","correct":true},{"t":"가로: 무게, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 무게, 세로: 무게","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각을, 세로에는 무게를 g 단위로 나타냈어요.","가로: 시각, 세로: 무게예요."],"asset":{"type":"lgraph","xs":["5","10","15","20","25"],"series":[{"vals":[221.5,221.9,222.2,222.5,222.5]}],"step":0.1,"ymax":222.6,"ylab":"(g)","xlab":"(분)","y0":221.5,"wave":true,"every":5,"title":"시각별 컵의 무게"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#4','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C5',1,'mc','auto','「스스로 마무리하기」 — 인구수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 세로 눈금 한 칸을 몇만 명으로 정하면 좋을까요?',ARRAY['M4-2-u5-X08','M4-2-u5-X07','M4-2-u5-X02']::text[],false,'{"seq":4,"concept":"M4-2-u5-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 인구수 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 세로 눈금 한 칸을 몇만 명으로 정하면 좋을까요?","options":[{"t":"1만 명","correct":true},{"t":"10만 명","mis":"M4-2-u5-X08"},{"t":"3만 명","mis":"M4-2-u5-X07"},{"t":"31만 명","mis":"M4-2-u5-X02"}],"explanation":["자료의 값은 31, 34, 36, 37, 38만 명이에요.","한 칸을 1만 명으로 하면 모든 값이 눈금 위에 와요.","세로 눈금 한 칸은 1만 명이 좋아요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[31,34,36,37,38],"vh":"인구수","unit":"만 명","total":false,"title":"연도별 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#5','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',1,'sa','auto','「스스로 마무리하기」 — 폭염 일수가 가장 많았던 때는 몇 년인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 폭염 일수가 가장 많았던 때는 몇 년인가요? 숫자로 쓰세요.","answer":["2023"],"explanation":["가장 높이 있는 점을 찾아요.","2023년의 19일이 가장 많아요.","가장 많았던 때는 2023년이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#6','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',1,'mc','auto','「스스로 마무리하기」 — 서준이의 체온이 전 시각과 비교하여 내려간 때를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u5-X10','M4-2-u5-X21','M4-2-u5-X12']::text[],false,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 서준이의 체온이 전 시각과 비교하여 내려간 때를 모두 고른 것은 어느 것인가요?","options":[{"t":"오전 8시, 오전 10시","correct":true},{"t":"오전 9시, 오전 11시","mis":"M4-2-u5-X10"},{"t":"오전 10시","mis":"M4-2-u5-X21"},{"t":"오전 7시, 오전 10시","mis":"M4-2-u5-X12"}],"explanation":["꺾은선그래프가 오른쪽 아래로 내려간 곳을 찾아요.","7시에서 8시로, 9시에서 10시로 내려가요.","내려간 때는 오전 8시와 오전 10시예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#7','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C11',1,'mc','auto','「스스로 마무리하기」 — 강아지의 몸무게를 매월 1일마다 조사한 표예요. 몸무게의 변화를 나타내기에 가장 적절한 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],false,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 강아지의 몸무게를 매월 1일마다 조사한 표예요. 몸무게의 변화를 나타내기에 가장 적절한 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["몸무게는 시간에 따라 달라지는 자료예요.","목적은 변화를 알아보는 거예요.","꺾은선그래프가 가장 적절해요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["7","8","9","10","11"],"counts":[4,5,5,6,7],"vh":"몸무게","unit":"kg","total":false,"title":"월별 강아지의 몸무게"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#8','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C10',1,'mc','auto','「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 차례로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],false,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 자료를 수집하여 꺾은선그래프로 나타내는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 → 항목 → 수집 방법 → 꺾은선그래프로 나타내고 해석","correct":true},{"t":"꺾은선그래프 → 주제 → 항목 → 수집 방법","mis":"M4-2-u5-X21"},{"t":"항목 → 주제 → 꺾은선그래프 → 수집 방법","mis":"M4-2-u5-X21"},{"t":"수집 방법 → 꺾은선그래프 → 항목 → 주제","mis":"M4-2-u5-X21"}],"explanation":["먼저 조사하고 싶은 주제를 정해요.","주제에 따른 항목, 수집 방법을 정하고 자료를 모아요.","모은 자료를 꺾은선그래프로 나타내고 해석해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#9','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 오전 11시의 체온은 몇 °C인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X05']::text[],false,'{"seq":9,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 오전 11시의 체온은 몇 °C인가요?","options":[{"t":"36.4 °C","correct":true},{"t":"36.5 °C","mis":"M4-2-u5-X02"},{"t":"4 °C","mis":"M4-2-u5-X05"},{"t":"36.3 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 0.1 °C예요.","오전 11시의 점을 따라 세로 눈금을 읽어요.","오전 11시의 체온은 36.4 °C예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#10','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C6',2,'mc','auto','「스스로 마무리하기」 — 교실의 온도 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 교실의 온도 표를 물결선을 사용한 꺾은선그래프로 나타낼 때 물결선은 어디에 넣으면 좋을까요?","options":[{"t":"0부터 19 °C 사이","correct":true},{"t":"20 °C와 22 °C 사이","mis":"M4-2-u5-X09"},{"t":"23 °C보다 위","mis":"M4-2-u5-X09"},{"t":"0부터 23 °C 사이","mis":"M4-2-u5-X09"}],"explanation":["가장 작은 값은 19 °C예요.","물결선은 0과 가장 작은 값 사이에 넣어요.","0부터 19 °C 사이에 넣어요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["오전 9","오전 10","오전 11","낮 12","오후 1"],"counts":[19,20,20,22,23],"vh":"온도","unit":"°C","total":false,"title":"시각별 교실의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#11','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',2,'sa','auto','「스스로 마무리하기」 — 우유 생산량은 2022년에 2020년보다 몇만 톤 줄어들었나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"「스스로 마무리하기」 — 우유 생산량은 2022년에 2020년보다 몇만 톤 줄어들었나요? 숫자로 쓰세요.","answer":["11"],"explanation":["2020년은 209만 톤, 2022년은 198만 톤이에요.","두 해의 값만 써서 빼요.","209 − 198 = 11 — 11만 톤 줄어들었어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[204,205,209,203,198]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","y0":195,"wave":true,"every":5,"title":"연도별 우리나라의 우유 생산량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#12','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C9',2,'mc','auto','「스스로 마무리하기」 — 전년도와 비교하여 폭염 일수가 가장 많이 늘어난 때는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X10','M4-2-u5-X21']::text[],false,'{"seq":12,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 전년도와 비교하여 폭염 일수가 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2021년","correct":true},{"t":"2023년","mis":"M4-2-u5-X12"},{"t":"2020년","mis":"M4-2-u5-X10"},{"t":"2022년","mis":"M4-2-u5-X21"}],"explanation":["늘어난 수: 2021년 14일, 2023년 9일.","2020년에서 2021년으로 가장 가파르게 올라가요.","가장 많이 늘어난 때는 2021년이에요."],"asset":{"type":"lgraph","xs":["2019","2020","2021","2022","2023"],"series":[{"vals":[15,4,18,10,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","every":5,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#13','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',2,'mc','auto','「스스로 마무리하기」 — 1인당 쌀 소비량이 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],false,'{"seq":13,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 1인당 쌀 소비량이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2021년부터 2022년까지","correct":true},{"t":"2018년부터 2019년까지","mis":"M4-2-u5-X13"},{"t":"2019년부터 2020년까지","mis":"M4-2-u5-X13"},{"t":"변하지 않은 때가 없어요.","mis":"M4-2-u5-X13"}],"explanation":["선분이 평평한 곳이 변하지 않은 때예요.","2021년과 2022년이 모두 57 kg이에요.","2021년부터 2022년까지 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[61,59,58,57,57]}],"step":1,"ymax":62,"ylab":"(kg)","xlab":"(년)","y0":55,"wave":true,"every":5,"title":"연도별 1인당 쌀 소비량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#14','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C12',2,'mc','auto','「스스로 마무리하기」 — 노년층 인구수가 전년도와 비교하여 가장 많이 늘어난 때는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X22','M4-2-u5-X21']::text[],false,'{"seq":14,"concept":"M4-2-u5-C12","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 노년층 인구수가 전년도와 비교하여 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2022년","mis":"M4-2-u5-X12"},{"t":"2021년","mis":"M4-2-u5-X22"},{"t":"2019년","mis":"M4-2-u5-X21"}],"explanation":["노년층의 늘어난 수: 30만, 50만, 40만, 30만 명.","2019년에서 2020년으로 가장 가파르게 올라가요.","가장 많이 늘어난 때는 2020년이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#15','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C3',2,'mc','auto','「스스로 마무리하기」 — 그래프를 보고 짐작하면 오전 9시 30분의 온실 안의 온도는 약 몇 °C였을까요?',ARRAY['M4-2-u5-X04']::text[],false,'{"seq":15,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 — 그래프를 보고 짐작하면 오전 9시 30분의 온실 안의 온도는 약 몇 °C였을까요?","options":[{"t":"약 21.5 °C","correct":true},{"t":"약 21 °C","mis":"M4-2-u5-X04"},{"t":"약 22 °C","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["오전 9시는 21 °C, 오전 10시는 22 °C예요.","9시 30분은 두 시각의 한가운데예요.","약 21.5 °C였을 거예요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[20.0,20.5,21.0,22.0,20.5]}],"step":0.1,"ymax":22.2,"ylab":"(°C)","xlab":"(시)","y0":20.0,"wave":true,"every":5,"title":"시각별 온실 안의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#16','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C9',2,'mc','auto','「이런 활동도 있어요」 — 양파 싹의 길이를 28일에 잰다면 어떻게 될까요?',ARRAY['M4-2-u5-X10','M4-2-u5-X25','M4-2-u5-X04']::text[],false,'{"seq":16,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"「이런 활동도 있어요」 — 양파 싹의 길이를 28일에 잰다면 어떻게 될까요?","options":[{"t":"더 길어질 것 — 전체적으로 오른쪽 위로 올라가고 있어서","correct":true},{"t":"짧아질 것","mis":"M4-2-u5-X10"},{"t":"변하지 않을 것 — 1일과 7일 사이가 짧아서","mis":"M4-2-u5-X25"},{"t":"알 수 없어요","mis":"M4-2-u5-X04"}],"explanation":["1일부터 25일까지 전체 흐름을 봐요.","양파 싹의 길이는 점점 길어지고 있어요.","28일에는 더 길어질 것 같아요."],"asset":{"type":"lgraph","xs":["1","7","13","19","25"],"series":[{"vals":[0,3,7,15,24]}],"step":1,"ymax":25,"ylab":"(cm)","xlab":"(일)","every":5,"title":"날짜별 양파 싹의 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#17','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C12',3,'error','auto','「스스로 마무리하기」 — 유소년층과 노년층 인구수 그래프를 보고 잘못 해석한 친구는 누구인가요?',ARRAY['M4-2-u5-X19','M4-2-u5-X21']::text[],false,'{"seq":17,"concept":"M4-2-u5-C12","difficulty":3,"kind":"error","stem":"「스스로 마무리하기」 — 유소년층과 노년층 인구수 그래프를 보고 잘못 해석한 친구는 누구인가요?","options":[{"t":"채원 — 「유소년층 인구수는 점점 늘어나고 노년층 인구수는 점점 줄어들고 있어.」","correct":true,"mis_target":"M4-2-u5-X19"},{"t":"도윤 — 「2018년에 노년층 인구수는 유소년층 인구수보다 100만 명 더 많아.」","mis":"M4-2-u5-X21"},{"t":"지유 — 「노년층 인구수가 전년도와 비교하여 가장 많이 늘어난 때는 2020년이야.」","mis":"M4-2-u5-X21"}],"explanation":["이름표를 보고 두 선을 먼저 가려요.","유소년층은 줄고 노년층은 늘어나요.","채원이는 두 선을 바꾸어 읽었어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층 인구수","vals":[650,640,630,610,590]},{"name":"노년층 인구수","vals":[750,780,830,870,900]}],"step":10,"ymax":900,"ylab":"(만 명)","xlab":"(년)","y0":590,"wave":true,"every":5,"title":"연도별 유소년층과 노년층 인구수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#18','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C4',3,'mc','auto','「스스로 마무리하기」 — 친구가 월별 해바라기의 키를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?',ARRAY['M4-2-u5-X09','M4-2-u5-X07','M4-2-u5-X06']::text[],false,'{"seq":18,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 친구가 월별 해바라기의 키를 꺾은선그래프로 나타냈어요. 잘못 나타낸 점은 무엇인가요?","options":[{"t":"점을 가로 눈금의 순서대로 잇지 않았어요.","correct":true},{"t":"물결선을 0과 180 사이에 넣었어요.","mis":"M4-2-u5-X09"},{"t":"세로 눈금 한 칸을 1 cm로 정했어요.","mis":"M4-2-u5-X07"},{"t":"점만 찍고 잇지 않았어요.","mis":"M4-2-u5-X06"}],"explanation":["점은 6월, 7월, 8월, 9월, 10월 순서대로 이어야 해요.","7월과 8월의 순서를 바꾸어 이었어요.","물결선과 한 칸 1 cm는 바르게 정했어요."],"asset":{"type":"lgraph","xs":["6","7","8","9","10"],"series":[{"vals":[180,183,186,190,193]}],"step":1,"ymax":194,"ylab":"(cm)","xlab":"(월)","y0":180,"wave":true,"every":5,"title":"월별 해바라기의 키","order":[0,2,1,3,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#19','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C9',3,'sa','auto','「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈을 때 전년도와 비교하여 가장 많이 변한 때에는 몇만 회 변했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 국제선 운항 횟수 표를 꺾은선그래프로 나타냈을 때 전년도와 비교하여 가장 많이 변한 때에는 몇만 회 변했나요? 숫자로 쓰세요.","answer":["36"],"explanation":["변화: 4만 회 늘고, 3만 회 늘고, 36만 회 줄고, 4만 회 줄었어요.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 2020년, 36만 회예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[46,50,53,17,13],"vh":"횟수","unit":"만 회","total":false,"title":"연도별 국제선 운항 횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#20','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C11',3,'mc','auto','「스스로 마무리하기」 — 같은 수온 값을 보고 나타낸 두 꺾은선그래프의 모양이 달라요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X22','M4-2-u5-X20','M4-2-u5-X05']::text[],false,'{"seq":20,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 같은 수온 값을 보고 나타낸 두 꺾은선그래프의 모양이 달라요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"세로 눈금 한 칸의 크기와 눈금의 수에 따라 다르게 보이니 수를 정확하게 읽어야 해요.","correct":true},{"t":"가파른 그래프의 수온이 더 많이 내려갔어요.","mis":"M4-2-u5-X22"},{"t":"하나는 틀린 그래프예요.","mis":"M4-2-u5-X20"},{"t":"물결선이 있는 쪽 수온이 더 낮아요.","mis":"M4-2-u5-X05"}],"explanation":["두 그래프는 같은 값을 나타내요.","눈금 한 칸과 눈금 수에 따라 모양이 달라 보여요.","모양보다 수를 정확하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#21','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C5',3,'sa','auto','「스스로 마무리하기」 — 폭염 일수(가장 큰 값 19일)를 세로 눈금 한 칸이 1일인 그래프로 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 폭염 일수(가장 큰 값 19일)를 세로 눈금 한 칸이 1일인 그래프로 나타내려면 세로 눈금이 적어도 몇 칸 있어야 하나요? 숫자로 쓰세요.","answer":["19"],"explanation":["가장 큰 값은 2023년의 19일이에요.","한 칸이 1일이므로 19칸이 필요해요.","적어도 19칸 있어야 해요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2019","2020","2021","2022","2023"],"counts":[15,4,18,10,19],"vh":"일수","unit":"일","total":false,"title":"연도별 폭염 일수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#22','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C12',3,'ox','auto','「스스로 마무리하기」 — 두 개의 자료를 하나의 꺾은선그래프로 나타낼 때는 선분의 색을 다르게 하여 구분해요.',ARRAY['M4-2-u5-X19']::text[],false,'{"seq":22,"concept":"M4-2-u5-C12","difficulty":3,"kind":"ox","stem":"「스스로 마무리하기」 — 두 개의 자료를 하나의 꺾은선그래프로 나타낼 때는 선분의 색을 다르게 하여 구분해요.","answer":"O","reason_options":[{"t":"두 자료를 구분해야 연도별 변화를 한눈에 비교할 수 있어서","correct":true},{"t":"두 자료를 한 선으로 이어야 해서","mis":"M4-2-u5-X19"}],"mis":"M4-2-u5-X19","explanation":["두 자료를 같은 연도에 함께 나타내요.","선분의 색을 다르게 하고 이름표를 붙여요.","두 자료의 변화를 한눈에 비교하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#23','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C1',4,'essay','teacher','「나의 성장 기록」 — 생활 속에서 꺾은선그래프를 본 경험을 쓰고, 단원 핵심 질문 「시간에 따른 변화를 알아보기 쉽도록 어떻게 나타낼까요?」에 대한 나의 답을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u5-C1","difficulty":4,"kind":"essay","stem":"「나의 성장 기록」 — 생활 속에서 꺾은선그래프를 본 경험을 쓰고, 단원 핵심 질문 「시간에 따른 변화를 알아보기 쉽도록 어떻게 나타낼까요?」에 대한 나의 답을 써 보세요.","answer_guide":{"answer":"예: 날씨 정보에서 기온 변화를 나타낸 꺾은선그래프를 본 적이 있다. 시간에 따른 변화를 알아보기 쉽도록 하려면 변화하는 양을 점으로 표시하고 그 점들을 선분으로 이은 꺾은선그래프로 나타내고, 필요하면 물결선을 사용한다.","scoring_points":["생활 속 꺾은선그래프 경험을 썼는가","꺾은선그래프로 나타낸다고 답했는가","점·선분(또는 물결선·눈금)으로 나타내는 방법을 썼는가"]},"explanation":["뉴스·날씨 정보에서 꺾은선그래프를 자주 써요.","시간에 따른 변화는 꺾은선그래프로 나타내요.","필요하면 물결선을 써서 변화를 뚜렷하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#24','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',4,'sa','auto','「스스로 마무리하기」 — 유적지의 관람객 수는 2022년에 2018년보다 몇만 명 적은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"「스스로 마무리하기」 — 유적지의 관람객 수는 2022년에 2018년보다 몇만 명 적은가요? 숫자로 쓰세요.","answer":["34"],"explanation":["2018년은 1224만 명, 2022년은 1190만 명이에요.","두 해의 값만 써서 빼요.","1224 − 1190 = 34 — 34만 명 적어요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2018","2019","2020","2021","2022"],"counts":[1224,1452,590,754,1190],"vh":"관람객 수","unit":"만 명","total":false,"title":"연도별 유적지의 관람객 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u5_review_d#25','math',4,2,'u5','','tb_g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',4,'mc','auto','「스스로 마무리하기」 — 서준이의 체온은 오전 7시부터 오전 11시까지 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X13','M4-2-u5-X10']::text[],false,'{"seq":25,"concept":"M4-2-u5-C8","difficulty":4,"kind":"mc","stem":"「스스로 마무리하기」 — 서준이의 체온은 오전 7시부터 오전 11시까지 어떻게 변하고 있나요?","options":[{"t":"내려갔다가 올라갔다가를 반복하고 있어요.","correct":true},{"t":"계속 내려가고 있어요.","mis":"M4-2-u5-X13"},{"t":"계속 올라가고 있어요.","mis":"M4-2-u5-X10"},{"t":"변하지 않아요.","mis":"M4-2-u5-X13"}],"explanation":["7시→8시 내려감, 8시→9시 올라감.","9시→10시 내려감, 10시→11시 올라감.","내려갔다가 올라갔다가를 반복해요."],"asset":{"type":"lgraph","xs":["7","8","9","10","11"],"series":[{"vals":[36.7,36.5,36.6,36.3,36.4]}],"step":0.1,"ymax":36.8,"ylab":"(°C)","xlab":"(시)","y0":36.0,"wave":true,"every":5,"title":"시각별 서준이의 체온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
